//! AppController integration tests: the full editing workflows driven
//! through the controller API (draw → dimension → carve → exposure →
//! phases → persist/reload), pinned against an in-memory SQLite DB.
use super::*;

/// R3 regression: `activate_shape` with the CURRENT shape as target is a
/// no-op — its early-return must NOT clear transient interaction state.
/// (Switching to a *different* shape does clear it; this pins the no-switch
/// path so the document extraction can't silently change that behaviour.)
#[test]
fn activate_shape_same_target_is_a_noop_for_transient_state() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    assert_eq!(c.document.active, ActiveShape::Outline); // default active shape
                                                         // Seed transient state that a real shape-switch would clear.
    c.pending_cut = Some((
        SubareaFlow::LivingArea,
        [ShapeSlot::default(), ShapeSlot::default()],
    ));
    c.document.edit_state.dragging = true;
    // Re-activating the SAME shape must leave it all intact.
    c.activate_shape(ActiveShape::Outline);
    assert!(
        c.pending_cut.is_some(),
        "activate_shape(current) must not clear pending_cut"
    );
    assert!(
        c.document.edit_state.dragging,
        "activate_shape(current) must not reset edit_state"
    );
}

/// The assessor's flow: draw a square, trim a corner, then zero the two
/// remnant cut walls so the cuts snap onto corners — leaving a triangle.
/// Exercises the real controller path: `compute_next_dimension_prompt`
/// picks each axis-aligned remnant wall, and `apply_dimension(0.0)`
/// collapses it (the diagonal cut wall is never offered).
#[test]
fn trim_corner_then_zero_remnants_makes_a_triangle() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());

    // A 10x10 square (5th point is the lift-near-start drag point).
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    // Treat it as fully dimensioned: scale set, both square params known.
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();

    // Trim off the top-right corner: right edge at y=5 to top edge at x=5.
    c.document
        .floor_plan
        .trim_by_stroke(&[Point2f32::new(10.0, 5.0), Point2f32::new(5.0, 10.0)])
        .unwrap();
    assert_eq!(
        c.document.floor_plan.polygons()[0].len(),
        5,
        "corner cut should leave a pentagon"
    );

    // Zero the two remnant cut walls. Each apply_dimension(0.0) collapses
    // one cut vertex; the diagonal is never prompted (non-axis-aligned).
    for step in 0..2 {
        c.compute_next_dimension_prompt();
        assert!(
            c.document.dimensioning.current_prompt.is_some(),
            "expected a promptable remnant wall at step {step}"
        );
        c.apply_dimension(0.0)
            .unwrap_or_else(|e| panic!("zero-collapse failed at step {step}: {e}"));
    }

    let ring = &c.document.floor_plan.polygons()[0];
    assert_eq!(
        ring.len(),
        3,
        "zeroing both remnants should yield a triangle"
    );
    assert!(c.document.floor_plan.validate_simple().is_ok());
    // The triangle is the square minus the cut corner: (0,0),(10,0),(0,10).
    for corner in [(0.0, 0.0), (10.0, 0.0), (0.0, 10.0)] {
        assert!(
            ring.iter()
                .any(|p| (p.x - corner.0).abs() < 1e-3 && (p.y - corner.1).abs() < 1e-3),
            "triangle should keep corner {corner:?}"
        );
    }
}

/// Tap-to-copy invariant behind the dimension-entry wall tap: the canvas only
/// offers LABELLED walls — `walls_with_known_length()` — as copy sources, so
/// the wall currently being ASKED about (its length is the unknown) must
/// never appear in that list at any point of the loop. That is the whole
/// no-self-insert rule: the prompted wall carries no label, so a tap on it
/// finds no candidate. Also pins the feature's precondition — once the first
/// dimension lands, known walls DO coexist with the still-open prompt (there
/// is something to copy from mid-loop).
#[test]
fn prompted_wall_is_never_a_known_length_copy_source() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    // Freshly captured (pixel-space, nothing dimensioned yet).
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.compute_next_dimension_prompt();
    assert!(c.dimensioning_active(), "fresh outline starts prompting");
    // Before any dimension lands nothing is known — no copy sources at all.
    assert!(
        c.walls_with_known_length().is_empty(),
        "no labels (and so no tap-copy sources) before the first dimension"
    );

    let mut applied = 0;
    while let Some(prompt) = c.current_dimension_prompt() {
        assert!(applied < 12, "dimension loop didn't terminate");
        let (ring, edge) = c
            .document
            .floor_plan
            .find_vertex(prompt.wall_start_vertex)
            .expect("prompted wall exists in the plan");
        assert!(
            !c.walls_with_known_length().contains(&(ring, edge)),
            "the prompted wall must never be offered as a copy source \
             (iteration {applied})"
        );
        if applied > 0 {
            assert!(
                !c.walls_with_known_length().is_empty(),
                "once a dimension landed, known walls coexist with the open \
                 prompt — the mid-loop tap has sources (iteration {applied})"
            );
        }
        c.apply_dimension(4.0).expect("dimension applies");
        applied += 1;
    }
    assert!(applied >= 2, "a square asks for at least width and height");
    // Loop done: every outline wall's length is known → all are copyable.
    assert!(!c.walls_with_known_length().is_empty());
}

/// The field report behind the label set (dump 07-13T1633): while a PHASE
/// CARVE was being dimensioned, only "some" walls were labelled — the live
/// buffer held the carve's little ring, so `walls_with_known_length`'s
/// indices landed on the wrong polygon, and the settled outline (including
/// "the full length on the right side") was offered nowhere. The genuine bug
/// was the cross-application of indices; the fix keeps `walls_with_known_length`
/// computed on the OUTLINE slot. Contract is CONFIRMED-only (user correction,
/// 07-14): every SET outline wall is a labelled copy source — the right side
/// among them, since it was a real dimension — but the not-yet-set carve
/// walls carry no label (their length is still a guess). The prompted wall
/// stays excluded.
#[test]
fn carve_dimensioning_offers_confirmed_outline_walls_as_copy_source() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    // 2x2 dimensioned storey outline.
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(2.0, 0.0),
        Point2f32::new(2.0, 2.0),
        Point2f32::new(0.0, 2.0),
        Point2f32::new(0.05, 0.05),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.1, true).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.sync_active();
    // No labels outside a prompt — the copy set is prompt-scoped.
    assert!(c.copyable_wall_labels().is_empty(), "no prompt, no labels");

    let mut phases = ConstructionPhases::default();
    phases.set_year(ConstructionPhase::Extension1, 2008);
    c.set_construction_phases(phases);
    // Interior ~0.9m phase carve → its dimension loop opens.
    c.set_phase_mode(true);
    c.apply_phase_region_stroke_event(&[
        (0.5, 0.5),
        (1.4, 0.5),
        (1.4, 1.4),
        (0.5, 1.4),
        (0.55, 0.55),
    ]);
    assert!(c.dimensioning_active(), "carve prompts to be dimensioned");

    let labels = c.copyable_wall_labels();
    // All FOUR settled outline walls are copy sources — including the right
    // side's full length, the one the assessor couldn't select.
    let outline_walls = labels
        .iter()
        .filter(|(_, _, len)| (len - 2.0).abs() < 1e-2)
        .count();
    assert_eq!(
        outline_walls, 4,
        "every CONFIRMED outline wall carries a label: {labels:?}"
    );
    assert!(
        labels.iter().any(|(a, b, len)| (a.0 - 2.0).abs() < 1e-3
            && (b.0 - 2.0).abs() < 1e-3
            && (len - 2.0).abs() < 1e-2),
        "the right side (x = 2) is offered at its full length: {labels:?}"
    );
    // Confirmed-only: the carve's walls are NOT yet set (a free interior carve
    // shares none with the outline, so nothing is known on it), so its
    // placeholder ~0.9 m lengths are never shown or copyable — exactly the
    // four outline walls remain, nothing else.
    assert_eq!(
        labels.len(),
        4,
        "only the confirmed outline walls — no unset/derived lengths: {labels:?}"
    );
    // …and the prompted wall itself is never a source (no self-insert).
    let prompt = c.current_dimension_prompt().expect("prompt open");
    let (pa, pb) = c
        .document
        .floor_plan
        .wall_endpoints(prompt.wall_start_vertex)
        .expect("prompted wall resolves");
    let close = |s: (f64, f64), p: Point2f32| {
        (s.0 - p.x as f64).abs() < 1e-3 && (s.1 - p.y as f64).abs() < 1e-3
    };
    assert!(
        labels.iter().all(
            |(a, b, _)| !((close(*a, pa) && close(*b, pb)) || (close(*a, pb) && close(*b, pa)))
        ),
        "the prompted wall must not be a copy source: {labels:?}"
    );
    // The confirmed-label indices point at the OUTLINE regions again — while
    // the carve is active they used to index its little ring instead (the
    // "random labels" bug — kept fixed).
    let known = c.walls_with_known_length();
    assert_eq!(known.len(), 4, "all outline edges known: {known:?}");
    assert!(known.iter().all(|(r, _)| *r == 0));
}

/// The OUTLINE's own loop, confirmed-only (user correction, 07-14): before the
/// scale is set nothing is labelled (pixel numbers are meaningless); after the
/// first applied dimension, only the CONFIRMED walls carry a label — the
/// just-set axis's pair — while the not-yet-asked axis (the prompted wall +
/// its equivalent) stays unlabelled until it's entered.
#[test]
fn outline_mid_loop_labels_only_confirmed_walls() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.compute_next_dimension_prompt();
    assert!(c.dimensioning_active());
    assert!(
        c.copyable_wall_labels().is_empty(),
        "pixel-space plan: no copy labels before the scale is set"
    );

    c.apply_dimension(4.0).expect("first dimension sets scale");
    assert!(c.dimensioning_active(), "the other axis is still asked");
    let labels = c.copyable_wall_labels();
    assert_eq!(
        labels.len(),
        2,
        "only the just-confirmed axis's pair is labelled; the unset axis \
         (prompted wall + equivalent) is hidden: {labels:?}"
    );
    assert!(
        labels.iter().all(|(_, _, len)| (len - 4.0).abs() < 1e-2),
        "labels show the confirmed metric length: {labels:?}"
    );
}

/// Zeroing a regular (orthogonal) wall is rejected — only a trim cut wall
/// can be collapsed. Guards against silently deleting a drawn wall.
#[test]
fn zero_rejected_for_a_regular_wall() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    // Scaled, but no walls dimensioned yet — so a plain orthogonal wall is
    // promptable. (No trim, so no diagonal cut edge anywhere.)
    c.document.dimensioning.scale_set = true;
    c.compute_next_dimension_prompt();
    assert!(c.document.dimensioning.current_prompt.is_some());

    let err = c
        .apply_dimension(0.0)
        .expect_err("0 on a regular wall must be rejected");
    assert!(err.contains("trim cut"), "unexpected error: {err}");
    // Shape untouched.
    assert_eq!(c.document.floor_plan.polygons()[0].len(), 4);
}

/// After a corner trim there are 3 undimensioned segments (2 axis-aligned
/// remnants + the diagonal cut) but only 2 degrees of freedom. The assessor
/// must be able to dimension ANY two — including the diagonal — since in the
/// field they may only be able to measure certain ones. This sets one
/// remnant, then dimensions the diagonal itself, and checks the diagonal
/// ends up the requested length.
#[test]
fn diagonal_cut_wall_is_dimensionable() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();

    // Trim the top-right corner: right edge at y=5 to top edge at x=5.
    c.document
        .floor_plan
        .trim_by_stroke(&[Point2f32::new(10.0, 5.0), Point2f32::new(5.0, 10.0)])
        .unwrap();

    // Set the first prompted (axis-aligned) remnant to a known length.
    c.compute_next_dimension_prompt();
    assert!(c.document.dimensioning.current_prompt.is_some());
    c.apply_dimension(4.0).expect("set first remnant");

    // Now cycle prompts to the diagonal (non-axis-aligned), skipping any
    // remaining axis-aligned remnant, and dimension it to 7.0.
    let mut dimensioned_diagonal = false;
    for _ in 0..5 {
        c.compute_next_dimension_prompt();
        let Some(prompt) = c.document.dimensioning.current_prompt.clone() else {
            break;
        };
        let (ring, edge) = c
            .document
            .floor_plan
            .find_vertex(prompt.wall_start_vertex)
            .unwrap();
        if c.document.floor_plan.wall_axis(ring, edge).is_none() {
            c.apply_dimension(7.0).expect("dimension the diagonal");
            dimensioned_diagonal = true;
            break;
        }
        c.skip_current_dimension();
    }
    assert!(
        dimensioned_diagonal,
        "the diagonal cut wall should be offered and settable"
    );

    // Verify the polygon's one diagonal edge is ~7.0 long.
    let ring = &c.document.floor_plan.polygons()[0];
    let n = ring.len();
    let mut diag_len = None;
    for i in 0..n {
        let a = ring[i];
        let b = ring[(i + 1) % n];
        if (a.x - b.x).abs() > 1e-3 && (a.y - b.y).abs() > 1e-3 {
            diag_len = Some(((a.x - b.x).powi(2) + (a.y - b.y).powi(2)).sqrt());
        }
    }
    let diag_len = diag_len.expect("a diagonal edge");
    assert!(
        (diag_len - 7.0).abs() < 1e-2,
        "diagonal should be 7.0, got {diag_len}"
    );
    assert!(c.document.floor_plan.validate_simple().is_ok());
}

/// The TrimOrtho tool routes to the orthogonal-polygon trim: a stepped cut
/// path carves a notch (area removed, extra vertices, stays orthogonal) —
/// not the straight line cut the plain Trim tool would attempt.
#[test]
fn trim_ortho_tool_carves_an_orthogonal_notch() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();

    let area = |c: &AppController| -> f32 {
        let r = &c.document.floor_plan.polygons()[0];
        let n = r.len();
        (0..n)
            .map(|i| {
                let (a, b) = (r[i], r[(i + 1) % n]);
                a.x * b.y - b.x * a.y
            })
            .sum::<f32>()
            .abs()
            * 0.5
    };
    let before = area(&c);

    c.set_edit_mode(EditTools::TrimOrtho);
    // Rectangular notch into the top edge (y=10), down to y=7, x in [3,7].
    let notch = vec![
        Point2f32::new(3.0, 10.0),
        Point2f32::new(3.0, 7.0),
        Point2f32::new(7.0, 7.0),
        Point2f32::new(7.0, 10.0),
    ];
    c.apply_trim_stroke(&notch)
        .expect("ortho trim should succeed");

    let after = area(&c);
    assert!(
        after < before,
        "notch should remove area ({after} vs {before})"
    );
    assert!(
        (before - after - 12.0).abs() < 1.0,
        "should remove ~12 (4x3); removed {}",
        before - after
    );
    let ring = &c.document.floor_plan.polygons()[0];
    assert!(ring.len() > 4, "notch adds vertices");
    // Orthogonal notch — no diagonal edge.
    let n = ring.len();
    let has_diag = (0..n).any(|i| {
        let (a, b) = (ring[i], ring[(i + 1) % n]);
        (a.x - b.x).abs() > 1e-3 && (a.y - b.y).abs() > 1e-3
    });
    assert!(!has_diag, "an orthogonal notch must have no diagonal edge");
    assert!(c.document.floor_plan.validate_simple().is_ok());
}

fn diag_edges(c: &AppController) -> usize {
    let ring = &c.document.floor_plan.polygons()[0];
    let n = ring.len();
    (0..n)
        .filter(|&i| {
            let (a, b) = (ring[i], ring[(i + 1) % n]);
            (a.x - b.x).abs() > 1e-3 && (a.y - b.y).abs() > 1e-3
        })
        .count()
}

/// Extending a porch flush at a corner leaves that corner mid-wall
/// (collinear). Since only the envelope matters, the controller cleans it
/// up after the splice — so the outline has no spurious collinear vertex.
#[test]
fn extend_porch_at_corner_cleans_the_spurious_vertex() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.set_edit_mode(EditTools::ExtendOrtho);
    // Freehand porch flush at corner (10,10).
    let porch = vec![
        Point2f32::new(10.3, 10.2),
        Point2f32::new(10.1, 14.1),
        Point2f32::new(5.8, 13.9),
        Point2f32::new(6.1, 10.3),
    ];
    c.apply_extend_stroke(&porch).unwrap();

    let ring = &c.document.floor_plan.polygons()[0];
    // The flush corner is gone — the right wall is one straight segment.
    assert!(
        !ring
            .iter()
            .any(|q| (q.x - 10.0).abs() < 1e-2 && (q.y - 10.0).abs() < 1e-2),
        "the flush corner should be cleaned from the envelope, ring={ring:?}"
    );
    assert_eq!(diag_edges(&c), 0, "envelope stays orthogonal");
    assert!(c.document.floor_plan.validate_simple().is_ok());
    // No collinear vertex remains.
    let n = ring.len();
    let collinear = (0..n)
        .filter(|&i| {
            let (pr, cu, nx) = (ring[(i + n - 1) % n], ring[i], ring[(i + 1) % n]);
            let (ux, uy) = (cu.x - pr.x, cu.y - pr.y);
            let (vx, vy) = (nx.x - cu.x, nx.y - cu.y);
            let len = ((ux * ux + uy * uy).sqrt() * (vx * vx + vy * vy).sqrt()).max(1e-9);
            (ux * vy - uy * vx).abs() / len < 1e-3 && (ux * vx + uy * vy) > 0.0
        })
        .count();
    assert_eq!(collinear, 0, "no spurious collinear vertices remain");
}

/// A wall painted Exposed that a dormer EXTEND splits into two flanks — the far
/// flank getting a freshly-minted start VertexId — has its exposure RE-HOMED so
/// BOTH resolved flank regions read Exposed, not one Exposed + one Unset.
/// Regression for the split-wall-loses-exposure report.
#[test]
fn extend_split_wall_keeps_exposure_on_both_flanks() {
    let mut c = dimensioned_square_controller();
    // Paint the whole bottom wall (y=0) Exposed.
    let (vid, a, b) = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .into_iter()
        .find(|(_, a, b)| a.y.abs() < 1e-4 && b.y.abs() < 1e-4)
        .expect("a y=0 wall");
    let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
    c.document
        .set_wall_section(vid, 0.0, len, len, WallExposure::Exposed);
    c.mark_dirty().unwrap();

    // Bump a dormer off the MIDDLE of that wall (outward, y<0): the splice
    // splits it into [0,3] (keeps `vid`) and [7,10] (a fresh vid).
    c.set_edit_mode(EditTools::ExtendOrtho);
    c.apply_extend_stroke(&[
        Point2f32::new(3.0, 0.0),
        Point2f32::new(3.0, -3.0),
        Point2f32::new(7.0, -3.0),
        Point2f32::new(7.0, 0.0),
    ])
    .expect("dormer extend");
    // Complete the dimensioning loop for the extend's freshly-minted params —
    // resolve DEFERS while the outline is in flux (the in-flux-outline gate,
    // field report eddc2f3f), so the record only re-derives once the loop is
    // done.
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();

    c.materialize();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    // The two perimeter flanks are the wall regions whose base edge lies on y=0.
    let flanks: Vec<&ber_model::ber::structural::WallRegion> = storey
        .walls
        .regions
        .iter()
        .filter(|r| {
            r.base_edge()
                .is_some_and(|(a, b)| a.y.abs() < 1e-3 && b.y.abs() < 1e-3)
        })
        .collect();
    assert_eq!(flanks.len(), 2, "the bottom wall split into two flanks");
    assert!(
        flanks.iter().all(|r| r.exposure == WallExposure::Exposed),
        "BOTH flanks inherit Exposed (not one Unset): {:?}",
        flanks.iter().map(|r| r.exposure).collect::<Vec<_>>()
    );
}

/// A PARTIAL paint must not leak onto the flank it doesn't cover: paint only the
/// FIRST metre of the 10 m bottom wall Exposed, then dormer-split it at the FAR
/// end. The near flank (which owns the painted metre) resolves Exposed; the far
/// flank (its own span was unpainted) resolves UNSET — the exposure sections are
/// TRANSLATED by the flank's offset, not copied verbatim.
#[test]
fn extend_split_wall_partial_paint_does_not_leak_to_the_far_flank() {
    let mut c = dimensioned_square_controller(); // 10×10
    let (vid, a, b) = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .into_iter()
        .find(|(_, a, b)| a.y.abs() < 1e-4 && b.y.abs() < 1e-4)
        .expect("a y=0 wall");
    let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
    // Paint only the first metre (near the wall's START vertex `a`) Exposed.
    c.document
        .set_wall_section(vid, 0.0, 1.0, len, WallExposure::Exposed);
    c.mark_dirty().unwrap();

    // Dormer off the FAR end of the wall (x≈6..8, away from the painted x≈0..1).
    c.set_edit_mode(EditTools::ExtendOrtho);
    c.apply_extend_stroke(&[
        Point2f32::new(6.0, 0.0),
        Point2f32::new(6.0, -3.0),
        Point2f32::new(8.0, -3.0),
        Point2f32::new(8.0, 0.0),
    ])
    .expect("dormer extend");
    // Complete the dimensioning loop for the extend's freshly-minted params —
    // resolve defers while the outline is in flux (see the gate note above).
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();

    c.materialize();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    // Exposure resolves per coverage segment, so the painted metre x[0,1] and the
    // unpainted rest x[1,6] are distinct regions on the near flank. Sample by x.
    let cover_at = |xmid: f64| -> Option<WallExposure> {
        storey
            .walls
            .regions
            .iter()
            .find(|r| {
                r.base_edge().is_some_and(|(a, b)| {
                    a.y.abs() < 1e-3
                        && b.y.abs() < 1e-3
                        && (a.x.min(b.x)..a.x.max(b.x)).contains(&xmid)
                })
            })
            .map(|r| r.exposure)
    };
    // The painted metre (x≈0.5) on the near flank is Exposed.
    assert_eq!(
        cover_at(0.5),
        Some(WallExposure::Exposed),
        "the painted first metre resolves Exposed"
    );
    // The far flank (x≈9, its own span unpainted) is Unset — the paint did NOT
    // leak onto it (the sections were offset-translated, not copied verbatim).
    assert_eq!(
        cover_at(9.0),
        Some(WallExposure::Unset),
        "the far flank's own span was unpainted → Unset (paint did NOT leak)"
    );
}

/// Every (x, y) plan position appearing in a wall region's polygon, deduped —
/// a clean wall over a flat roof is a plain quad with exactly TWO of them (its
/// base-edge endpoints); a stale roof edge shows up as an extra top vertex.
fn wall_plan_positions(r: &ber_model::ber::structural::WallRegion) -> Vec<(i64, i64)> {
    let mut pts: Vec<(i64, i64)> = r
        .polygon
        .exterior
        .iter()
        .map(|v| ((v.x * 1e6).round() as i64, (v.y * 1e6).round() as i64))
        .collect();
    pts.sort_unstable();
    pts.dedup();
    pts
}

/// FIELD REPORT eddc2f3f (8 Ashgrove Hill): trimming a corner of a
/// fully-resolved, exposure-painted storey left "lines everywhere" — the
/// resolve that ran MID-dimensioning re-fit the regions-as-truth ceilings
/// against the PROVISIONAL (drawn) cut line, and the post-dimensioning resolve
/// then intersected against those scarred rings: the superseded line survived
/// in the porch ceiling, `Unset` sliver fills appeared between the drawn and
/// the dimensioned cut, and wall tops traced the stale edges ("the exposures
/// set for the old walls linger rather than cropping with the walls").
///
/// With the in-flux-outline gate, resolve DEFERS while the trim's freshly
/// minted params are still being prompted for — the record holds the pre-trim
/// state untouched — and the first post-completion resolve clips against the
/// FINAL outline only: one clean ceiling, quad walls, and the painted wall
/// exposure CROPPED to the shortened wall.
#[test]
fn trim_defers_resolve_until_dimensioned_and_paint_crops_with_the_wall() {
    let mut c = dimensioned_square_controller(); // 10×10, storey 0
    c.set_default_ceiling_height(2.4).unwrap();
    // Paint the whole TOP wall (y=10) Exposed — the paint that must crop.
    let (vid, a, b) = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .into_iter()
        .find(|(_, a, b)| (a.y - 10.0).abs() < 1e-4 && (b.y - 10.0).abs() < 1e-4)
        .expect("a y=10 wall");
    let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
    c.document
        .set_wall_section(vid, 0.0, len, len, WallExposure::Exposed);
    c.commit_to_ber().unwrap();
    let pre = c.current_record.as_ref().unwrap().data.storeys[0].clone();
    assert_eq!(pre.ceilings.regions.len(), 1, "fixture: one flat ceiling");

    // Chamfer-trim the (10,10) corner. The trim mints new params → the outline
    // is IN FLUX until the dimensioning loop completes.
    c.set_edit_mode(EditTools::Trim);
    c.apply_trim_stroke(&[Point2f32::new(10.0, 7.5), Point2f32::new(7.5, 10.0)])
        .expect("trim applies");
    c.materialize();
    assert!(
        !c.document.storeys[0].measurements_complete(),
        "fixture: the trim left params to dimension (the in-flux state)"
    );
    // Mid-loop, the record held STEADY: the provisional cut line never reached
    // the resolved regions (stale but consistent — no scar to intersect later).
    let mid = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(
        mid.ceilings.regions[0].polygon.exterior, pre.ceilings.regions[0].polygon.exterior,
        "resolve deferred while the outline is mid-dimensioning"
    );

    // The dimensioning loop completes (drawn values accepted) → the next
    // resolve derives the FINAL chamfered outline in ONE clean projection.
    // (A real `apply_dimension` marks dirty; the direct known_params write
    // used by tests must do the same for `materialize` to re-derive.)
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];

    // One clean re-fit ceiling: no Unset sliver fills, nothing past the cut.
    assert_eq!(storey.ceilings.regions.len(), 1, "no sliver regions");
    for v in &storey.ceilings.regions[0].polygon.exterior {
        assert!(
            v.x + v.y <= 17.5 + 1e-3,
            "no ceiling vertex beyond the chamfer: ({}, {})",
            v.x,
            v.y
        );
    }
    // Every wall is a plain quad — no phantom top vertex from a stale edge.
    for w in &storey.walls.regions {
        assert_eq!(
            wall_plan_positions(w).len(),
            2,
            "wall carries only its base-edge plan positions: {:?}",
            w.polygon.exterior
        );
    }
    // THE USER'S COMPLAINT: the painted exposure crops with the shortened
    // wall. The y=10 wall now ends at x=7.5; its Exposed region must cover
    // exactly the surviving span and nothing may extend past the chamfer.
    let top_walls: Vec<_> = storey
        .walls
        .regions
        .iter()
        .filter(|r| {
            r.base_edge()
                .is_some_and(|(a, b)| (a.y - 10.0).abs() < 1e-3 && (b.y - 10.0).abs() < 1e-3)
        })
        .collect();
    assert!(!top_walls.is_empty(), "the shortened top wall resolves");
    for w in &top_walls {
        let (a, b) = w.base_edge().unwrap();
        assert!(
            a.x <= 7.5 + 1e-3 && b.x <= 7.5 + 1e-3,
            "no top-wall region extends past the chamfered end: {:?}",
            (a, b)
        );
        assert_eq!(
            w.exposure,
            WallExposure::Exposed,
            "the paint survives on the surviving span"
        );
    }
    let covered: f64 = top_walls
        .iter()
        .map(|w| {
            let (a, b) = w.base_edge().unwrap();
            (b.x - a.x).abs()
        })
        .sum();
    assert!(
        (covered - 7.5).abs() < 1e-2,
        "the paint covers exactly the shortened wall (got {covered})"
    );
}

/// UNDO must roll back the RESOLVE-side effects of the undone action too
/// (field report eddc2f3f, second mechanism): after trim → undo, the resolved
/// record may keep NO geometry from the undone cut — otherwise a later
/// re-trim + resolve intersects against the stale rings and the abandoned
/// chamfer lingers as extra lines. The `HistorySnapshot` carries the storey's
/// record (`record_storey`), and the post-undo re-resolve must reproduce the
/// pre-trim regions exactly; a different re-trim afterwards must come out
/// clean, with no coordinate from the first (undone) attempt.
#[test]
fn undo_of_a_trim_rolls_back_the_resolved_record() {
    let mut c = dimensioned_square_controller(); // 10×10
    c.set_default_ceiling_height(2.4).unwrap();
    c.commit_to_ber().unwrap();
    let pre = c.current_record.as_ref().unwrap().data.storeys[0].clone();

    // Trim attempt 1: chamfer A — (10,7)↔(7,10) — dimensioned as drawn.
    c.set_edit_mode(EditTools::Trim);
    c.apply_trim_stroke(&[Point2f32::new(10.0, 7.0), Point2f32::new(7.0, 10.0)])
        .expect("trim A applies");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.materialize();
    let has_pt = |storey: &ber_model::ber::structural::Storey, x: f64, y: f64| {
        storey
            .ceilings
            .regions
            .iter()
            .flat_map(|r| r.polygon.exterior.iter())
            .chain(
                storey
                    .walls
                    .regions
                    .iter()
                    .flat_map(|r| r.polygon.exterior.iter()),
            )
            .any(|v| (v.x - x).abs() < 1e-3 && (v.y - y).abs() < 1e-3)
    };
    assert!(
        has_pt(
            &c.current_record.as_ref().unwrap().data.storeys[0],
            7.0,
            10.0
        ),
        "fixture: chamfer A resolved into the record"
    );

    // UNDO the trim: the record must return to the PRE-TRIM state — no
    // chamfer-A geometry may survive anywhere in the resolved regions.
    c.undo().unwrap();
    c.materialize();
    let after_undo = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(
        after_undo.ceilings.regions[0].polygon.exterior, pre.ceilings.regions[0].polygon.exterior,
        "undo restored the pre-trim ceilings exactly"
    );
    assert_eq!(
        after_undo.floors.to_vertex_lists(),
        pre.floors.to_vertex_lists(),
        "undo restored the pre-trim floors exactly"
    );
    assert!(
        !has_pt(after_undo, 7.0, 10.0) && !has_pt(after_undo, 10.0, 7.0),
        "no geometry from the undone trim survives in the resolved record"
    );

    // Trim attempt 2: a DIFFERENT chamfer B — (10,8.5)↔(8.5,10) — dimensioned.
    c.apply_trim_stroke(&[Point2f32::new(10.0, 8.5), Point2f32::new(8.5, 10.0)])
        .expect("trim B applies");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.materialize();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];

    // Clean result: one ceiling, quad walls, and NOTHING from abandoned A.
    assert_eq!(storey.ceilings.regions.len(), 1, "no sliver regions");
    assert!(
        !has_pt(storey, 7.0, 10.0) && !has_pt(storey, 10.0, 7.0),
        "the undone chamfer A left no coordinates behind"
    );
    for w in &storey.walls.regions {
        assert_eq!(
            wall_plan_positions(w).len(),
            2,
            "wall carries only its base-edge plan positions: {:?}",
            w.polygon.exterior
        );
    }
    assert!(
        !storey.ceilings_carry_outline_edit_scars(),
        "the resolved record is scar-free"
    );
}

/// LOAD-TIME HEAL for records scarred BEFORE the in-flux-outline gate (field
/// report eddc2f3f): a saved BER whose regions-as-truth ceilings carry an
/// unjustified flat seam (the superseded cut line + `Unset` fill pieces) is
/// detected on reopen (`Storey::ceilings_carry_outline_edit_scars`) and its
/// ceilings recomposed from the durable inputs — the painted exposure
/// re-stamps via the containment fallback, and the walls re-derive against
/// the clean roof. A clean record keeps its stored ceilings verbatim (the
/// detector never fires), preserving the reload fixpoint.
#[test]
fn outline_scarred_ceilings_heal_on_reopen() {
    use ber_model::ber::common::ItemId;
    use ber_model::ber::structural::{
        CeilingExposure, CeilingRegion, CeilingRegions, Opes, Polygon3D,
    };
    use domain::points::Point3f64;

    let mut c = dimensioned_square_controller(); // 10×10
    c.set_default_ceiling_height(2.4).unwrap();
    c.commit_to_ber().unwrap();
    let id = c.current_record.as_ref().unwrap().id;

    // Bake the pre-fix scar into the record: the single flat ceiling split
    // along a stale cut line — the main piece painted ExposedRoof, the corner
    // triangle an `Unset` fill (the eddc2f3f fingerprint). Together they tile
    // the unchanged footprint, so a normal resolve keeps them verbatim.
    {
        let record = c.current_record.as_mut().unwrap();
        let storey = &mut record.data.storeys[0];
        let cid = storey.ceilings.regions[0].construction_id;
        let mk = |pts: &[(f64, f64)], exposure: CeilingExposure| CeilingRegion {
            id: ItemId::default(),
            polygon: Polygon3D::new(
                pts.iter()
                    .map(|&(x, y)| Point3f64::new(x, y, 2.4))
                    .collect(),
            ),
            opes: Opes::default(),
            construction_id: cid,
            exposure,
        };
        storey.ceilings = CeilingRegions {
            regions: vec![
                mk(
                    &[
                        (0.0, 0.0),
                        (10.0, 0.0),
                        (10.0, 8.0),
                        (8.0, 10.0),
                        (0.0, 10.0),
                    ],
                    CeilingExposure::ExposedRoof,
                ),
                mk(
                    &[(10.0, 8.0), (10.0, 10.0), (8.0, 10.0)],
                    CeilingExposure::Unset,
                ),
            ],
        };
        assert!(
            storey.ceilings_carry_outline_edit_scars(),
            "fixture: the baked seam is detected as a scar"
        );
    }
    // The scar survives a normal save (regions-as-truth: the footprint is
    // unchanged, so resolve keeps the stored ceilings verbatim).
    c.mark_dirty().unwrap();
    c.flush_if_dirty().unwrap();

    // REOPEN: the load-path heal detects the scar, recomposes the ceilings
    // from the durable inputs, and the re-resolve re-stamps the paint.
    c.open_ber(&id).unwrap();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(
        storey.ceilings.regions.len(),
        1,
        "healed back to the single flat ceiling (scar seam + Unset fill gone)"
    );
    assert_eq!(
        storey.ceilings.regions[0].exposure,
        ber_model::ber::structural::CeilingExposure::ExposedRoof,
        "the painted exposure re-stamped onto the healed region (containment fallback)"
    );
    assert!(
        !storey.ceilings_carry_outline_edit_scars(),
        "the reopened record is scar-free"
    );
    for w in &storey.walls.regions {
        assert_eq!(
            wall_plan_positions(w).len(),
            2,
            "walls re-derived against the healed roof are plain quads"
        );
    }
}

fn ring_area(c: &AppController) -> f32 {
    let ring = &c.document.floor_plan.polygons()[0];
    let n = ring.len();
    let mut sum = 0.0_f32;
    for i in 0..n {
        let (a, b) = (ring[i], ring[(i + 1) % n]);
        sum += a.x * b.y - b.x * a.y;
    }
    (sum * 0.5).abs()
}

/// Dragging a wall in Edit mode must prompt for a distance PERPENDICULAR to
/// the wall: a vertical wall is measured horizontally (axis X), a horizontal
/// wall vertically (axis Y). (User: "moving the E's left wall showed me a
/// vertical dimension; it should be horizontal.")
#[test]
fn dragging_a_wall_measures_perpendicular_to_it() {
    let make = || {
        let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
        let square = vec![
            Point2f32::new(0.0, 0.0),
            Point2f32::new(10.0, 0.0),
            Point2f32::new(10.0, 10.0),
            Point2f32::new(0.0, 10.0),
            Point2f32::new(0.2, 0.2),
        ];
        c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
        // The drag prompt only appears once the plan is dimensioned.
        c.document.dimensioning.scale_set = true;
        c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
        c.set_edit_mode(EditTools::Move);
        c
    };

    // Left (vertical) wall at x=0 → measured along X.
    let mut c = make();
    assert!(c.edit_mouse_down(0.0, 5.0, 1.0), "should hit the left wall");
    c.edit_mouse_drag(0.5, 5.0); // nudge it horizontally
    c.edit_mouse_up().unwrap();
    let p = c
        .edit_drag_prompt
        .as_ref()
        .expect("a measurement prompt after dragging a wall");
    assert_eq!(
        p.axis,
        ParameterAxis::X,
        "a vertical wall is measured horizontally"
    );

    // Bottom (horizontal) wall at y=0 → measured along Y.
    let mut c = make();
    assert!(
        c.edit_mouse_down(5.0, 0.0, 1.0),
        "should hit the bottom wall"
    );
    c.edit_mouse_drag(5.0, 0.5);
    c.edit_mouse_up().unwrap();
    let p = c
        .edit_drag_prompt
        .as_ref()
        .expect("a measurement prompt after dragging a wall");
    assert_eq!(
        p.axis,
        ParameterAxis::Y,
        "a horizontal wall is measured vertically"
    );
}

/// Drawing a living area inside a dimensioned storey: it inherits the
/// storey's scale (no recalibration), becomes the active shape, is stored,
/// and the storey outline is untouched when you switch back.
#[test]
fn living_area_inherits_scale_is_stored_and_leaves_outline_intact() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.document.dimensioning.scale_set = true; // storey is dimensioned (metres)
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    let outline_verts = c.document.floor_plan.polygons()[0].len();

    // Enter living-area mode and draw a sub-area inside the storey.
    c.set_living_area_mode(true);
    assert!(c.living_area_mode());
    let la: Vec<(f32, f32)> = vec![(2.0, 2.0), (6.0, 2.0), (6.0, 6.0), (2.0, 6.0), (2.1, 2.1)];
    c.apply_living_area_stroke_event(&la);

    assert_eq!(c.living_area_count(), 1, "the living area is stored");
    assert_eq!(
        c.active_living_area_index(),
        Some(0),
        "it's the active shape"
    );
    // Inherits the storey scale — no first-dimension calibration step.
    assert!(
        c.dimensioning_scale_set(),
        "a living area inside a dimensioned storey inherits its scale"
    );
    assert!(
        c.document.floor_plan.polygons()[0].len() >= 4,
        "a sub-area was drawn"
    );
    assert_eq!(c.living_area_polygons().len(), 1, "renderable");

    // Switch back to the outline: it's restored exactly, area still stored.
    c.set_living_area_mode(false);
    assert_eq!(c.active_living_area_index(), None);
    assert_eq!(
        c.document.floor_plan.polygons()[0].len(),
        outline_verts,
        "the storey outline is untouched by drawing a living area"
    );
    assert_eq!(c.living_area_count(), 1, "the living area is still kept");
}

/// A fully-dimensioned living area is persisted as resolved geometry and
/// comes back on reopen (alongside the outline). Un-dimensioned areas are
/// NOT written to the DB — only finalised geometry is.
#[test]
fn living_areas_survive_save_and_reopen() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let ber = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.commit_to_ber().unwrap();

    c.set_living_area_mode(true);
    c.apply_living_area_stroke_event(&[(2.0, 2.0), (6.0, 2.0), (6.0, 6.0), (2.0, 6.0), (2.1, 2.1)]);
    assert_eq!(c.living_area_count(), 1);
    // Finalise the living area (mark every wall dimensioned) so it's written
    // to the DB — only finalised geometry is persisted.
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.commit_to_ber().unwrap();

    // Reopen from the DB (same connection): the living area is restored.
    c.open_ber(&ber.id).unwrap();
    assert_eq!(
        c.living_area_count(),
        1,
        "the living area survives save + reopen"
    );
    assert_eq!(
        c.active_living_area_index(),
        None,
        "reopen starts on the storey outline"
    );
    assert_eq!(
        c.living_area_polygons().len(),
        1,
        "still renderable after reopen"
    );
}

/// An un-dimensioned outline is still in pixels, not metres, so it is NOT
/// written to the DB — only a finalised (scale-set, fully dimensioned)
/// outline persists. (The in-memory copy keeps it, for rendering.)
#[test]
fn undimensioned_outline_is_not_persisted() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let ber = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    // Draw an outline but leave it un-dimensioned (scale never set).
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(
        &[
            Point2f32::new(0., 0.),
            Point2f32::new(10., 0.),
            Point2f32::new(10., 10.),
            Point2f32::new(0., 10.),
            Point2f32::new(0.2, 0.2),
        ],
        0.5,
        true,
    )
    .unwrap();
    c.commit_to_ber().unwrap();
    c.flush_if_dirty().unwrap();

    // The DURABLE record holds no geometry (the outline wasn't finalised, so
    // it's filtered out of `data_json`). The editing-layer snapshot recovers
    // the in-progress sketch separately on reopen.
    let durable = BerRepository::new(&c.conn).load(&ber.id).unwrap();
    assert!(
        durable
            .data
            .storeys
            .first()
            .map_or(true, |s| s.floors.regions.is_empty()),
        "an un-dimensioned outline isn't written into the durable BER record"
    );
    c.open_ber(&ber.id).unwrap();
    assert!(
        !c.document.outline.floor_plan.get_points().is_empty(),
        "...but the snapshot recovers the in-progress outline on reopen"
    );
}

/// Duplicate-BER deep-copy: `duplicate_ber` writes a BRAND-NEW persisted row
/// (a real deep copy, not in-memory), leaves the source untouched, does not open
/// the copy, re-stamps the clone's `data.id` to the new record id, and clones
/// the editing-layer snapshot when the source has one.
#[test]
fn duplicate_ber_deep_copies_into_a_new_persisted_record() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let source = c.create_ber(
        "Original".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    // Give the source some non-default data + a storey, then persist (which
    // also writes a snapshot for the source).
    {
        let rec = c.current_record.as_mut().unwrap();
        rec.data.address = "42 Test Lane".into();
        rec.data.eircode = "D01 AB12".into();
        rec.data.storeys.push(Default::default());
    }
    c.persist().unwrap();
    assert!(
        BerRepository::new(&c.conn)
            .load_snapshot(&source.id)
            .unwrap()
            .is_some(),
        "source has a snapshot (precondition for the copy-snapshot assertion)"
    );

    // Duplicate. Must NOT open the copy — `current_record` stays the source.
    let new_id = c.duplicate_ber(&source.id).unwrap();
    assert_eq!(
        c.current_record.as_ref().unwrap().id,
        source.id,
        "duplicating must not change the currently-loaded record"
    );

    // (a) Two records now listed.
    assert_eq!(c.list_bers().len(), 2, "the copy is a real new DB row");
    // (b) New id differs from the source.
    assert_ne!(new_id, source.id, "the copy gets a fresh id");

    // (c) The copy carries the source's data, with `data.id` re-stamped to the
    // new record id (NOT the source's).
    let repo = BerRepository::new(&c.conn);
    let copy = repo.load(&new_id).unwrap();
    assert_eq!(copy.id, new_id);
    assert_eq!(copy.data.id, new_id, "Ber.id matches the new record id");
    assert_ne!(copy.data.id, source.id);
    assert_eq!(copy.name, "Original (copy)");
    assert_eq!(copy.data.address, "42 Test Lane");
    assert_eq!(copy.data.eircode, "D01 AB12");
    assert_eq!(copy.data.storeys.len(), 1);
    // date_assessed is preserved (same assessment).
    assert_eq!(
        copy.date_assessed,
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap()
    );
    // The copy has its own snapshot (deep copy included the editing layer).
    assert!(
        repo.load_snapshot(&new_id).unwrap().is_some(),
        "the copy's editing-layer snapshot was cloned"
    );

    // (d) The source record is unchanged.
    let src = repo.load(&source.id).unwrap();
    assert_eq!(src.name, "Original");
    assert_eq!(src.data.id, source.id);
    assert_eq!(src.data.address, "42 Test Lane");
}

