/// THE cd36f510 FLOW, height MEETING one side: an E-W ridge stroke drawn
/// ALONG the junction between the two raised strips snaps onto the junction
/// line (cross) and onto the outline wall / strip boundary (both ends) — all
/// three DOFs resolve from the stroke, the finalize placement check passes
/// (the ridge is a legal mono-pitch junction claimed by BOTH strips), and
/// the Height stage opens. A height of 2.95 — the RAISED strip's own
/// ceiling — can only slope the LOWER strip, so the model auto-resolves to
/// it and the shell surfaces the silent decision as the ridge notice.
///
/// REGRESSION (the field bug): the finalize used to reject this stroke with
/// "Both ends of the ridge must sit in the same ceiling area" — the extent's
/// far end, recomputed as `lo + len` in f32, landed ~5e-7 m past the strips'
/// shared corner, strictly inside the default-height region beyond it, and
/// `claim_regions`' strictly-contains short-circuit handed the end to that
/// region ALONE. The all-snapped path then dropped the stroke (before the
/// notice fix, silently — "it's not letting me do it").
#[test]
fn cd36f510_junction_ridge_meeting_one_side_slopes_the_lower_strip() {
    let mut c = cd36f510_controller();
    c.apply_roof_ridge_stroke_event(&[(1.5, 0.10), (4.4, 0.09), (7.2, 0.10)]);
    assert!(
        c.ceiling_ridge_height_pending(),
        "all-snapped junction stroke reaches the Height stage (notice: {:?})",
        c.roof_ridge_notice()
    );
    c.assign_roof_ridge_height(2.95)
        .expect("the junction height applies");
    assert!(
        c.ceiling_ridge_area_options().is_empty(),
        "no ChooseArea — only the lower strip is slope-able"
    );
    let notice = c
        .roof_ridge_notice()
        .expect("the auto-resolve is surfaced, not silent");
    assert!(notice.starts_with("Sloped:"), "got: {notice}");

    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(storey.ceiling_apexes.len(), 2, "both ridge ends committed");
    assert_eq!(
        storey.ceiling_apex_groups().len(),
        1,
        "one mono-pitch group"
    );
    // The LOWER strip slopes from its own 2.572 eave up to 2.95 at the
    // junction; the raised strip keeps its flat 2.95 ceiling; the
    // default-height remainder is untouched.
    let sloped: Vec<_> = storey
        .ceilings
        .regions
        .iter()
        .filter(|r| r.flat_z().is_none())
        .collect();
    assert_eq!(sloped.len(), 1, "exactly the lower strip slopes");
    let zs: Vec<f64> = sloped[0].polygon.exterior.iter().map(|v| v.z).collect();
    assert!(
        zs.iter().any(|z| (z - 2.95).abs() < 1e-4) && zs.iter().any(|z| (z - 2.572).abs() < 1e-4),
        "slopes 2.572 → 2.95: {zs:?}"
    );
    assert!(
        storey
            .ceilings
            .regions
            .iter()
            .any(|r| r.flat_z().is_some_and(|z| (z - 2.95).abs() < 1e-4)),
        "the raised strip keeps its flat ceiling"
    );
    assert!(
        storey
            .ceilings
            .regions
            .iter()
            .any(|r| r.flat_z().is_some_and(|z| (z - 2.409).abs() < 1e-4)),
        "the default-height remainder survives flat"
    );
}

/// THE cd36f510 FLOW, height meeting NEITHER side: the same on-junction
/// stroke with a height above both strips is a genuine two-way choice — the
/// ChooseArea prompt opens naming both sides, and the chosen side slopes up
/// to the ridge while the other keeps its ceiling.
#[test]
fn cd36f510_junction_ridge_meeting_neither_side_asks_which_area() {
    let mut c = cd36f510_controller();
    c.apply_roof_ridge_stroke_event(&[(1.5, 0.10), (4.4, 0.09), (7.2, 0.10)]);
    assert!(c.ceiling_ridge_height_pending(), "height stage opens");
    c.assign_roof_ridge_height(3.4).expect("the height applies");
    let options = c.ceiling_ridge_area_options();
    assert_eq!(options.len(), 2, "both sides offered: {options:?}");
    // "Above the ridge" is the smaller-y side (plan y grows downward): the
    // 2.572 strip.
    let above = options
        .iter()
        .position(|o| o.contains("Above"))
        .expect("side labels name above/below");
    c.choose_roof_ridge_area(above).expect("the choice applies");
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    let sloped: Vec<_> = storey
        .ceilings
        .regions
        .iter()
        .filter(|r| r.flat_z().is_none())
        .collect();
    assert_eq!(sloped.len(), 1, "exactly the chosen strip slopes");
    let zs: Vec<f64> = sloped[0].polygon.exterior.iter().map(|v| v.z).collect();
    assert!(
        zs.iter().any(|z| (z - 3.4).abs() < 1e-4) && zs.iter().any(|z| (z - 2.572).abs() < 1e-4),
        "the chosen (lower) strip rises 2.572 → 3.4: {zs:?}"
    );
    assert!(
        storey
            .ceilings
            .regions
            .iter()
            .any(|r| r.flat_z().is_some_and(|z| (z - 2.95).abs() < 1e-4)),
        "the passed-over strip keeps its flat ceiling"
    );
}

/// The all-snapped stroke path used to DROP a rejected ridge silently (a
/// `log::error` the assessor never sees — cd36f510's "it's not letting me
/// do it"). Now the rejection surfaces as the ridge notice.
#[test]
fn rejected_all_snapped_ridge_stroke_surfaces_a_notice() {
    let mut c = cd36f510_controller();
    // Commit the junction ridge first — the lower strip is sloped now.
    c.apply_roof_ridge_stroke_event(&[(1.5, 0.10), (4.4, 0.09), (7.2, 0.10)]);
    c.assign_roof_ridge_height(2.95).unwrap();
    assert!(c.pending_roof_ridge.is_none(), "the ridge committed");
    // A horizontal stroke hugging the bottom outline wall of the now-SLOPED
    // strip: the cross snaps to y = -1.3851 and both ends snap
    // (x = 1.3659 / 7.3669) — all-snapped, so the finalize rejection (the
    // area already has a high point) has no open stage to land on.
    c.apply_roof_ridge_stroke_event(&[(1.45, -1.30), (4.4, -1.31), (7.3, -1.30)]);
    assert!(
        c.pending_roof_ridge.is_none(),
        "the rejected stroke opens no stage"
    );
    let notice = c.roof_ridge_notice().expect("the rejection is surfaced");
    assert!(
        !notice.is_empty(),
        "the notice carries the rejection message"
    );
}

/// Minor bbox dimension (m) of a plan ring — the thickness the sliver guard
/// measures. Shared by the degenerate-region assertions below.
fn plan_minor_dim(ext: &[domain::points::Point3f64]) -> f64 {
    let (mut nx, mut xx, mut ny, mut xy) = (
        f64::INFINITY,
        f64::NEG_INFINITY,
        f64::INFINITY,
        f64::NEG_INFINITY,
    );
    for v in ext {
        nx = nx.min(v.x);
        xx = xx.max(v.x);
        ny = ny.min(v.y);
        xy = xy.max(v.y);
    }
    (xx - nx).min(xy - ny)
}

/// Shoelace plan area of a `Polygon3D` exterior (xy projection).
fn plan_area3(ext: &[domain::points::Point3f64]) -> f64 {
    let n = ext.len();
    (0..n)
        .map(|i| {
            let (p, q) = (&ext[i], &ext[(i + 1) % n]);
            p.x * q.y - q.x * p.y
        })
        .sum::<f64>()
        .abs()
        / 2.0
}

/// FIELD REPORT 797a7ff5 — the degenerate-sliver artifact: an L-plan two-storey
/// with an Original/Extension phase boundary coincident with the storey1/
/// storey0 shared edge (y = 4.4649). The phase-zone ring had round-tripped
/// through f32, landing one ULP (~0.48 µm) off the f64 outline edge, so the
/// floor partition + inter-storey / coplanar splits shaved a 6.02 m × 0.48 µm
/// strip that cleared every area-only guard — persisted as storey1 floor
/// reg1, storey1 ceiling reg0, and storey0 ceiling reg0 (all minor dim
/// 4.77e-7 m in the dump).
///
/// The fix carries phase-zone rings in f64 (bit-identical to the floor edge)
/// AND adds a thickness-aware split guard. Re-resolving the dump must leave
/// NO degenerate region on either storey's floors or ceilings, with the real
/// coverage intact (floors and ceilings still cover the full footprint, the
/// phase split preserved).
#[test]
fn dump_797a7ff5_no_degenerate_sliver_after_resolve() {
    let dump = "/tmp/claude-1000/-home-anishrag-WORK-BER-APP-Branch2/\
c3838f4c-8dc1-4e86-92de-029cef93c73d/scratchpad/bugs-new6/07-14T1534_797a7ff5/state.json";
    // The dump lives in a session /tmp scratchpad — when it's gone (fresh
    // boot, another machine) skip rather than fail; the guard still runs
    // wherever the capture exists.
    if !std::path::Path::new(dump).exists() {
        eprintln!("dump_797a7ff5: {dump} not present — skipped");
        return;
    }
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    assert!(c.load_checkpoint_from(dump), "checkpoint loads");

    // Re-resolve every storey from its inputs (the fix acts at partition /
    // split time, so the persisted strip only clears on re-derivation).
    let n = c.current_record.as_ref().unwrap().data.storeys.len();
    for i in 0..n {
        c.set_current_storey(Some(i)).unwrap();
        c.commit_to_ber().unwrap();
    }

    const MIN_MINOR_M: f64 = 1e-3;
    let record = c.current_record.as_ref().unwrap();
    for (i, storey) in record.data.storeys.iter().enumerate() {
        let mut floor_area = 0.0;
        for (j, r) in storey.floors.regions.iter().enumerate() {
            let ext: Vec<domain::points::Point3f64> = r
                .polygon
                .exterior()
                .coords()
                .map(|co| domain::points::Point3f64::new(co.x, co.y, 0.0))
                .collect();
            assert!(
                plan_minor_dim(&ext) >= MIN_MINOR_M,
                "storey {i} floor {j} is a degenerate sliver (minor {:.2e} m)",
                plan_minor_dim(&ext)
            );
            floor_area += plan_area3(&ext);
        }
        let mut ceil_area = 0.0;
        for (j, r) in storey.ceilings.regions.iter().enumerate() {
            let ext = &r.polygon.exterior;
            assert!(
                plan_minor_dim(ext) >= MIN_MINOR_M,
                "storey {i} ceiling {j} is a degenerate sliver (minor {:.2e} m)",
                plan_minor_dim(ext)
            );
            ceil_area += plan_area3(ext);
        }
        // Coverage intact: floors and ceilings still cover the same footprint.
        assert!(floor_area > 1.0, "storey {i} floors cover real area");
        assert!(
            (floor_area - ceil_area).abs() < 1e-3,
            "storey {i} floor/ceiling coverage matches ({floor_area} vs {ceil_area})"
        );
    }
    // The phase split survived on the ground storey (Original + Extension) —
    // more than one floor region, all non-degenerate (checked above).
    assert!(
        record.data.storeys[0].floors.regions.len() >= 2,
        "the Original/Extension phase split is preserved on the ground storey"
    );
}

/// Field regression (2026-07-19 porch trim): chamfering a porch corner on a
/// FULLY DIMENSIONED outline (scale set, every param known, height entered)
/// must succeed — the porch was drawn as a 3-sided rectangle bump and the two
/// front corners were to be cut to make it 5-sided. Same shape as the field
/// storey: an L-ish 10-vertex ring with a 1.86 × 0.98 porch bump on top.
#[test]
fn trim_chamfers_porch_corner_on_dimensioned_outline() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let ring = [
        Point2f32::new(1.66, 24.03),
        Point2f32::new(5.03, 24.03),
        Point2f32::new(5.03, 25.01), // porch front-left corner
        Point2f32::new(6.89, 25.01), // porch front-right corner
        Point2f32::new(6.89, 15.93),
        Point2f32::new(9.01, 15.93),
        Point2f32::new(9.01, 8.92),
        Point2f32::new(8.33, 8.92),
        Point2f32::new(8.33, 5.39),
        Point2f32::new(1.66, 5.39),
    ];
    c.document.floor_plan = FloorPlan::from_clean_ring(&ring).unwrap();
    // Fully dimensioned, as in the field when the trim was attempted.
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();

    // Chamfer across the front-left porch corner: the cut line crosses the
    // porch's left wall (x=5.03) at y≈24.68 and its front (y=25.01) at x≈5.36.
    c.sketch_engine.edit_tool = EditTools::Trim;
    c.apply_trim_stroke_event(&[(4.9, 24.55), (5.5, 25.15)])
        .expect("corner chamfer on a dimensioned outline succeeds");
    assert_eq!(
        c.document.floor_plan.get_points().len(),
        11,
        "the chamfer replaces the corner with a diagonal cut edge (+1 vertex)"
    );
    // Then the front-RIGHT corner — the second cut runs on a ring that already
    // contains the first diagonal edge, completing the 5-sided porch.
    c.apply_trim_stroke_event(&[(6.45, 25.15), (7.0, 24.5)])
        .expect("second corner chamfer succeeds after the first");
    assert_eq!(
        c.document.floor_plan.get_points().len(),
        12,
        "both porch corners are chamfered (porch front is now 5-sided)"
    );
}

/// Field regression (2026-07-19 porch trim): picking an edit tool from the
/// toolbar must EXIT the canvas-claiming overlay modes. In the field an
/// active mode kept owning the canvas and every Trim stroke was silently
/// discarded while the Trim button showed selected.
#[test]
fn select_edit_tool_exits_stroke_swallowing_modes() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.set_openings_mode(true);
    assert!(c.openings_mode(), "precondition: openings mode on");
    c.select_edit_tool(EditTools::Trim);
    assert!(!c.openings_mode(), "tool pick exits openings mode");
    assert_eq!(c.edit_mode(), EditTools::Trim);

    c.set_exposure_mode(true);
    c.select_edit_tool(EditTools::ExtendOrtho);
    assert!(!c.exposure_mode, "tool pick exits wall-exposure mode");
    assert_eq!(c.edit_mode(), EditTools::ExtendOrtho);

    // The guarded exits must NOT clear unrelated pending state: with roof
    // mode OFF, `set_roof_mode(false)` (which drops `pending_redraw`) is not
    // called at all.
    c.pending_redraw = Some(PendingRedraw {
        stroke_points: vec![Point2f32::new(0.0, 0.0)],
        closed: true,
    });
    c.select_edit_tool(EditTools::Trim);
    assert!(
        c.pending_redraw.is_some(),
        "a pending redraw survives a tool pick (only the redraw prompt resolves it)"
    );
}

/// Picking Trim INSIDE living-area mode must keep the mode (and the active
/// living area) — the trim then applies to the LIVING AREA's ring, leaving
/// the storey outline untouched. Living-area / construction-year modes don't
/// block edit-tool strokes, so `select_edit_tool` deliberately does not exit
/// them (unlike the stroke-swallowing exposure/openings/roof/partition modes).
#[test]
fn trim_inside_living_area_mode_trims_the_living_area() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    let square = vec![
        Point2f32::new(0.0, 0.0),
        Point2f32::new(10.0, 0.0),
        Point2f32::new(10.0, 10.0),
        Point2f32::new(0.0, 10.0),
        Point2f32::new(0.2, 0.2),
    ];
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(&square, 0.5, true).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    let outline_verts = c.document.floor_plan.polygons()[0].len();

    // Draw a living area; it becomes the active shape.
    c.set_living_area_mode(true);
    c.apply_living_area_stroke_event(&[(2.0, 2.0), (6.0, 2.0), (6.0, 6.0), (2.0, 6.0), (2.1, 2.1)]);
    assert_eq!(c.active_living_area_index(), Some(0));
    let la_verts = c.document.floor_plan.polygons()[0].len();

    // Picking Trim from the toolbar keeps the living-area context.
    c.select_edit_tool(EditTools::Trim);
    assert!(
        c.living_area_mode(),
        "a tool pick stays inside living-area mode"
    );
    assert_eq!(
        c.active_living_area_index(),
        Some(0),
        "the living area stays active"
    );

    // Chamfer the living area's top-right corner (at ~(6, 6)).
    c.apply_trim_stroke_event(&[(6.2, 4.8), (4.8, 6.2)])
        .expect("trim applies to the active living area");
    assert_eq!(
        c.document.floor_plan.polygons()[0].len(),
        la_verts + 1,
        "the living area gained the chamfer vertex"
    );

    // The storey outline is untouched.
    c.set_living_area_mode(false);
    assert_eq!(
        c.document.floor_plan.polygons()[0].len(),
        outline_verts,
        "the storey outline is unaffected by the living-area trim"
    );
}

