/// Renaming a shared WINDOW TYPE from the Structure review drives
/// `AppController::rename_window_type` (mirroring the group rename): a valid
/// name lands on the type and clears any parked hint; a collision with
/// ANOTHER type's name or an empty name is rejected — the durable name keeps
/// its last valid value and the hint parks on `window_type_rename_error()`
/// until a valid rename (or a fresh review session) clears it.
#[test]
fn rename_window_type_streams_and_parks_rejections() {
    use ber_model::ber::fenestration::{Frame, Glazing};
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    // Two shared types, distinguished by name.
    let (a, b) = {
        let record = c.current_record.as_mut().unwrap();
        let a = record.data.ensure_window_type(
            Glazing::Double,
            Frame::WoodUPVC,
            2010,
            false,
            true,
            Vec::new(),
            Some("Alpha".into()),
        );
        let b = record.data.ensure_window_type(
            Glazing::Double,
            Frame::WoodUPVC,
            2010,
            false,
            true,
            Vec::new(),
            Some("Beta".into()),
        );
        (a, b)
    };
    let name_of = |c: &AppController, id| {
        c.current_record.as_ref().unwrap().data.window_types[..]
            .iter()
            .find(|t| t.id == id)
            .unwrap()
            .specifics
            .name()
            .map(str::to_owned)
    };

    // A valid rename lands and parks no hint.
    c.rename_window_type(a, "Gamma".into());
    assert_eq!(name_of(&c, a).as_deref(), Some("Gamma"));
    assert!(c.window_type_rename_error().is_none());

    // Another type's name is rejected: the durable name keeps its last valid
    // value and the hint parks against the edited type's id.
    c.rename_window_type(a, "Beta".into());
    assert_eq!(
        name_of(&c, a).as_deref(),
        Some("Gamma"),
        "rejected rename must not change the stored name"
    );
    let (eid, hint) = c.window_type_rename_error().expect("hint parked");
    assert_eq!(*eid, a);
    assert!(hint.contains("Beta"), "hint names the clash: {hint}");
    assert_eq!(
        name_of(&c, b).as_deref(),
        Some("Beta"),
        "the OTHER type is untouched"
    );

    // Empty (whitespace) is rejected too — a type requires a model name.
    c.rename_window_type(a, "   ".into());
    assert_eq!(name_of(&c, a).as_deref(), Some("Gamma"));
    assert!(
        c.window_type_rename_error().is_some(),
        "empty name parks a hint"
    );

    // The assessor keeps typing to a valid name: it lands and clears the hint.
    c.rename_window_type(a, "Delta".into());
    assert_eq!(name_of(&c, a).as_deref(), Some("Delta"));
    assert!(c.window_type_rename_error().is_none());

    // A stale hint doesn't outlive the review session.
    c.rename_window_type(a, "Beta".into());
    assert!(c.window_type_rename_error().is_some());
    c.set_structure_review_mode(true);
    assert!(
        c.window_type_rename_error().is_none(),
        "a fresh review session clears the parked hint"
    );
}

/// The "rename all" tick on the Edit-door box: Apply retypes EVERY door
/// sharing the old trimmed `type_name` (across the record) — doors group by
/// their free-text label, so renaming the label retypes the group — while a
/// door with a different name keeps it.
#[test]
fn review_rename_door_type_bulk_renames_matching_doors() {
    use ber_model::ber::fenestration::Overshading;
    let mut c = dimensioned_square_controller();
    c.set_default_ceiling_height(2.8).unwrap();
    c.materialize();
    // Three plain doors on three walls — all placed with the default type
    // name "Door"; the third is then retyped "Other" so the bulk rename has a
    // non-matching bystander.
    c.select_opening_tool(OpeningToolKind::Door);
    for (x, y) in [(5.0, -0.2), (10.2, 5.0), (5.0, 10.2)] {
        c.openings_pointer_down(x, y, 0.5);
        c.place_opening(
            0.9,
            2.0,
            false,
            false,
            None,
            None,
            None,
            WindowTypeChoice::default(),
            Overshading::Average,
            None,
            true,
            Vec::new(),
        )
        .expect("door places");
    }
    c.materialize();
    let other_id = {
        let record = c.current_record.as_mut().unwrap();
        let doors = &mut record.data.storeys[0].doors;
        assert_eq!(doors.len(), 3, "three doors placed");
        assert!(doors.iter().all(|d| d.type_name == "Door"));
        doors[2].type_name = "Other".to_string();
        doors[2].id
    };
    // The review-path rename: every "Door" becomes "Front door".
    c.rename_door_type("Door".to_string(), "Front door".to_string());
    let doors = &c.current_record.as_ref().unwrap().data.storeys[0].doors;
    assert_eq!(
        doors.iter().filter(|d| d.type_name == "Front door").count(),
        2,
        "both \"Door\" doors are bulk-renamed"
    );
    assert_eq!(
        doors.iter().find(|d| d.id == other_id).unwrap().type_name,
        "Other",
        "a non-matching door keeps its name"
    );
}

/// The Structure review offers a rename affordance on WINDOW-TYPE and DOOR
/// items: the window item carries the type's id + current model name (and the
/// parked rejection hint when one is targeted at it); the door item carries
/// its current type label as the bulk-rename key.
#[test]
fn structure_review_items_carry_window_and_door_rename_info() {
    use ber_model::ber::fenestration::Overshading;
    let mut c = dimensioned_square_controller();
    c.set_default_ceiling_height(2.8).unwrap();
    c.materialize();
    // One window (creating a shared type named "Alpha") + one door.
    c.select_opening_tool(OpeningToolKind::Window);
    c.openings_pointer_down(5.0, -0.2, 0.5);
    c.place_opening(
        1.2,
        1.0,
        false,
        false,
        None,
        None,
        None,
        WindowTypeChoice::New {
            glazing: ber_model::ber::fenestration::Glazing::Double,
            frame: ber_model::ber::fenestration::Frame::WoodUPVC,
            year: 2010,
            certified: false,
            draught_stripped: true,
            gap: Vec::new(),
            name: Some("Alpha".to_string()),
        },
        Overshading::Average,
        None,
        true,
        Vec::new(),
    )
    .expect("window places");
    c.select_opening_tool(OpeningToolKind::Door);
    c.openings_pointer_down(10.2, 5.0, 0.5);
    c.place_opening(
        0.9,
        2.0,
        false,
        false,
        None,
        None,
        None,
        WindowTypeChoice::default(),
        Overshading::Average,
        None,
        true,
        Vec::new(),
    )
    .expect("door places");
    c.materialize();
    let type_id = c.current_record.as_ref().unwrap().data.window_types[0].id;

    let items = c.structure_review_items();
    let window_item = items
        .iter()
        .find(|i| i.kind == StructureReviewKind::WindowType)
        .expect("a window-type review item");
    match window_item.rename.as_ref() {
        Some(StructureReviewRename::WindowType {
            id, name, error, ..
        }) => {
            assert_eq!(*id, type_id, "rename targets the shared type");
            assert_eq!(name, "Alpha", "prefill is the current model name");
            assert!(error.is_none(), "no hint parked yet");
        }
        other => panic!("expected a WindowType rename, got {:?}", other.is_some()),
    }
    let door_item = items
        .iter()
        .find(|i| i.kind == StructureReviewKind::Door)
        .expect("a door review item");
    match door_item.rename.as_ref() {
        Some(StructureReviewRename::Door { type_name }) => {
            assert_eq!(type_name, "Door", "prefill/key is the door's label");
        }
        other => panic!("expected a Door rename, got {:?}", other.is_some()),
    }

    // A refused rename parks its hint ON the window item (id-matched).
    c.rename_window_type(type_id, "   ".into());
    let items = c.structure_review_items();
    let window_item = items
        .iter()
        .find(|i| i.kind == StructureReviewKind::WindowType)
        .unwrap();
    match window_item.rename.as_ref() {
        Some(StructureReviewRename::WindowType { error, .. }) => {
            assert!(error.is_some(), "the parked hint rides the review item");
        }
        _ => panic!("expected a WindowType rename"),
    }
}

// ----- storey-junction mismatch (floor vs the ceiling below) -------------

/// Field case "56 Elmwood Road": a floor hand-stepped BELOW the ceiling it
/// rests on (the junction derive can't bury the seam — it mints wall slivers
/// and churns settled exposure) must be VISIBLE: a "Storey junctions"
/// checklist row goes red naming the neighbour + gap + zone size, and the
/// plan's step-zone display flags the zone with the gap in its label.
/// Deleting the bad step heals both.
#[test]
fn junction_mismatch_surfaces_in_checklist_and_plan_zones() {
    let mut c = dimensioned_square_controller(); // storey 0 = 10×10
    c.set_default_ceiling_height(2.4).unwrap();

    // Single-storey: no junction row at all (nothing to junction against).
    assert!(
        !c.stage_a_checklist()
            .iter()
            .any(|i| i.label == "Storey junctions"),
        "no junction row on a single-storey dwelling"
    );

    c.add_storey().unwrap();
    finalise_current_storey_as_square(&mut c, 6.0); // storey 1 = 6×6 over it
    c.set_default_ceiling_height(2.4).unwrap();
    c.materialize();

    let junction_row = |c: &AppController| {
        c.stage_a_checklist()
            .into_iter()
            .find(|i| i.label == "Storey junctions")
            .expect("junction row present on a multi-storey dwelling")
    };
    // Aligned junction (flat below ceiling, level-0 floor): green, no zones.
    let item = junction_row(&c);
    assert_eq!(
        item.status,
        ChecklistStatus::AllStoreys,
        "aligned: {:?}",
        item.reasons
    );
    assert!(c.floor_step_zone_polygons().is_empty(), "no steps yet");

    // Hand-step part of storey 1's floor 0.25 m DOWN — into the ceiling
    // below (no matching ceiling step exists under it).
    let p = |x: f32, y: f32| Point2f32::new(x, y);
    c.step_regions.entry(1).or_default().push(StepRegion {
        polygon: vec![p(1.0, 1.0), p(4.0, 1.0), p(4.0, 4.0), p(1.0, 4.0)],
        level_m: -0.25,
    });
    c.mark_dirty().unwrap();
    c.materialize();

    let item = junction_row(&c);
    assert_eq!(item.status, ChecklistStatus::Incomplete);
    assert_eq!(item.reasons.len(), 1, "reasons: {:?}", item.reasons);
    assert!(
        item.reasons[0].contains("Floor sits 0.25 m below")
            && item.reasons[0].contains("ceiling over a 9.0 m² zone"),
        "reason names gap + neighbour + zone: {}",
        item.reasons[0]
    );
    // A junction mismatch blocks Mapping completion outright.
    assert!(!c.mapping_complete());

    // The plan display data: the stepped zone shows, flagged, its label
    // carrying level AND gap (drawn in the warning colour by the canvas).
    let zones = c.floor_step_zone_polygons();
    let flagged: Vec<_> = zones.iter().filter(|z| z.warning).collect();
    assert_eq!(flagged.len(), 1, "zones: {zones:?}");
    assert!(
        flagged[0].label.contains("▼ 0.25 m")
            && flagged[0].label.contains("⚠ 0.25 m into the ceiling below"),
        "label: {}",
        flagged[0].label
    );

    // Deleting the bad step heals the row and clears the warning zone.
    c.delete_step_region(0);
    c.materialize();
    let item = junction_row(&c);
    assert_eq!(
        item.status,
        ChecklistStatus::AllStoreys,
        "healed: {:?}",
        item.reasons
    );
    assert!(
        c.floor_step_zone_polygons().iter().all(|z| !z.warning),
        "no warning zones left"
    );
}

/// A LEGITIMATE split-level junction — the below ceiling stepped and the
/// upper floor seeded to match — shows its step zone on the plan (level
/// label, no warning) and keeps the junction row green: the display marks
/// geometry, the warning only physical impossibility.
#[test]
fn aligned_floor_step_shows_zone_without_warning() {
    let mut c = dimensioned_square_controller(); // storey 0 = 10×10
    c.set_default_ceiling_height(2.4).unwrap();
    // Step the below ceiling UP by 0.3 over x ≥ 5 (regions-as-truth: apply
    // straight onto the resolved record, as the ceiling-step flow would).
    c.materialize();
    {
        let record = c.current_record.as_mut().unwrap();
        let ring = vec![
            Point2f64::new(5.0, 0.0),
            Point2f64::new(10.0, 0.0),
            Point2f64::new(10.0, 10.0),
            Point2f64::new(5.0, 10.0),
        ];
        record.data.storeys[0].ceilings =
            std::mem::take(&mut record.data.storeys[0].ceilings).with_z_deltas(&[(ring, 0.3)]);
    }

    c.add_storey().unwrap();
    finalise_current_storey_as_square(&mut c, 10.0); // full footprint above
    c.set_default_ceiling_height(2.4).unwrap();
    // Seed the inherited step the add-storey flow derives: +0.3 over x ≥ 5.
    let p = |x: f32, y: f32| Point2f32::new(x, y);
    c.step_regions.entry(1).or_default().push(StepRegion {
        polygon: vec![p(5.0, 0.0), p(10.0, 0.0), p(10.0, 10.0), p(5.0, 10.0)],
        level_m: 0.3,
    });
    c.mark_dirty().unwrap();
    c.materialize();

    let item = c
        .stage_a_checklist()
        .into_iter()
        .find(|i| i.label == "Storey junctions")
        .unwrap();
    assert_eq!(
        item.status,
        ChecklistStatus::AllStoreys,
        "matched step is aligned: {:?}",
        item.reasons
    );
    let zones = c.floor_step_zone_polygons();
    assert_eq!(zones.len(), 1, "the raised zone displays: {zones:?}");
    assert!(
        zones[0].label.contains("▲ 0.30 m") && !zones[0].warning,
        "level label, no warning: {:?}",
        zones[0]
    );
}

// ----- subtract-don't-split: legacy split-record migration (plan §4, §6 step 3)

/// Local mirror of ber_model's sliver invariant (its `MIN_SUBWALL_M` is
/// `pub(crate)`): every wall region of every storey must clear the sub-wall
/// floor in area AND bounding-box minor dimension (plan extent vs z extent).
/// Asserted at the controller level so the FULL pipeline (resolve →
/// stamp-all → derive tail → openings re-link) is what's being measured.
fn assert_no_degenerate_walls_ber(ber: &ber_model::ber::ber_struct::Ber) {
    const MIN_SUBWALL_M: f64 = 0.01; // mirrors ber_model::structural::wall_regions
    for (si, s) in ber.storeys.iter().enumerate() {
        for w in &s.walls.regions {
            let area = w.polygon.area();
            assert!(
                area > MIN_SUBWALL_M * MIN_SUBWALL_M,
                "storey {si}: wall {:?} has sliver area {area}",
                w.id
            );
            let (mut xmin, mut xmax) = (f64::INFINITY, f64::NEG_INFINITY);
            let (mut ymin, mut ymax) = (f64::INFINITY, f64::NEG_INFINITY);
            let (mut zmin, mut zmax) = (f64::INFINITY, f64::NEG_INFINITY);
            for v in &w.polygon.exterior {
                xmin = xmin.min(v.x);
                xmax = xmax.max(v.x);
                ymin = ymin.min(v.y);
                ymax = ymax.max(v.y);
                zmin = zmin.min(v.z);
                zmax = zmax.max(v.z);
            }
            let plan_extent = (xmax - xmin).hypot(ymax - ymin);
            assert!(
                plan_extent.min(zmax - zmin) > MIN_SUBWALL_M,
                "storey {si}: wall {:?} has a sliver minor dimension (plan {plan_extent}, z {})",
                w.id,
                zmax - zmin
            );
        }
    }
}

/// Storey 1's wall pieces lying on the y=4 base line, split into
/// (labellable, InterStorey bands).
#[allow(clippy::type_complexity)]
fn y4_run_walls(
    s: &ber_model::ber::structural::Storey,
) -> (
    Vec<&ber_model::ber::structural::WallRegion>,
    Vec<&ber_model::ber::structural::WallRegion>,
) {
    s.walls
        .regions
        .iter()
        .filter(|w| w.polygon.exterior.iter().all(|v| (v.y - 4.0).abs() < 1e-6))
        .partition(|w| w.exposure != ber_model::ber::structural::WallExposure::InterStorey)
}

/// The Elmwood stack on the CONTROLLER (mirror of ber_model's
/// `elmwood_fixture`, which pins the geometry half): ground 8×4 with the
/// front strip y∈[0,2] flat at 2.4 (the datum anchor) and the back strip at
/// 3.04 carrying a raised zone x∈[zx0,zx1] at `raised_z`; first storey 8×4,
/// slab 0.3, ceiling 2.4 — so the upper y=4 wall is backed by band tops
/// 0.34 / (raised_z−2.7) / 0.34 storey-local. Every upper wall is painted
/// Exposed and the y=4 host gets a CavityWall construction with an assigned
/// PHASE via the durable SurfaceRef doc-map. Ground ceilings are hand-set on
/// the record (regions-as-truth: same footprint area+bbox, so every resolve
/// keeps them verbatim — the same mechanism a real raised-ceiling record
/// rides). Returns the controller in the MODERN derived state.
fn elmwood_migration_controller(raised_z: f64, zx0: f64, zx1: f64) -> AppController {
    use ber_model::ber::common::ConstructionPhase;
    use ber_model::ber::structural::{
        CeilingRegion, CeilingRegions, Polygon3D, WallConstructionType,
    };
    use domain::points::Point3f64;

    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "Elmwood".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 7, 25).unwrap(),
    );
    finalise_current_storey_as_rect(&mut c, 8.0, 4.0);
    c.set_default_ceiling_height(2.4).unwrap();
    c.materialize();
    // Hand-set the ground ceilings (keep the derived default's construction).
    let flat = |x0: f64, y0: f64, x1: f64, y1: f64, z: f64, cid| CeilingRegion {
        id: Default::default(),
        polygon: Polygon3D::new(vec![
            Point3f64::new(x0, y0, z),
            Point3f64::new(x1, y0, z),
            Point3f64::new(x1, y1, z),
            Point3f64::new(x0, y1, z),
        ]),
        opes: Default::default(),
        construction_id: cid,
        exposure: Default::default(),
    };
    {
        let ber = &mut c.current_record.as_mut().unwrap().data;
        let cid = ber.storeys[0].ceilings.regions[0].construction_id;
        let mut regions = vec![flat(0.0, 0.0, 8.0, 2.0, 2.4, cid)];
        if zx0 > 0.0 {
            regions.push(flat(0.0, 2.0, zx0, 4.0, 3.04, cid));
        }
        regions.push(flat(zx0, 2.0, zx1, 4.0, raised_z, cid));
        if zx1 < 8.0 {
            regions.push(flat(zx1, 2.0, 8.0, 4.0, 3.04, cid));
        }
        ber.storeys[0].ceilings = CeilingRegions { regions };
    }
    c.mark_dirty().unwrap();
    c.materialize();

    // The upper storey: slab 0.3 → datum 2.7 (anchored on the front strip).
    c.add_storey().unwrap();
    c.assign_floor_thickness(0.3).unwrap();
    c.choose_draw_outline();
    finalise_current_storey_as_rect(&mut c, 8.0, 4.0);
    c.set_default_ceiling_height(2.4).unwrap();
    let datums = c
        .current_record
        .as_ref()
        .unwrap()
        .data
        .storey_floor_datums();
    assert!(
        (datums[1] - 2.7).abs() < 1e-9,
        "datum anchors on the front strip, got {datums:?}"
    );

    // Paint every upper perimeter wall Exposed (1-D sections, full spans).
    c.set_exposure_mode(true);
    let mids: Vec<(f64, f64)> = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .iter()
        .map(|(_, a, b)| (((a.x + b.x) * 0.5) as f64, ((a.y + b.y) * 0.5) as f64))
        .collect();
    for (mx, my) in mids {
        c.exposure_pointer_down(mx, my, 0.5);
        c.set_wall_exposure(WallExposure::Exposed);
    }
    c.set_exposure_mode(false);
    c.materialize();

    // MODERN-state sanity (the ber_model fixture pins this in depth): ONE
    // exposed wall on the y=4 run.
    let host_id = {
        let s1 = &c.current_record.as_ref().unwrap().data.storeys[1];
        let (exposed, bands) = y4_run_walls(s1);
        assert_eq!(exposed.len(), 1, "modern state: one exposed y=4 wall");
        assert!(!bands.is_empty(), "modern state: InterStorey band(s)");
        exposed[0].id
    };
    // Construction + PHASE onto the run via the durable SurfaceRef doc-map
    // (`set_wall_construction_for` keys it parametrically, so it must land on
    // the unified wall after any re-derive/migration).
    c.set_wall_construction_for(
        &[host_id],
        WallConstructionType::CavityWall,
        Default::default(),
        ConstructionPhase::Original,
        None,
    );
    c.materialize();
    c
}

/// Place a window on the upper storey's y=4 wall at plan x (tap 0.2 m
/// outside), 0.6 × 0.8 m with the given (host-base-relative) sill.
fn place_y4_window(c: &mut AppController, x: f64, sill: f32) {
    use ber_model::ber::fenestration::{Frame, Glazing};
    c.select_opening_tool(OpeningToolKind::Window);
    c.openings_pointer_down(x, 4.2, 0.5);
    assert!(
        c.pending_opening_prompt().is_some(),
        "the y=4 wall was picked at x={x}"
    );
    c.place_pending_window(0.6, 0.8, sill, Glazing::Double, Frame::WoodUPVC, 2010)
        .expect("window places");
}

/// One window's captured MODERN placement: `(id, plan x of centre, world
/// z-lo, world z-hi, stored sill)` — the world rectangle is the migration
/// invariant, the stored sill re-checks "rebased exactly once".
type ModernWindow = (ber_model::ber::common::ItemId, f64, f64, f64, f32);

/// Capture the modern y=4 host + each window's world rectangle off the
/// resolved record (world lo = host base_z + stored sill).
fn capture_modern_y4(
    s1: &ber_model::ber::structural::Storey,
) -> (ber_model::ber::structural::WallRegion, Vec<ModernWindow>) {
    use ber_model::ber::fenestration::OpeningPlacement;
    let (exposed, _) = y4_run_walls(s1);
    assert_eq!(exposed.len(), 1, "one exposed wall on the y=4 run");
    let host = exposed[0].clone();
    let (o, (ux, _uy), _len, ubase) = host.base_frame().expect("host base frame");
    let mut out = Vec::new();
    for w in &s1.windows {
        let Some(OpeningPlacement::Wall {
            wall_id,
            along_m,
            sill_m,
        }) = &w.placement
        else {
            panic!("window {:?} lost its wall placement", w.id);
        };
        assert_eq!(*wall_id, host.id, "modern window hosts on the y=4 wall");
        let cx = o.x + ux * (*along_m as f64);
        let lo = ubase + *sill_m as f64;
        out.push((w.id, cx, lo, lo + w.height_m as f64, *sill_m));
    }
    (host, out)
}

/// Rewrite storey 1's y=4 run into the OLD split output — flat-bottom strips
/// (one per band-top), optionally plus a sub-sliver strip, with every window
/// re-pointed at its strip under PIECE-RELATIVE sill storage — mimicking a
/// pre-change DB row ("56 Elmwood Road"). `pieces` are `(x0, x1, base_z)`.
fn rewrite_y4_run_as_legacy_split(c: &mut AppController, pieces: &[(f64, f64, f64)], sliver: bool) {
    use ber_model::ber::fenestration::OpeningPlacement;
    use ber_model::ber::structural::{Polygon3D, WallExposure, WallRegion};
    use domain::points::Point3f64;
    let ber = &mut c.current_record.as_mut().unwrap().data;
    let s1 = &mut ber.storeys[1];
    let uidx = s1
        .walls
        .regions
        .iter()
        .position(|w| {
            w.exposure != WallExposure::InterStorey
                && w.polygon.exterior.iter().all(|v| (v.y - 4.0).abs() < 1e-6)
        })
        .expect("the modern unified y=4 wall");
    let unified = s1.walls.regions.remove(uidx);
    let (o, (ux, _uy), _len, ubase) = unified.base_frame().expect("unified frame");
    let top_z = unified
        .polygon
        .exterior
        .iter()
        .map(|v| v.z)
        .fold(f64::NEG_INFINITY, f64::max);
    let mut legacy: Vec<(ber_model::ber::common::ItemId, f64, f64, f64)> = Vec::new();
    let mut strips: Vec<(f64, f64, f64)> = pieces.to_vec();
    if sliver {
        // The old pass's boundary leftover: an 8 mm strip hugging a run end.
        let &(_, x1, bz) = pieces
            .iter()
            .find(|p| p.2 > pieces[0].2)
            .unwrap_or(&pieces[0]);
        strips.push((x1 - 0.008, x1, bz));
    }
    for &(x0, x1, bz) in &strips {
        let id = ber_model::ber::common::ItemId::default();
        legacy.push((id, x0, x1, bz));
        s1.walls.regions.push(WallRegion {
            id,
            polygon: Polygon3D::new(vec![
                Point3f64::new(x0, 4.0, bz),
                Point3f64::new(x1, 4.0, bz),
                Point3f64::new(x1, 4.0, top_z),
                Point3f64::new(x0, 4.0, top_z),
            ]),
            exposure: WallExposure::Exposed,
            opes: Default::default(),
            construction_id: unified.construction_id,
        });
    }
    // Re-point each window at the strip containing its centre, with the sill
    // re-based to the STRIP's flat bottom (the old storage semantics), and
    // along measured from the strip's own x0 end.
    let mut links: Vec<(
        ber_model::ber::common::ItemId,
        ber_model::ber::common::ItemId,
    )> = Vec::new();
    for w in &mut s1.windows {
        let Some(OpeningPlacement::Wall {
            wall_id,
            along_m,
            sill_m,
        }) = &mut w.placement
        else {
            continue;
        };
        if *wall_id != unified.id {
            continue;
        }
        let cx = o.x + ux * (*along_m as f64);
        let lo = ubase + *sill_m as f64;
        let &(pid, x0, _x1, bz) = legacy
            .iter()
            .find(|&&(_, x0, x1, _)| cx >= x0 - 1e-6 && cx <= x1 + 1e-6)
            .expect("a legacy strip hosts the window");
        *wall_id = pid;
        *along_m = (cx - x0) as f32;
        *sill_m = (lo - bz) as f32;
        links.push((pid, w.id));
    }
    assert_eq!(
        links.len(),
        s1.windows.len(),
        "every window re-pointed at a legacy strip"
    );
    for (pid, wid) in links {
        let piece = s1.walls.regions.iter_mut().find(|r| r.id == pid).unwrap();
        piece.opes.windows.push(wid);
    }
}

/// Storey 1's walls+windows serialized with the wall-region ids NORMALIZED
/// to ring-sorted tokens: region ids re-mint on every resolve BY DESIGN
/// (durable identity is parametric), so byte-stability across save→load→save
/// is asserted on everything EXCEPT the minting — geometry, exposures,
/// constructions, placements (sill/along), anchors, vertices, opes.
fn walls_windows_fingerprint(s1: &ber_model::ber::structural::Storey) -> String {
    let mut json = serde_json::to_string(&(&s1.walls, &s1.windows)).unwrap();
    let mut walls: Vec<&ber_model::ber::structural::WallRegion> = s1.walls.regions.iter().collect();
    walls.sort_by_key(|w| format!("{:?}", w.polygon.exterior));
    for (i, w) in walls.iter().enumerate() {
        json = json.replace(&w.id.to_string(), &format!("wall#{i}"));
    }
    json
}

/// THE MIGRATION PROOF (plan §4 + §6 step 3, fixture of record "56 Elmwood
/// Road"): a saved record shaped like the OLD split output — the upper y=4
/// run stored as THREE flat-bottom Exposed strips (bottoms 0.34/0.79/0.34)
/// plus a sub-sliver, four windows spread 0+2+2 across the strips with
/// PIECE-RELATIVE sills — unifies on `open_ber`:
///  - ONE non-InterStorey wall on the base line, underside stepping
///    0.34 → 0.79 → 0.34, per-run bands intact;
///  - every window re-linked to it (placement + opes), WORLD rectangles
///    unchanged (computed from the legacy host base_z + sill before);
///  - stored sills rebased EXACTLY once (back to the run's 0.34 base — the
///    modern values), pinned by save→load→save fingerprint equality, id
///    minting normalized out;
///  - painted exposure survives as the wall's Exposed stamp, checklist
///    counts 0 unset; the SurfaceRef-keyed construction+phase land on the
///    unified wall; no degenerate wall anywhere, including after a second
///    materialize.
#[test]
fn elmwood_legacy_split_record_unifies_on_open_with_world_rects_stable() {
    use ber_model::ber::common::ConstructionPhase;
    use ber_model::ber::fenestration::OpeningPlacement;
    use ber_model::ber::structural::{WallConstructionType, WallExposure};

    let mut c = elmwood_migration_controller(3.49, 2.0, 6.0);
    // Four windows, 0+2+2: none on x∈[0,2], two over the raised zone
    // (min-sill clamp there is 0.45 above the 0.34 base), two on x∈[6,8].
    place_y4_window(&mut c, 2.9, 0.8);
    place_y4_window(&mut c, 5.1, 1.0);
    place_y4_window(&mut c, 6.5, 0.6);
    place_y4_window(&mut c, 7.4, 0.6);
    c.materialize();

    let (modern_host, modern) = {
        let s1 = &c.current_record.as_ref().unwrap().data.storeys[1];
        assert_eq!(s1.windows.len(), 4, "all four windows placed");
        capture_modern_y4(s1)
    };
    let (_, _, _, modern_base_z) = modern_host.base_frame().unwrap();
    assert!(
        (modern_base_z - 0.34).abs() < 1e-6,
        "modern host base anchors the low runs, got {modern_base_z}"
    );

    // Rewrite into the pre-change DB row and save it.
    rewrite_y4_run_as_legacy_split(
        &mut c,
        &[(0.0, 2.0, 0.34), (2.0, 6.0, 0.79), (6.0, 8.0, 0.34)],
        true,
    );
    {
        // The legacy row really is piece-relative: the middle-strip windows'
        // stored sills DIFFER from the modern values by the 0.45 notch.
        let s1 = &c.current_record.as_ref().unwrap().data.storeys[1];
        let mid = modern
            .iter()
            .find(|(_, cx, ..)| (*cx - 2.9).abs() < 0.2)
            .unwrap();
        let w = s1.windows.iter().find(|w| w.id == mid.0).unwrap();
        let Some(OpeningPlacement::Wall { sill_m, .. }) = &w.placement else {
            panic!("wall placement");
        };
        assert!(
            (*sill_m - (mid.4 - 0.45)).abs() < 1e-5,
            "legacy sill is piece-relative: {} vs modern {}",
            sill_m,
            mid.4
        );
    }
    c.persist().unwrap();
    let id = c.current_record.as_ref().unwrap().id.clone();

    // MIGRATE: reload the pre-change row.
    c.open_ber(&id).unwrap();
    {
        let ber = &c.current_record.as_ref().unwrap().data;
        let s1 = &ber.storeys[1];
        let (exposed, bands) = y4_run_walls(s1);
        assert_eq!(exposed.len(), 1, "the legacy strips unified on load");
        let host = exposed[0];
        assert_eq!(host.exposure, WallExposure::Exposed, "paint survived");
        let (_, _, len, base_z) = host.base_frame().expect("unified base frame");
        assert!((len - 8.0).abs() < 1e-6, "full-run frame, got {len}");
        assert!((base_z - 0.34).abs() < 1e-6);
        for (along, want) in [(1.0, 0.34), (4.0, 0.79), (7.0, 0.34)] {
            let z = host.base_z_at_along(along);
            assert!(
                (z - want).abs() < 1e-6,
                "base_z_at_along({along}) = {z}, want {want}"
            );
        }
        assert_eq!(bands.len(), 3, "per-run InterStorey bands survive");
        // Windows: all four on the unified wall, opes carry them, world
        // rectangles unchanged, sills rebased exactly once (the modern
        // values, base 0.34).
        assert_eq!(s1.windows.len(), 4, "no window pruned by the migration");
        for (wid, cx, lo, hi, modern_sill) in &modern {
            let w = s1.windows.iter().find(|w| w.id == *wid).unwrap();
            let Some(OpeningPlacement::Wall {
                wall_id,
                along_m,
                sill_m,
            }) = &w.placement
            else {
                panic!("window {wid:?} lost its wall placement");
            };
            assert_eq!(*wall_id, host.id, "window re-linked to the unified wall");
            assert!(host.opes.windows.contains(wid), "opes carry window {wid:?}");
            let (o, (ux, _), _, base_z) = host.base_frame().unwrap();
            let got_cx = o.x + ux * (*along_m as f64);
            let got_lo = base_z + *sill_m as f64;
            let got_hi = got_lo + w.height_m as f64;
            assert!(
                (got_cx - cx).abs() < 2e-4,
                "window {wid:?} slid along the wall: {got_cx} vs {cx}"
            );
            assert!(
                (got_lo - lo).abs() < 2e-4 && (got_hi - hi).abs() < 2e-4,
                "window {wid:?} world rect moved: [{got_lo},{got_hi}] vs [{lo},{hi}]"
            );
            assert!(
                (*sill_m - modern_sill).abs() < 2e-4,
                "sill rebased once back to the run base: {sill_m} vs {modern_sill}"
            );
        }
        // Checklist: nothing came back unclassified (this pinned a REAL gap:
        // the side walls' 0.64 m-notched L-remainders used to recover only
        // their floor-band-truncated base span, reloading the back half
        // Unset — see `recover_wall_region_span`'s full-extent span).
        assert!(
            document::wall_exposure_reasons(ber, 1).is_empty(),
            "no exposure churn: {:?}",
            document::wall_exposure_reasons(ber, 1)
        );
        // Construction + phase (SurfaceRef doc-map) landed on the unified wall.
        let wc = ber.wall_construction(host.construction_id).expect("fabric");
        assert_eq!(wc.construction_type, WallConstructionType::CavityWall);
        assert_eq!(wc.base.construction_phase, ConstructionPhase::Original);
        assert_no_degenerate_walls_ber(ber);
    }
    // The painted 1-D model holds ONE full-span Exposed section for the run.
    {
        let sd = &c.document.storeys[1];
        let (vid, a, b) = sd
            .outline
            .floor_plan
            .perimeter_walls()
            .into_iter()
            .find(|(_, a, b)| (a.y - 4.0).abs() < 1e-3 && (b.y - 4.0).abs() < 1e-3)
            .expect("the y=4 plan wall");
        let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
        let secs = sd.wall_sections.get(&vid).expect("painted sections");
        assert_eq!(secs.len(), 1, "one section on the run: {secs:?}");
        assert_eq!(secs[0].exposure, WallExposure::Exposed);
        assert!(
            secs[0].start_m < 1e-3 && (secs[0].end_m - len).abs() < 1e-3,
            "full span: {secs:?}"
        );
    }

    // Second materialize (double-derive through the whole pipeline): still
    // one unified wall, still sliver-free.
    c.mark_dirty().unwrap();
    c.materialize();
    let fp1 = {
        let ber = &c.current_record.as_ref().unwrap().data;
        let (exposed, _) = y4_run_walls(&ber.storeys[1]);
        assert_eq!(exposed.len(), 1, "re-derive keeps the unified wall");
        assert_no_degenerate_walls_ber(ber);
        walls_windows_fingerprint(&ber.storeys[1])
    };

    // Save → load → save: byte-stable modulo the by-design id re-mint —
    // in particular the sills do NOT rebase a second time.
    c.persist().unwrap();
    c.open_ber(&id).unwrap();
    c.materialize();
    let fp2 = walls_windows_fingerprint(&c.current_record.as_ref().unwrap().data.storeys[1]);
    assert_eq!(fp1, fp2, "save→load→save is stable (ids normalized)");
}

/// SNAPSHOT-LESS recovery over the legacy split (plan §2.3's test
/// obligation): with the editing snapshot unusable, `open_ber` rebuilds the
/// editing model FROM the legacy record — `sections_from_wall_regions` /
/// `recover_wall_region_span` must coalesce the three Exposed strips (+ the
/// sliver) into ONE full-span section, and the record-seeded SurfaceRef
/// store must still land the construction+phase on the unified wall.
#[test]
fn legacy_split_exposure_recovers_one_span_without_snapshot() {
    use ber_model::ber::common::ConstructionPhase;
    use ber_model::ber::structural::{WallConstructionType, WallExposure};

    let mut c = elmwood_migration_controller(3.49, 2.0, 6.0);
    c.materialize();
    rewrite_y4_run_as_legacy_split(
        &mut c,
        &[(0.0, 2.0, 0.34), (2.0, 6.0, 0.79), (6.0, 8.0, 0.34)],
        true,
    );
    c.persist().unwrap();
    let id = c.current_record.as_ref().unwrap().id.clone();
    // Kill the snapshot AFTER the save: the reload must take the legacy
    // (Layer-1-only) path a pre-feature record would.
    BerRepository::new(&c.conn)
        .save_snapshot(&id, PARAMETRIC_SNAPSHOT_VERSION + 1, 0, "not json")
        .unwrap();

    c.open_ber(&id).unwrap();
    // 1-D recovery: one coalesced full-span Exposed section on the run.
    {
        let sd = &c.document.storeys[1];
        let (vid, a, b) = sd
            .outline
            .floor_plan
            .perimeter_walls()
            .into_iter()
            .find(|(_, a, b)| (a.y - 4.0).abs() < 1e-3 && (b.y - 4.0).abs() < 1e-3)
            .expect("the y=4 plan wall");
        let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
        let secs = sd.wall_sections.get(&vid).expect("recovered sections");
        assert_eq!(
            secs.len(),
            1,
            "three strips + sliver coalesced to one span: {secs:?}"
        );
        assert_eq!(secs[0].exposure, WallExposure::Exposed);
        assert!(
            secs[0].start_m < 1e-3 && (secs[0].end_m - len).abs() < 1e-3,
            "full span: {secs:?}"
        );
    }
    // And the resolved record unified with everything re-stamped.
    let ber = &c.current_record.as_ref().unwrap().data;
    let (exposed, _) = y4_run_walls(&ber.storeys[1]);
    assert_eq!(exposed.len(), 1, "unified on the snapshot-less path too");
    assert_eq!(exposed[0].exposure, WallExposure::Exposed);
    assert!(
        document::wall_exposure_reasons(ber, 1).is_empty(),
        "0 unset: {:?}",
        document::wall_exposure_reasons(ber, 1)
    );
    let wc = ber
        .wall_construction(exposed[0].construction_id)
        .expect("fabric");
    assert_eq!(wc.construction_type, WallConstructionType::CavityWall);
    assert_eq!(wc.base.construction_phase, ConstructionPhase::Original);
    assert_no_degenerate_walls_ber(ber);
}

/// Step-2 note verified at the controller level (plan §2.1 base_edge band):
/// a remainder whose bottom steps MORE than `MAX_FLOOR_STEP_M` (0.6) — the
/// raised zone at the far half of the run, band tops 0.34 → 1.29 — keeps its
/// base FRAME truncated to the LOW run, and a legacy two-strip record still
/// re-links its low-span windows onto the unified wall with world rects
/// unchanged.
#[test]
fn legacy_split_with_over_step_remainder_relinks_low_span_windows() {
    use ber_model::ber::fenestration::OpeningPlacement;
    use ber_model::ber::structural::WallExposure;

    // Raised zone x∈[4,8] at absolute 3.99 → storey-local band top 1.29,
    // a 0.95 m bottom step (> MAX_FLOOR_STEP_M).
    let mut c = elmwood_migration_controller(3.99, 4.0, 8.0);
    place_y4_window(&mut c, 1.5, 0.8);
    place_y4_window(&mut c, 3.0, 0.8);
    c.materialize();

    let (modern_host, modern) = {
        let s1 = &c.current_record.as_ref().unwrap().data.storeys[1];
        capture_modern_y4(s1)
    };
    // The >0.6 m step means the base FRAME cannot span both runs at floor
    // level: it either truncates to the low run (ring starting there) or
    // anchors on the high shoulder (ring starting there — this fixture's
    // orientation, base_z 1.29 over the full span). Either way the UNDERSIDE
    // query must read the true profile at the window stations; the exact
    // frame choice is ber_model's pin, not this test's.
    let (o, (ux, uy), _len, _base_z) = modern_host.base_frame().unwrap();
    for (x, want) in [(1.5, 0.34), (3.0, 0.34), (6.0, 1.29)] {
        let along = (x - o.x) * ux + (4.0 - o.y) * uy;
        let z = modern_host.base_z_at_along(along);
        assert!(
            (z - want).abs() < 1e-6,
            "underside at x={x}: {z}, want {want}"
        );
    }

    rewrite_y4_run_as_legacy_split(&mut c, &[(0.0, 4.0, 0.34), (4.0, 8.0, 1.29)], false);
    c.persist().unwrap();
    let id = c.current_record.as_ref().unwrap().id.clone();
    c.open_ber(&id).unwrap();

    let ber = &c.current_record.as_ref().unwrap().data;
    let s1 = &ber.storeys[1];
    let (exposed, _) = y4_run_walls(s1);
    assert_eq!(exposed.len(), 1, "one exposed wall on the run");
    let host = exposed[0];
    assert_eq!(host.exposure, WallExposure::Exposed);
    assert_eq!(s1.windows.len(), 2, "no low-span window pruned");
    for (wid, cx, lo, hi, _) in &modern {
        let w = s1.windows.iter().find(|w| w.id == *wid).unwrap();
        let Some(OpeningPlacement::Wall {
            wall_id,
            along_m,
            sill_m,
        }) = &w.placement
        else {
            panic!("window {wid:?} lost its wall placement");
        };
        assert_eq!(*wall_id, host.id, "window re-linked to the unified wall");
        assert!(host.opes.windows.contains(wid), "opes carry {wid:?}");
        let (o, (ux, _), _, hbase) = host.base_frame().unwrap();
        let got_cx = o.x + ux * (*along_m as f64);
        let got_lo = hbase + *sill_m as f64;
        let got_hi = got_lo + w.height_m as f64;
        assert!(
            (got_cx - cx).abs() < 2e-4,
            "window {wid:?} slid: {got_cx} vs {cx}"
        );
        assert!(
            (got_lo - lo).abs() < 2e-4 && (got_hi - hi).abs() < 2e-4,
            "window {wid:?} world rect moved: [{got_lo},{got_hi}] vs [{lo},{hi}]"
        );
    }
    assert_no_degenerate_walls_ber(ber);
}

/// Step 4 (plan §2.2 ElevationView): the per-wall elevation editor's
/// `bottom_profile` traces the stepped underside of the subtracted wall
/// (band tops 0.34 → 0.79 → 0.34 on the Elmwood run) — derived from
/// `base_profile()` in the SAME base frame as `base_z`, so the drawn
/// underside and the sill math (`base_z + sill`) can never disagree.
#[test]
fn elevation_view_bottom_profile_steps_with_the_notch() {
    let mut c = elmwood_migration_controller(3.49, 2.0, 6.0);
    place_y4_window(&mut c, 1.5, 0.8);
    c.materialize();

    // The y=4 host's frame, for plan-x → along mapping.
    let (o, (ux, uy), _len, hbase) = {
        let s1 = &c.current_record.as_ref().unwrap().data.storeys[1];
        let (exposed, _) = y4_run_walls(s1);
        assert_eq!(exposed.len(), 1, "one exposed y=4 wall");
        exposed[0].base_frame().unwrap()
    };

    // Open the wall's elevation (Edit tap just outside the y=4 run).
    c.set_openings_mode(true);
    c.set_openings_tool(OpeningToolKind::Edit);
    c.openings_pointer_down(4.0, 4.2, 0.5);
    assert!(c.elevation_wall().is_some(), "elevation opened");
    let ev = c.elevation_view().expect("an elevation view");

    assert!(
        (ev.base_z as f64 - hbase).abs() < 1e-6,
        "base_z is the frame origin's z (the sill datum): {} vs {hbase}",
        ev.base_z
    );
    let interp = |along: f32| -> f32 {
        for w in ev.bottom_profile.windows(2) {
            let (a0, z0) = w[0];
            let (a1, z1) = w[1];
            let (lo, hi) = (a0.min(a1), a0.max(a1));
            if along >= lo - 1e-6 && along <= hi + 1e-6 && (a1 - a0).abs() > 1e-6 {
                return z0 + (z1 - z0) * ((along - a0) / (a1 - a0));
            }
        }
        panic!(
            "along {along} outside the bottom profile {:?}",
            ev.bottom_profile
        );
    };
    let along_at = |x: f64| ((x - o.x) * ux + (4.0 - o.y) * uy) as f32;
    // Storey-local band tops: 0.34 outside the raised zone, 0.79 over it.
    for (x, want) in [(1.0, 0.34f32), (4.0, 0.79), (7.0, 0.34)] {
        let got = interp(along_at(x));
        assert!(
            (got - want).abs() < 1e-3,
            "underside at x={x}: {got}, want {want} (profile {:?})",
            ev.bottom_profile
        );
    }
    // The placed window's drawn bottom (base_z + sill) sits on the expected
    // world line and clears the drawn underside at its along.
    assert_eq!(ev.openings.len(), 1, "the placed window unrolls");
    let op = &ev.openings[0];
    let world_bottom = ev.base_z + op.sill_m;
    assert!(
        (world_bottom - 1.14).abs() < 1e-3,
        "window bottom = 0.34 (base) + 0.8 (sill), got {world_bottom}"
    );
    assert!(
        world_bottom >= interp(op.along_m) - 1e-4,
        "the window clears the drawn underside"
    );
}

/// EXTEND-path collinearity review, settled-anchor rule: accepting a
/// suggestion must NEVER move a settled (dimensioned) wall — the fresh porch
/// wall is the one pulled onto the settled line. Field regression: the raw
/// detector order could put the settled wall in the B slot, and
/// `apply_collinear_suggestion` rewrites B onto A — an accept-all then
/// deformed a dimensioned plan by metres. The extend path now normalizes each
/// suggestion (`anchor_suggestions_to_known`) so side A is the settled one.
#[test]
fn extend_review_accept_never_moves_the_settled_wall() {
    let mut c = dimensioned_square_controller(); // 10×10, fully dimensioned
    c.set_edit_mode(EditTools::ExtendOrtho);
    // Porch off the RIGHT wall whose TOP run lands at y=8.5 — above the splice
    // snap leveller (~6% of the ring diagonal, ≈1.0 here — a smaller offset is
    // auto-flattened before any review) but within the 12% collinearity
    // tolerance (≈2.0) of the SETTLED top wall (y=10).
    c.apply_extend_stroke(&[
        Point2f32::new(10.0, 5.0),
        Point2f32::new(13.0, 5.0),
        Point2f32::new(13.0, 8.5),
        Point2f32::new(10.0, 8.5),
    ])
    .expect("porch extend");

    let sug = c
        .current_review_suggestion_clone()
        .expect("the y=8.5 run near the y=10 top wall raises a review");
    // Normalized: side A (the merge target that KEEPS its position) is the
    // settled top wall; side B is the fresh porch run.
    assert!(
        (sug.coord_a - 10.0).abs() < 1e-3,
        "settled wall must sit in the A slot, got coord_a={}",
        sug.coord_a
    );
    assert!((sug.coord_b - 8.5).abs() < 1e-3);

    c.accept_current_review().expect("accept the merge");

    let ring = &c.document.floor_plan.polygons()[0];
    // The DIMENSIONED top wall did not move: its corners are still at y=10...
    for corner in [(0.0, 10.0), (13.0, 10.0)] {
        assert!(
            ring.iter()
                .any(|p| (p.x - corner.0).abs() < 1e-3 && (p.y - corner.1).abs() < 1e-3),
            "settled top line must survive at {corner:?}, ring={ring:?}"
        );
    }
    // ...and the fresh porch run moved ONTO it (nothing left at y≈8.5).
    assert!(
        !ring.iter().any(|p| (p.y - 8.5).abs() < 0.05),
        "the unknown porch wall must be pulled onto the settled line, ring={ring:?}"
    );
    assert!(c.document.floor_plan.validate_simple().is_ok());
}

/// EXTEND-path review with BOTH sides unknown (two freshly-minted runs of the
/// same porch near each other): no side is settled, the detector's order is
/// preserved, and accepting still applies — the two runs merge onto one line.
#[test]
fn extend_review_both_unknown_still_applies() {
    let mut c = dimensioned_square_controller(); // 10×10, fully dimensioned
    c.set_edit_mode(EditTools::ExtendOrtho);
    // Stepped bump off the BOTTOM wall: two horizontal runs at y=-4.6 and
    // y=-3.2 — 1.4 apart (above the splice snap leveller ≈1.1, inside the 12%
    // review tolerance ≈2.1), and everything else out of tolerance: the runs
    // sit 3.2+ from the settled y=0 wall, the bump's verticals 2.5 from each
    // other and from the side walls.
    c.apply_extend_stroke(&[
        Point2f32::new(2.5, 0.0),
        Point2f32::new(2.5, -4.6),
        Point2f32::new(5.0, -4.6),
        Point2f32::new(5.0, -3.2),
        Point2f32::new(7.5, -3.2),
        Point2f32::new(7.5, 0.0),
    ])
    .expect("stepped bump extend");

    let sug = c
        .current_review_suggestion_clone()
        .expect("the two bump runs raise a review");
    let ys = [sug.coord_a, sug.coord_b];
    assert!(
        ys.iter().any(|y| (y + 4.6).abs() < 1e-3) && ys.iter().any(|y| (y + 3.2).abs() < 1e-3),
        "the pair is the two minted runs, got {ys:?}"
    );

    c.accept_current_review().expect("accept the merge");
    // The merge applied: the two runs share one line now (only ONE of the two
    // y-levels survives), and the settled y=0 wall is untouched.
    let ring = &c.document.floor_plan.polygons()[0];
    let has_y = |y: f32| ring.iter().any(|p| (p.y - y).abs() < 0.05);
    assert!(
        has_y(-4.6) ^ has_y(-3.2),
        "exactly one of the two runs' lines survives the merge, ring={ring:?}"
    );
    for corner in [(0.0, 0.0), (2.5, 0.0)] {
        assert!(
            ring.iter()
                .any(|p| (p.x - corner.0).abs() < 1e-3 && (p.y - corner.1).abs() < 1e-3),
            "the settled bottom wall stays at y=0, ring={ring:?}"
        );
    }
    assert!(c.document.floor_plan.validate_simple().is_ok());
}

/// The review highlight is resolved from the LIVE parametric plan — never
/// from the committed `storey.floors.regions`. Committed regions are EMPTY
/// during the deferred-derivation window (the assessor answered a whole
/// review blind when the highlight read them), and even when present their
/// ring/vertex layout differs from the live plan's. Pins:
///   * segments == the current suggestion's edge endpoints in the live plan,
///     with NO committed record at all (the hardest deferred window);
///   * the segments advance with the review cursor;
///   * None once the review drains.
#[test]
fn review_highlight_segments_come_from_the_live_plan() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    // A live plan with NO committed record — current_record is None, so any
    // regions-based highlight resolution would find nothing to draw.
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(
        &[
            Point2f32::new(0.0, 0.0),
            Point2f32::new(10.0, 0.0),
            Point2f32::new(10.0, 10.0),
            Point2f32::new(0.0, 10.0),
            Point2f32::new(0.05, 0.05),
        ],
        0.1,
        true,
    )
    .unwrap();
    assert!(
        c.current_record.is_none(),
        "the deferred window: nothing committed"
    );

    // Two hand-built suggestions over real square edges (the highlight only
    // reads ring/edge indices; the review machinery only skips pairs that are
    // already collinear or degenerate — neither applies here).
    let ring = c.document.floor_plan.polygons()[0].clone();
    let n = ring.len();
    let edge_where = |pred: &dyn Fn(Point2f32, Point2f32) -> bool| -> usize {
        (0..n)
            .find(|&i| pred(ring[i], ring[(i + 1) % n]))
            .expect("edge")
    };
    let bottom = edge_where(&|a, b| a.y.abs() < 1e-3 && b.y.abs() < 1e-3);
    let top = edge_where(&|a, b| (a.y - 10.0).abs() < 1e-3 && (b.y - 10.0).abs() < 1e-3);
    let left = edge_where(&|a, b| a.x.abs() < 1e-3 && b.x.abs() < 1e-3);
    let right = edge_where(&|a, b| (a.x - 10.0).abs() < 1e-3 && (b.x - 10.0).abs() < 1e-3);
    let s1 = CollinearitySuggestion {
        ring_a: 0,
        edge_a: bottom,
        ring_b: 0,
        edge_b: top,
        axis: Axis::Horizontal,
        coord_a: 0.0,
        coord_b: 10.0,
    };
    let s2 = CollinearitySuggestion {
        ring_a: 0,
        edge_a: left,
        ring_b: 0,
        edge_b: right,
        axis: Axis::Vertical,
        coord_a: 0.0,
        coord_b: 10.0,
    };
    c.review = Some(CollinearityReview {
        suggestions: vec![s1, s2],
        cursor: 0,
        rejections: Vec::new(),
    });

    let expect_edge = |e: usize| (ring[e], ring[(e + 1) % n]);
    let segs = c
        .review_highlight_segments()
        .expect("highlight resolves with an empty committed record");
    assert_eq!(segs[0], expect_edge(bottom), "A = the live bottom edge");
    assert_eq!(segs[1], expect_edge(top), "B = the live top edge");

    // Advance the cursor: the highlight follows the CURRENT suggestion.
    c.reject_current_review();
    let segs = c
        .review_highlight_segments()
        .expect("second suggestion still pending");
    assert_eq!(segs[0], expect_edge(left), "A = the live left edge");
    assert_eq!(segs[1], expect_edge(right), "B = the live right edge");

    // Drained review → no highlight.
    c.reject_current_review();
    assert!(c.review.is_none());
    assert!(c.review_highlight_segments().is_none());
}

/// EXTEND-path variant of the highlight test: the review raised by a real
/// extend resolves its highlight from the live plan, and the segments lie on
/// the suggestion's own coordinates — proving the (ring, edge) index space of
/// the suggestions and the live-plan lookup agree by construction.
#[test]
fn review_highlight_segments_match_the_extend_suggestion_coords() {
    let mut c = dimensioned_square_controller();
    c.set_edit_mode(EditTools::ExtendOrtho);
    c.apply_extend_stroke(&[
        Point2f32::new(10.0, 5.0),
        Point2f32::new(13.0, 5.0),
        Point2f32::new(13.0, 8.5),
        Point2f32::new(10.0, 8.5),
    ])
    .expect("porch extend");

    let sug = c.current_review_suggestion_clone().expect("review raised");
    let [seg_a, seg_b] = c.review_highlight_segments().expect("highlight resolves");
    // Horizontal pair: each segment's endpoints sit on its side's y coord.
    for (seg, coord) in [(seg_a, sug.coord_a), (seg_b, sug.coord_b)] {
        assert!(
            (seg.0.y - coord).abs() < 1e-3 && (seg.1.y - coord).abs() < 1e-3,
            "segment {seg:?} must lie on the suggestion's y={coord}"
        );
    }
}

/// PROVISIONAL live-outline preview, built-storey path. After an extend on a
/// dimensioned storey the resolve guard returns the PREVIOUS projection
/// untouched (the committed regions stay pre-extend — that is the DESIGNED
/// in-flux behaviour, pinned here), so without a preview the new walls are
/// invisible until dimensioning completes. `provisional_outline_rings` must
/// carry the live rings including the bump at its drawn/estimated position
/// while mid-dimensioning — and go back to None (with the committed regions
/// caught up) once the minted walls are dimensioned.
#[test]
fn extend_on_built_storey_shows_provisional_live_rings() {
    let mut c = dimensioned_square_controller(); // 10×10, committed, walls resolved
    c.materialize();
    assert!(
        c.provisional_outline_rings().is_none(),
        "fully dimensioned storey needs no provisional preview"
    );

    // Dormer bump off the bottom wall (no collinearity pair within tolerance,
    // so no review interleaves).
    c.set_edit_mode(EditTools::ExtendOrtho);
    c.apply_extend_stroke(&[
        Point2f32::new(3.0, 0.0),
        Point2f32::new(3.0, -3.0),
        Point2f32::new(7.0, -3.0),
        Point2f32::new(7.0, 0.0),
    ])
    .expect("dormer extend");
    c.materialize();

    // The committed regions are STILL the pre-extend square (in-flux guard).
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert!(
        !storey.walls.regions.is_empty(),
        "built storey keeps its previous resolve"
    );
    let committed_has_bump = storey
        .floors
        .regions
        .iter()
        .any(|r| r.polygon.exterior().coords().any(|q| q.y < -1.0));
    assert!(
        !committed_has_bump,
        "in-flux guard: committed floors stay pre-extend"
    );

    // ...but the provisional preview carries the live ring WITH the bump.
    let rings = c
        .provisional_outline_rings()
        .expect("mid-dimensioning on a built storey exposes the live rings");
    let has = |x: f64, y: f64| {
        rings.iter().any(|ring| {
            ring.iter()
                .any(|&(px, py)| (px - x).abs() < 1e-3 && (py - y).abs() < 1e-3)
        })
    };
    assert!(has(3.0, -3.0) && has(7.0, -3.0), "bump at drawn position");
    // The preview IS the live plan verbatim (same rings the highlight and
    // dimension prompts index into).
    let live: Vec<Vec<(f64, f64)>> = c
        .document
        .floor_plan
        .polygons()
        .into_iter()
        .map(|r| r.into_iter().map(|p| (p.x as f64, p.y as f64)).collect())
        .collect();
    assert_eq!(rings, live);

    // Dimension the minted walls: the preview retires and the committed
    // regions catch up.
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();
    assert!(
        c.provisional_outline_rings().is_none(),
        "preview gone once measurements are complete"
    );
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert!(
        storey.floors.regions.iter().any(|r| {
            r.polygon
                .exterior()
                .coords()
                .any(|q| (q.y - -3.0).abs() < 1e-3)
        }),
        "committed floors include the bump after dimensioning"
    );
}

/// PROVISIONAL preview, fresh-storey path (the diagnosis pin): on a storey
/// with NO resolved walls/ceilings, resolve's fresh-outline display exception
/// projects the LIVE outline as a bare floor each materialize — including
/// straight after an extend — so the preview channel stays None (overlaying
/// it would double the fill) and the display projection is NOT stale.
#[test]
fn fresh_storey_display_projection_tracks_an_extend() {
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    // Undimensioned outline (pixel space) — the fresh-draw window.
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(
        &[
            Point2f32::new(0.0, 0.0),
            Point2f32::new(10.0, 0.0),
            Point2f32::new(10.0, 10.0),
            Point2f32::new(0.0, 10.0),
            Point2f32::new(0.05, 0.05),
        ],
        0.1,
        true,
    )
    .unwrap();
    c.commit_to_ber().unwrap();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert!(
        !storey.floors.regions.is_empty() && storey.walls.regions.is_empty(),
        "fresh outline shows via the bare-floor display projection"
    );
    assert!(
        c.provisional_outline_rings().is_none(),
        "display projection already draws the live outline — no overlay"
    );

    // Extend the still-undimensioned outline: the projection must RE-FIRE
    // with the extended live ring (not stay on the pre-extend shape).
    c.set_edit_mode(EditTools::ExtendOrtho);
    c.apply_extend_stroke(&[
        Point2f32::new(3.0, 0.0),
        Point2f32::new(3.0, -3.0),
        Point2f32::new(7.0, -3.0),
        Point2f32::new(7.0, 0.0),
    ])
    .expect("extend on the fresh outline");
    c.materialize();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert!(
        storey.floors.regions.iter().any(|r| {
            r.polygon
                .exterior()
                .coords()
                .any(|q| (q.y - -3.0).abs() < 1e-2)
        }),
        "the display projection tracks the extended live outline"
    );
    assert!(
        c.provisional_outline_rings().is_none(),
        "still covered by the display projection — no overlay"
    );
}

/// ACCEPTANCE geometry from the live tablet record (57f413ef…): the
/// 14-vertex post-extend ring with the P9/P10/P11 extension section
/// (y −0.659…1.741) undimensioned. Mid-dimensioning, the provisional preview
/// must carry the FULL ring — extension at its estimated coords, min-y down
/// to −0.659 (the datum the render-side fit bbox unions in; the fit itself is
/// pure paint, verified live) — and the dimension loop must be prompting for
/// the extension's params.
#[test]
fn live_record_geometry_shows_the_full_provisional_ring() {
    let p = |x: f32, y: f32| Point2f32::new(x, y);
    let ring14 = [
        p(4.917, 15.220),
        p(7.917, 15.220),
        p(7.917, 14.220),
        p(9.917, 14.220),
        p(9.917, 14.720),
        p(12.917, 14.720),
        p(12.917, 6.720),
        p(12.417, 6.720),
        p(12.417, 5.220),
        p(11.917, 5.220),
        p(11.917, -0.659),
        p(7.704, -0.659),
        p(7.704, 1.741),
        p(4.917, 1.741),
    ];
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    c.document.floor_plan = FloorPlan::from_clean_ring(&ring14).unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    // Commit once fully-known so the storey resolves with WALLS (the built
    // state the in-flux guard preserves)...
    c.commit_to_ber().unwrap();
    assert!(
        !c.current_record.as_ref().unwrap().data.storeys[0]
            .walls
            .regions
            .is_empty(),
        "built storey"
    );

    // ...then mark the three extension walls' params unknown — the state the
    // extend's mint left the tablet in (P9/P10/P11).
    let edge_at = |c: &AppController, a: (f32, f32), b: (f32, f32)| -> usize {
        let ring = &c.document.floor_plan.polygons()[0];
        let n = ring.len();
        (0..n)
            .find(|&i| {
                let (q, r) = (ring[i], ring[(i + 1) % n]);
                (q.x - a.0).abs() < 1e-3
                    && (q.y - a.1).abs() < 1e-3
                    && (r.x - b.0).abs() < 1e-3
                    && (r.y - b.1).abs() < 1e-3
            })
            .expect("extension edge present")
    };
    for (a, b) in [
        ((11.917, -0.659), (7.704, -0.659)), // the P9 run
        ((7.704, -0.659), (7.704, 1.741)),   // the P10 run
        ((7.704, 1.741), (4.917, 1.741)),    // the P11 run
    ] {
        let e = edge_at(&c, a, b);
        let (param, _) = c
            .document
            .floor_plan
            .wall_movable_param(0, e)
            .expect("extension wall is parameter-movable");
        c.document.dimensioning.known_params.remove(&param);
    }
    c.mark_dirty().unwrap();
    c.materialize();
    assert!(
        !c.document.measurements_complete(),
        "mid-dimensioning: the extension is unknown"
    );

    let rings = c
        .provisional_outline_rings()
        .expect("the full live ring is previewed");
    assert_eq!(rings.len(), 1);
    assert_eq!(rings[0].len(), 14, "all 14 vertices at estimated positions");
    let has = |x: f64, y: f64| {
        rings[0]
            .iter()
            .any(|&(px, py)| (px - x).abs() < 1e-3 && (py - y).abs() < 1e-3)
    };
    assert!(
        has(11.917, -0.659) && has(7.704, -0.659),
        "extension bottom run"
    );
    assert!(has(7.704, 1.741) && has(4.917, 1.741), "extension top run");
    let min_y = rings[0].iter().map(|&(_, y)| y).fold(f64::MAX, f64::min);
    assert!(
        (min_y - -0.659).abs() < 1e-3,
        "the fit-bbox datum reaches y=-0.659, got {min_y}"
    );

    // The dimension loop is asking about the extension — the prompt's target
    // wall is on the previewed ring, not off in empty space.
    c.compute_next_dimension_prompt();
    assert!(
        c.document.dimensioning.current_prompt.is_some(),
        "the extension walls are being prompted for"
    );
}

/// The dimension prompt's highlight DATA is the live plan's edge for the
/// prompted param — endpoint COORDINATES, not just length (field report: a
/// 0.47 m jog prompted with the indicator painted at the wrong LOCATION).
/// Fixture mirrors the field: extend with a SHORT jog between two longer
/// near-collinear runs. For EVERY prompt of the loop, the UI data's primary
/// wall must be exactly the live plan's edge of `prompt.wall_start_vertex`,
/// and the "currently X m" figure must be that same edge's length. (The
/// on-screen displacement itself was a fit-transform mismatch, pinned
/// render-side by `storey_transform_unions_the_view_fit_include_bbox`.)
#[test]
fn dimension_prompt_ui_walls_are_the_live_plan_edges() {
    // A 4×4 dimensioned square: small enough that the splice snap leveller
    // (~6% of the ring diagonal ≈ 0.42 here) does NOT flatten a 0.5 m jog —
    // on the 10×10 fixture anything under ≈1.05 is auto-levelled away, so a
    // field-scale short jog can't exist there.
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "T".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(
        &[
            Point2f32::new(0.0, 0.0),
            Point2f32::new(4.0, 0.0),
            Point2f32::new(4.0, 4.0),
            Point2f32::new(0.0, 4.0),
            Point2f32::new(0.02, 0.02),
        ],
        0.1,
        true,
    )
    .unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.commit_to_ber().unwrap();

    c.set_edit_mode(EditTools::ExtendOrtho);
    // Stepped bump: runs y=-1.8 and y=-1.3 joined by a 0.5 m vertical jog at
    // x=2 — the short wall with longer collinear-ish neighbours (the field's
    // 0.47 m case).
    c.apply_extend_stroke(&[
        Point2f32::new(1.0, 0.0),
        Point2f32::new(1.0, -1.8),
        Point2f32::new(2.0, -1.8),
        Point2f32::new(2.0, -1.3),
        Point2f32::new(3.0, -1.3),
        Point2f32::new(3.0, 0.0),
    ])
    .expect("stepped bump extend");
    // The 0.5 m separation pairs the two runs for review — the assessor
    // keeps them distinct (the field case), which starts the dimension loop.
    while c.current_review_suggestion().is_some() {
        c.reject_current_review();
    }

    let mut prompted_lengths = Vec::new();
    let mut guard = 0;
    while let Some(prompt) = c.document.dimensioning.current_prompt.clone() {
        let ui = c
            .dimension_prompt_for_ui()
            .expect("open prompt resolves UI data");
        // The primary wall == the live plan's edge for the prompted vertex.
        let (ring, edge) = c
            .document
            .floor_plan
            .find_vertex(prompt.wall_start_vertex)
            .expect("prompted wall exists in the live plan");
        let poly = &c.document.floor_plan.polygons()[ring];
        let n = poly.len();
        let (pa, pb) = (poly[edge], poly[(edge + 1) % n]);
        let primary = ui.walls.first().expect("primary wall present");
        let close = |got: (f64, f64), want: Point2f32| {
            (got.0 - want.x as f64).abs() < 1e-6 && (got.1 - want.y as f64).abs() < 1e-6
        };
        assert!(
            close(primary.wall_a, pa) && close(primary.wall_b, pb),
            "prompt highlight endpoints must be the live edge: got {:?}-{:?}, live {:?}-{:?}",
            primary.wall_a,
            primary.wall_b,
            pa,
            pb
        );
        // The "currently X m" figure is that same edge's length — the label
        // and the endpoints can never describe different walls.
        let span = ((primary.wall_b.0 - primary.wall_a.0).powi(2)
            + (primary.wall_b.1 - primary.wall_a.1).powi(2))
        .sqrt() as f32;
        assert!(
            (span - ui.current_length).abs() < 1e-3,
            "endpoint span {span} == prompted length {}",
            ui.current_length
        );
        prompted_lengths.push(ui.current_length);
        // Accept the drawn length to advance the loop.
        c.apply_dimension(ui.current_length).expect("advance loop");
        guard += 1;
        assert!(guard < 20, "runaway dimension loop");
    }
    assert!(
        prompted_lengths.iter().any(|l| (l - 0.5).abs() < 0.02),
        "the short 0.5 m jog was among the prompts: {prompted_lengths:?}"
    );
}

/// STRUCTURAL: a resolved region's id SURVIVES a materialize.
///
/// The resolve mints every wall/floor/ceiling region fresh, and the InterStorey
/// derive re-splits and re-mints after it — so a region id used to be valid only
/// until the next materialize. Anything holding one (the Structure selection, an
/// open "Edit attributes" session, the riser selection, the open elevation) had
/// to capture a durable key beforehand and re-point afterwards, per caller.
///
/// `document::restore_region_identity` gives each re-derived region back the id
/// its surface held, so a no-op materialize churns NOTHING. This is what makes
/// `materialize()` safe to call at the point of decision — see
/// `subset_decision_needs_no_caller_discipline`.
#[test]
fn region_ids_survive_a_materialize() {
    fn ids_by_surface(c: &AppController) -> Vec<(String, ItemId)> {
        let mut out = Vec::new();
        let rec = c.current_record.as_ref().unwrap();
        for (i, s) in rec.data.storeys.iter().enumerate() {
            for r in s.walls.regions.iter().chain(s.porch_walls.regions.iter()) {
                let (e0, e1) = r.base_edge().expect("a resolved wall has a base edge");
                out.push((
                    format!("{i}/wall/{:?}/{:?}", (e0.x, e0.y, e0.z), (e1.x, e1.y)),
                    r.id,
                ));
            }
            for (tag, regs) in [
                ("floor", &s.floors),
                ("porch", &s.porches),
                ("living", &s.living_areas),
            ] {
                for r in regs.regions.iter() {
                    out.push((
                        format!("{i}/{tag}/{:?}", document::centroid_key(r.centroid())),
                        r.id,
                    ));
                }
            }
            for r in s.ceilings.regions.iter() {
                out.push((
                    format!("{i}/ceiling/{:?}", document::centroid_key(r.centroid())),
                    r.id,
                ));
            }
        }
        out.sort_by(|a, b| a.0.cmp(&b.0));
        out
    }

    // Fixtures spanning the shapes that re-mint: porches, ceiling steps/apexes,
    // risers, wall splits, and the multi-storey InterStorey derive.
    let mut fixtures: Vec<(&str, AppController)> = vec![
        ("square", dimensioned_square_controller()),
        ("porch_square", porch_square_controller()),
        ("ceiling_apex_ready", ceiling_apex_ready_controller()),
        ("ceiling_ready_notched", ceiling_ready_notched_controller()),
        ("riser_ready", riser_ready_controller()),
        ("all_storeys_lasso", all_storeys_lasso_controller()),
        (
            "partial_cover_two_storey",
            partial_cover_two_storey_controller(),
        ),
        (
            "inter_storey_riser",
            inter_storey_riser_fixture_controller(),
        ),
        ("t_plan", dimensioned_t_plan_controller()),
        ("cd36f510", cd36f510_controller()),
    ];
    for (name, c) in fixtures.iter_mut() {
        c.materialize();
        let before = ids_by_surface(c);
        assert!(
            !before.is_empty(),
            "{name}: the fixture resolved some regions"
        );
        // Mark dirty WITHOUT changing anything, then re-derive: the geometry is
        // identical, so every id must be too.
        c.revision = c.revision.wrapping_add(1);
        c.materialize();
        assert_eq!(
            before,
            ids_by_surface(c),
            "{name}: every region kept its id"
        );
        // Ids stay UNIQUE — the restore hands each out at most once.
        let all: Vec<ItemId> = ids_by_surface(c).into_iter().map(|(_, id)| id).collect();
        let uniq: HashSet<ItemId> = all.iter().copied().collect();
        assert_eq!(all.len(), uniq.len(), "{name}: region ids are unique");
    }
}

/// STRUCTURAL: the full-group-vs-subset decision brings the record current
/// ITSELF — no caller has to remember to materialize first.
///
/// This was the actual complaint behind four field bugs: the controller writes
/// attributes to the durable maps and a region's `construction_id` only catches
/// up at the next materialize, so a decision made by reading the record mid-edit
/// answered about the state before the session. The obvious remedy — materialize
/// before deciding — used to INVALIDATE the caller's ids (every resolve re-minted
/// them), so it could only go at the top of an operation, before ids were
/// captured, and it kept being forgotten at one more call site.
///
/// With region identity stable across a resolve
/// (`region_ids_survive_a_materialize`) the remedy is safe where the decision is
/// made, so `group_covers_all_members` owns it. This pins that: the ids captured
/// BEFORE the decision are still live AFTER it.
#[test]
fn subset_decision_needs_no_caller_discipline() {
    use ber_model::ber::structural::{ConstructionMakeup, ConstructionType, WallConstructionType};
    let mut c = dimensioned_square_controller();
    c.materialize();
    set_only_kind(&mut c, SurfaceKind::Walls);
    let mids = square_wall_mids(&c);

    c.clear_structure_surface_selection();
    for m in &mids[0..2] {
        let id = wall_at_mid(&c, *m);
        c.structure_selected.insert(id);
    }
    c.begin_structure_edit();
    let held: Vec<ItemId> = c.structure_edit().unwrap().groups[0].ids.clone();

    // The attribute write lands in the durable maps; the record is now behind.
    c.set_structure_group_attrs(
        0,
        ConstructionType::Wall(WallConstructionType::CavityWall),
        ConstructionMakeup::Default,
        ConstructionPhase::Original,
    );
    c.set_structure_group_name(0, "front pair".to_string());
    // Each of those brought the record current from inside the decision — and
    // the ids the session captured before them are STILL the live regions.
    c.materialize();
    let live: HashSet<ItemId> = c.current_record.as_ref().unwrap().data.storeys[0]
        .walls
        .regions
        .iter()
        .map(|r| r.id)
        .collect();
    for id in &held {
        assert!(
            live.contains(id),
            "a captured region id outlives the decision"
        );
    }
    assert_eq!(
        c.structure_edit().unwrap().groups[0]
            .explicit_name
            .as_deref(),
        Some("front pair"),
        "and the group keeps its name — the decision read a CURRENT record"
    );
}

/// STRUCTURAL: a held region id whose SURFACE the re-resolve removed is dropped
/// from the Structure selection and from any open edit session's group.
///
/// Region identity is stable across a resolve, so nothing needs re-pointing any
/// more — but ids still have to DIE when their surface does. A partition cut
/// splits one wall into two pieces with new base edges, so the whole wall's id
/// is no longer any region's: leaving it in `structure_selected` would keep it
/// counting toward the "N selected" headers, the single-selection gate in the
/// partition flow and the is-empty checks, all of which are length-sensitive.
#[test]
fn a_removed_surface_drops_out_of_the_selection() {
    use document::PartitionCut;

    let mut c = dimensioned_square_controller();
    c.materialize();
    set_only_kind(&mut c, SurfaceKind::Walls);

    // Select the whole top wall (and note a second wall the cut won't touch).
    let mids = square_wall_mids(&c);
    let doomed = wall_at_mid(&c, mids[2]);
    let survivor = wall_at_mid(&c, mids[0]);
    c.clear_structure_surface_selection();
    c.structure_selected.insert(doomed);
    c.structure_selected.insert(survivor);
    c.begin_structure_edit();
    assert!(
        c.structure_edit().unwrap().groups[0].ids.contains(&doomed),
        "the session opened holding the wall about to be split"
    );

    // Split that wall in two: neither piece is the surface `doomed` named.
    let (vid, ..) = c.document.outline.floor_plan.perimeter_walls()[2];
    c.document.commit_partition_cut(
        vid,
        PartitionCut {
            a: Point2f32::new(5.0, 0.0),
            b: Point2f32::new(5.0, 2.4),
        },
    );
    for a in [2.5_f32, 7.5] {
        c.document.set_partition_region_exposure(
            vid,
            Point2f32::new(a, 1.2),
            WallExposure::Exposed,
            10.0,
            2.4,
        );
    }
    c.mark_dirty().unwrap();
    c.materialize();

    let live: HashSet<ItemId> = c.current_record.as_ref().unwrap().data.storeys[0]
        .walls
        .regions
        .iter()
        .map(|r| r.id)
        .collect();
    assert!(
        !live.contains(&doomed),
        "the split really removed that surface"
    );
    assert!(
        !c.structure_selected.contains(&doomed),
        "…so its id left the selection rather than lingering as a phantom member"
    );
    assert!(
        !c.structure_edit().unwrap().groups[0].ids.contains(&doomed),
        "…and left the open edit session's group too"
    );
    // The untouched wall is unaffected — the prune drops the dead, not the rest.
    assert!(
        live.contains(&survivor),
        "the other wall is still a surface"
    );
    assert!(
        c.structure_selected.contains(&survivor),
        "and keeps its place in the selection across the re-resolve"
    );
}

/// FIELD REGRESSION (2026-07-29): "when I click Reset in the Structure phase it
/// resets the construction phase to Unassigned — it should reset to the default
/// for its location based on the mapping phase."
///
/// Reset returns a group box to the two-mode entry, and it used to blank the
/// phase to `ConstructionPhase::default()` (= `Unassigned`). That is wrong twice
/// over. The phase axis is DERIVED from the phase-area mapping, so the fabric
/// default for a surface is whatever zone it sits in — an extension wall's
/// default is `Extension1`, not "no phase". And the editor stamps `g.phase` onto
/// the durable store with EVERY attribute pick, so a box left reading
/// `Unassigned` writes that onto the next pick and strips the wall's phase for
/// real — the reset would quietly undo the phase mapping.
#[test]
fn reset_returns_the_group_to_its_mapping_phase() {
    use ber_model::ber::structural::{ConstructionMakeup, ConstructionType, WallConstructionType};
    let p = |x: f32, y: f32| Point2f32::new(x, y);
    let mut c = dimensioned_square_controller();
    // Tag the right half Extension1: the right wall's mapping phase is
    // Extension1, the left wall's is the untagged Unassigned.
    c.phase_regions.entry(0).or_default().push(PhaseRegion {
        polygon: (vec![p(5., 0.), p(10., 0.), p(10., 10.), p(5., 10.)])
            .into_iter()
            .map(to_f64)
            .collect(),
        phase: ConstructionPhase::Extension1,
    });
    c.commit_to_ber().unwrap();
    c.materialize();
    set_only_kind(&mut c, SurfaceKind::Walls);

    let wall_phase = |c: &AppController, mid: (f64, f64)| {
        let id = wall_at_mid(c, mid);
        let rec = c.current_record.as_ref().unwrap();
        rec.data.storeys[0]
            .walls
            .regions
            .iter()
            .find(|r| r.id == id)
            .and_then(|r| rec.data.wall_construction(r.construction_id))
            .map(|cc| cc.base.construction_phase.clone())
            .unwrap()
    };
    assert_eq!(
        wall_phase(&c, (10.0, 5.0)),
        ConstructionPhase::Extension1,
        "the right wall maps to the tagged zone"
    );

    c.clear_structure_surface_selection();
    c.structure_selected.insert(wall_at_mid(&c, (10.0, 5.0)));
    c.begin_structure_edit();
    c.set_structure_group_attrs(
        0,
        ConstructionType::Wall(WallConstructionType::CavityWall),
        ConstructionMakeup::SomeInsulation,
        c.structure_edit().unwrap().groups[0].phase.clone(),
    );
    c.materialize();

    c.reset_structure_group(0);
    assert_eq!(
        c.structure_edit().unwrap().groups[0].phase,
        ConstructionPhase::Extension1,
        "the BOX returns to the mapping phase, not Unassigned — otherwise the \
         next attribute pick writes Unassigned onto the wall"
    );
    assert_eq!(
        c.structure_edit().unwrap().groups[0].makeup,
        ConstructionMakeup::Tbd,
        "and the build-up really is cleared"
    );
    c.materialize();
    assert_eq!(
        wall_phase(&c, (10.0, 5.0)),
        ConstructionPhase::Extension1,
        "the RECORD keeps the mapping phase across the reset too"
    );

    // The knock-on the box value causes: attribute again straight after the
    // reset, exactly as the editor does (it passes `g.phase` through).
    c.set_structure_group_attrs(
        0,
        ConstructionType::Wall(WallConstructionType::TimberConstruction),
        ConstructionMakeup::Default,
        c.structure_edit().unwrap().groups[0].phase.clone(),
    );
    c.materialize();
    assert_eq!(
        wall_phase(&c, (10.0, 5.0)),
        ConstructionPhase::Extension1,
        "re-attributing after a reset does NOT strip the wall's phase"
    );
}

/// Reset is per-BOX, and the boxes already split on phase — so a "Select all"
/// spanning two zones opens one group per zone, and each returns to ITS OWN
/// mapping phase. This is the multi-zone shape of the field report: the
/// extension's box must come back reading `Extension1`, not `Unassigned`.
#[test]
fn reset_returns_each_zone_group_to_its_own_phase() {
    use ber_model::ber::structural::{ConstructionMakeup, ConstructionType, WallConstructionType};
    let p = |x: f32, y: f32| Point2f32::new(x, y);
    let mut c = dimensioned_square_controller();
    c.phase_regions.entry(0).or_default().push(PhaseRegion {
        polygon: (vec![p(5., 0.), p(10., 0.), p(10., 10.), p(5., 10.)])
            .into_iter()
            .map(to_f64)
            .collect(),
        phase: ConstructionPhase::Extension1,
    });
    c.commit_to_ber().unwrap();
    c.materialize();
    set_only_kind(&mut c, SurfaceKind::Walls);
    c.set_structure_select_mode(Some(SelectMode::All));
    c.begin_structure_edit();

    // One box per phase zone (the documented group-box split).
    let opened: Vec<ConstructionPhase> = c
        .structure_edit()
        .unwrap()
        .groups
        .iter()
        .map(|g| g.phase.clone())
        .collect();
    assert!(
        opened.contains(&ConstructionPhase::Extension1)
            && opened.contains(&ConstructionPhase::Unassigned),
        "the selection opened one box per zone: {opened:?}"
    );

    for i in 0..c.structure_edit().unwrap().groups.len() {
        let phase = c.structure_edit().unwrap().groups[i].phase.clone();
        c.set_structure_group_attrs(
            i,
            ConstructionType::Wall(WallConstructionType::CavityWall),
            ConstructionMakeup::SomeInsulation,
            phase,
        );
    }
    c.materialize();

    for i in 0..c.structure_edit().unwrap().groups.len() {
        c.reset_structure_group(i);
    }
    let after: Vec<ConstructionPhase> = c
        .structure_edit()
        .unwrap()
        .groups
        .iter()
        .map(|g| g.phase.clone())
        .collect();
    assert_eq!(
        after, opened,
        "every box came back to the phase its surfaces map to"
    );

    c.materialize();
    let rec = c.current_record.as_ref().unwrap();
    let phases: Vec<ConstructionPhase> = rec.data.storeys[0]
        .walls
        .regions
        .iter()
        .filter_map(|r| rec.data.wall_construction(r.construction_id))
        .map(|cc| cc.base.construction_phase.clone())
        .collect();
    assert!(
        phases.contains(&ConstructionPhase::Extension1)
            && phases.contains(&ConstructionPhase::Unassigned),
        "and the record still carries both zones' phases: {phases:?}"
    );
    assert!(
        rec.data.storeys[0]
            .walls
            .regions
            .iter()
            .filter_map(|r| rec.data.wall_construction(r.construction_id))
            .all(|cc| cc.base.construction_makeup == ConstructionMakeup::Tbd),
        "every member's build-up cleared"
    );
}

/// FIELD REGRESSION (2026-07-29): "I reset 3 walls, the boxes went back to
/// Group 1 / Group 2, but selecting them again opened TWO groups still called
/// 'w' and 'wb'. They should open as ONE group — everything else about them is
/// the same — and the name should have been reset."
///
/// Two defects, both about the NAME:
///
/// 1. Naming a group whose fabric is still unset renamed the shared
///    UNCLASSIFIED bucket IN PLACE. The bucket reads as a "full group" for the
///    subset decision (it is not a group at all — there is nothing to be a
///    subset of), and the rename took that as licence to brand it — so every
///    OTHER un-answered surface in the house inherited the name too.
/// 2. Reset then could not clear it: the "did this box actually apply
///    anything?" gate counted only type and build-up, so a name-only group
///    looked untouched and the detach returned early. The box cleared to
///    "Group N" while the record kept the name — the reset was a no-op that
///    looked like it worked.
#[test]
fn reset_clears_a_name_applied_before_any_fabric() {
    let mut c = dimensioned_square_controller();
    c.materialize();
    set_only_kind(&mut c, SurfaceKind::Walls);
    let mids = square_wall_mids(&c);
    let names = |c: &AppController| -> Vec<String> {
        let rec = c.current_record.as_ref().unwrap();
        rec.data.storeys[0]
            .walls
            .regions
            .iter()
            .filter_map(|r| rec.data.wall_construction(r.construction_id))
            .map(|cc| cc.base.name.clone().unwrap_or_else(|| "-".into()))
            .collect()
    };

    // Label the selection BEFORE choosing its fabric — the assessor's order.
    c.clear_structure_surface_selection();
    for m in &mids[0..2] {
        let id = wall_at_mid(&c, *m);
        c.structure_selected.insert(id);
    }
    c.begin_structure_edit();
    c.set_structure_group_name(0, "w".to_string());
    c.materialize();
    assert_eq!(
        names(&c).iter().filter(|n| *n == "w").count(),
        2,
        "the name reaches the two selected walls and NO others — it must not \
         brand the unclassified bucket the rest of the house shares: {:?}",
        names(&c)
    );

    // Reset must actually clear it, not just blank the box.
    c.reset_structure_group(0);
    c.materialize();
    assert!(
        names(&c).iter().all(|n| n == "-"),
        "reset cleared the name from the record: {:?}",
        names(&c)
    );

    // …so re-selecting opens ONE fresh unnamed group, not the old named ones.
    c.end_structure_edit();
    c.clear_structure_surface_selection();
    for m in &mids[0..2] {
        let id = wall_at_mid(&c, *m);
        c.structure_selected.insert(id);
    }
    c.begin_structure_edit();
    let groups = &c.structure_edit().unwrap().groups;
    assert_eq!(groups.len(), 1, "one group — the walls are identical again");
    assert_eq!(groups[0].explicit_name, None, "and it carries no name");
}

/// Resetting several named groups returns every member to the unattributed
/// default, so re-selecting them opens ONE group rather than re-offering the
/// old names — the whole-flow shape of the field report.
#[test]
fn reset_of_named_groups_reopens_as_one_unnamed_group() {
    use ber_model::ber::structural::{ConstructionMakeup, ConstructionType, WallConstructionType};
    let mut c = dimensioned_square_controller();
    c.materialize();
    set_only_kind(&mut c, SurfaceKind::Walls);
    let mids = square_wall_mids(&c);

    let mut name_group = |c: &mut AppController, sel: &[(f64, f64)], name: &str| {
        c.clear_structure_surface_selection();
        for m in sel {
            let id = wall_at_mid(c, *m);
            c.structure_selected.insert(id);
        }
        c.begin_structure_edit();
        c.set_structure_group_attrs(
            0,
            ConstructionType::Wall(WallConstructionType::CavityWall),
            ConstructionMakeup::Default,
            ConstructionPhase::Original,
        );
        c.set_structure_group_name(0, name.to_string());
        c.end_structure_edit();
        c.materialize();
    };
    name_group(&mut c, &mids[0..2], "w");
    name_group(&mut c, &mids[2..3], "wb");

    // The untouched fourth wall never took either name.
    let rec = c.current_record.as_ref().unwrap();
    let unnamed = rec.data.storeys[0]
        .walls
        .regions
        .iter()
        .filter_map(|r| rec.data.wall_construction(r.construction_id))
        .filter(|cc| cc.base.name.is_none())
        .count();
    assert_eq!(unnamed, 1, "the wall outside both groups stayed unnamed");

    // Select all three named walls and reset every box.
    c.clear_structure_surface_selection();
    for m in &mids[0..3] {
        let id = wall_at_mid(&c, *m);
        c.structure_selected.insert(id);
    }
    c.begin_structure_edit();
    assert_eq!(
        c.structure_edit().unwrap().groups.len(),
        2,
        "two boxes — the names make them distinct groups"
    );
    for i in 0..2 {
        c.reset_structure_group(i);
    }
    c.end_structure_edit();
    c.materialize();

    c.clear_structure_surface_selection();
    for m in &mids[0..3] {
        let id = wall_at_mid(&c, *m);
        c.structure_selected.insert(id);
    }
    c.begin_structure_edit();
    let groups = &c.structure_edit().unwrap().groups;
    assert_eq!(
        groups.len(),
        1,
        "reset made the three identical again → ONE group, not the old two"
    );
    assert_eq!(groups[0].explicit_name, None, "with no name carried over");
}

// ── Edit dimension (side-aware resize of a finalised wall) ──────────────────

/// End-to-end resize through the controller: tap the south wall of the
/// committed 10×6, apply 12.0 moving the East end. The record footprint
/// grows east; a window anchored 2 m from the WEST (fixed) end stays 2 m
/// from it; the painted south-wall exposure covers the full new length;
/// undo restores everything.
#[test]
fn edit_dimension_grows_east_and_satellites_follow() {
    use ber_model::ber::fenestration::{OpeningPlacement, WallAnchor, Window, WindowShape};

    let mut c = dimensioned_10x6_controller();
    c.materialize();

    // South wall of the plan: (0,0) → (10,0).
    let south_vid = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .into_iter()
        .find(|(_, a, b)| a.y.abs() < 1e-3 && b.y.abs() < 1e-3)
        .map(|(v, _, _)| v)
        .expect("south wall");

    // Paint the whole south wall Exposed (1-D section).
    c.document.wall_sections.insert(
        south_vid,
        vec![document::ExposureSection {
            start_m: 0.0,
            end_m: 10.0,
            exposure: WallExposure::Exposed,
        }],
    );

    // A window on the south wall, centred 2 m from its start (the west end),
    // with its durable anchor already seeded (fraction 0.2 of 10 m).
    let south_region_id = {
        let record = c.current_record.as_ref().unwrap();
        record.data.storeys[0]
            .walls
            .regions
            .iter()
            .find(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
            .map(|r| r.id)
            .expect("south wall region")
    };
    {
        let record = c.current_record.as_mut().unwrap();
        record.data.storeys[0].windows.push(Window {
            id: ItemId::default(),
            vertices: vec![],
            width_m: 1.0,
            height_m: 1.2,
            window_type_id: ItemId::default(),
            placement: Some(OpeningPlacement::Wall {
                wall_id: south_region_id,
                along_m: 2.0,
                sill_m: 1.0,
            }),
            wall_anchor: Some(WallAnchor {
                wall: manip_plan::SurfaceRef::wall(south_vid),
                along_fraction: 0.2,
                porch: None,
            }),
            assembly_id: None,
            multi_storey: false,
            shape: WindowShape::Rectangular,
            overshading: Default::default(),
            num_opes: None,
        });
    }

    // Tap the south wall in edit-dimension mode and apply 12 m, East end.
    c.set_edit_dimension_mode(true);
    assert!(c.edit_dimension_tap(5.0, 0.0, 0.5), "tap picked the wall");
    let prompt = c.edit_dimension_for_ui().unwrap();
    assert!((prompt.current_length - 10.0).abs() < 1e-3);
    // Default moving end is End — for the ring order here that's the EAST end.
    c.apply_edit_dimension(12.0).unwrap();

    // The record footprint now spans x ∈ [0, 12].
    let record = c.current_record.as_ref().unwrap();
    let xs: Vec<f64> = record.data.storeys[0]
        .floors
        .footprint_ring()
        .unwrap()
        .iter()
        .map(|p| p.x)
        .collect();
    let max_x = xs.iter().cloned().fold(f64::MIN, f64::max);
    let min_x = xs.iter().cloned().fold(f64::MAX, f64::min);
    assert!((max_x - 12.0).abs() < 1e-3, "east face at 12 (got {max_x})");
    assert!(min_x.abs() < 1e-3, "west face anchored");

    // The window kept its 2 m distance from the fixed WEST end.
    let w = &record.data.storeys[0].windows[0];
    let frac = w.wall_anchor.unwrap().along_fraction;
    assert!(
        (frac - 2.0 / 12.0).abs() < 1e-3,
        "fraction re-derived (got {frac})"
    );
    if let Some(OpeningPlacement::Wall { along_m, .. }) = &w.placement {
        assert!(
            (along_m - 2.0).abs() < 0.05,
            "placement re-derived at 2 m from the west corner (got {along_m})"
        );
    } else {
        panic!("window lost its wall placement");
    }

    // The south wall's painted exposure covers the full 12 m: its derived
    // region is Exposed with a 12 m base edge.
    let south_region = record.data.storeys[0]
        .walls
        .regions
        .iter()
        .find(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
        .expect("south wall region");
    assert_eq!(south_region.exposure, WallExposure::Exposed);
    let (_, _, len, _) = south_region.base_frame().unwrap();
    assert!((len - 12.0).abs() < 1e-3, "region spans the new length");

    // One undo restores the pre-edit geometry AND the window.
    c.undo().unwrap();
    let record = c.current_record.as_ref().unwrap();
    let xs: Vec<f64> = record.data.storeys[0]
        .floors
        .footprint_ring()
        .unwrap()
        .iter()
        .map(|p| p.x)
        .collect();
    let max_x = xs.iter().cloned().fold(f64::MIN, f64::max);
    assert!((max_x - 10.0).abs() < 1e-3, "undo restored the 10 m width");
    let w = &record.data.storeys[0].windows[0];
    assert!(
        (w.wall_anchor.unwrap().along_fraction - 0.2).abs() < 1e-3,
        "undo restored the window anchor"
    );
}

/// A shrink that would leave the outline self-intersecting is rejected with
/// everything rolled back and the prompt still open.
#[test]
fn edit_dimension_rejects_and_rolls_back_cleanly() {
    let mut c = dimensioned_10x6_controller();
    c.materialize();
    c.set_edit_dimension_mode(true);
    assert!(c.edit_dimension_tap(5.0, 0.0, 0.5));
    // 0-length is invalid input; a negative is too.
    assert!(c.apply_edit_dimension(-3.0).is_err());
    // The plan is untouched and the prompt is still open.
    let p = c.edit_dimension_for_ui().expect("prompt stays open");
    assert!((p.current_length - 10.0).abs() < 1e-3);
}

/// The side toggle flips which end the plane move targets: moving the START
/// (west) end of the south wall grows the house westward instead.
#[test]
fn edit_dimension_swap_side_grows_west() {
    let mut c = dimensioned_10x6_controller();
    c.materialize();
    c.set_edit_dimension_mode(true);
    assert!(c.edit_dimension_tap(5.0, 0.0, 0.5));
    c.toggle_edit_dimension_side();
    c.apply_edit_dimension(12.0).unwrap();
    let record = c.current_record.as_ref().unwrap();
    let xs: Vec<f64> = record.data.storeys[0]
        .floors
        .footprint_ring()
        .unwrap()
        .iter()
        .map(|p| p.x)
        .collect();
    let min_x = xs.iter().cloned().fold(f64::MAX, f64::min);
    let max_x = xs.iter().cloned().fold(f64::MIN, f64::max);
    assert!(
        (min_x + 2.0).abs() < 1e-3,
        "west face moved to -2 (got {min_x})"
    );
    assert!((max_x - 10.0).abs() < 1e-3, "east face anchored");
}

/// A session phase zone drawn against the moving face CONTINUES into the
/// grown strip: its ring stretches with the face, so the resolved floor
/// partition keeps the zone boundary at its interior line and the new strip
/// lands in the zone it grew from.
#[test]
fn edit_dimension_extends_the_phase_zone_on_the_moving_side() {
    let mut c = dimensioned_10x6_controller();
    c.materialize();
    // An east zone x ∈ [7, 10] (session ring, as the phase workflow stores it).
    c.phase_regions.insert(
        0,
        vec![document::PhaseRegion {
            polygon: vec![
                Point2f64::new(7.0, 0.0),
                Point2f64::new(10.0, 0.0),
                Point2f64::new(10.0, 6.0),
                Point2f64::new(7.0, 6.0),
            ],
            phase: ConstructionPhase::Extension1,
        }],
    );
    c.mark_dirty().unwrap();
    c.materialize();

    c.set_edit_dimension_mode(true);
    assert!(c.edit_dimension_tap(5.0, 0.0, 0.5));
    c.apply_edit_dimension(12.0).unwrap();

    // The session ring followed the face…
    let ring = &c.phase_regions[&0][0].polygon;
    let max_x = ring.iter().map(|p| p.x).fold(f64::MIN, f64::max);
    let min_x = ring.iter().map(|p| p.x).fold(f64::MAX, f64::min);
    assert!((max_x - 12.0).abs() < 1e-6, "zone grew east (got {max_x})");
    assert!((min_x - 7.0).abs() < 1e-6, "interior boundary stayed at 7");

    // …and the resolved floors keep two regions split at x = 7, with the
    // grown strip inside the extension zone.
    let record = c.current_record.as_ref().unwrap();
    let floors = &record.data.storeys[0].floors.regions;
    assert_eq!(floors.len(), 2, "still partitioned into two zones");
    let contains = |px: f64, py: f64| {
        floors
            .iter()
            .position(|r| {
                let ring: Vec<(f64, f64)> =
                    r.polygon.exterior().coords().map(|p| (p.x, p.y)).collect();
                point_in_ring(px, py, &ring)
            })
            .expect("point inside some region")
    };
    assert_eq!(
        contains(11.0, 3.0),
        contains(8.0, 3.0),
        "the grown strip continues the east zone"
    );
    assert_ne!(
        contains(11.0, 3.0),
        contains(2.0, 3.0),
        "the west zone stays separate"
    );
}

/// Winding-agnostic point-in-polygon for the phase-zone test.
fn point_in_ring(px: f64, py: f64, ring: &[(f64, f64)]) -> bool {
    let mut inside = false;
    let n = ring.len();
    for i in 0..n {
        let (x1, y1) = ring[i];
        let (x2, y2) = ring[(i + 1) % n];
        if ((y1 > py) != (y2 > py)) && (px < (x2 - x1) * (py - y1) / (y2 - y1) + x1) {
            inside = !inside;
        }
    }
    inside
}

// ── Doorset (door+sidelights assembly) EDIT ─────────────────────────────────

/// Shared setup: a committed square storey with a door+sidelights assembly on
/// the south wall (0.9×2.0 door, 0.4 sidelights both sides, 0.4 transom).
fn controller_with_doorset() -> AppController {
    use ber_model::ber::fenestration::{Frame, Glazing};
    let mut c = dimensioned_square_controller();
    c.materialize();
    c.set_openings_mode(true);
    c.set_openings_tool(OpeningToolKind::DoorSidelights);
    c.openings_pointer_down(5.0, -0.2, 0.5);
    c.place_pending_door_sidelights(
        0.9,
        2.0,
        Some(0.4),
        Some(0.4),
        Some(0.4),
        Glazing::Double,
        Frame::WoodUPVC,
        2010,
    )
    .expect("assembly places");
    c.materialize();
    c
}

/// Selecting ANY member of a doorset offers the assembly edit: the prompt
/// opens in the piece-by-piece shape, prefilled from the members.
#[test]
fn doorset_member_opens_the_assembly_edit_prompt() {
    let mut c = controller_with_doorset();
    let (panel_id, pane_id) = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        (s.doors[0].id, s.windows[0].id)
    };
    // Via the door panel…
    c.elevation_selection = Some(ber_model::ber::openings::OpeningRef::Door(panel_id));
    c.start_edit_selected_assembly();
    let p = c
        .opening_fields_prompt(
            DoorSidelightsMode::default(),
            ber_model::ber::fenestration::ComplexWindowKind::default(),
            ber_model::ber::fenestration::WindowTopShape::default(),
        )
        .expect("assembly edit prompt");
    assert_eq!(p.fields.len(), 7, "piece-by-piece field set");
    assert_eq!(p.door_sidelights, Some(DoorSidelightsMode::Detailed));
    let e = p.assembly_edit.expect("prefill present");
    assert!((e.door_width_m - 0.9).abs() < 1e-4);
    assert!((e.door_height_m - 2.0).abs() < 1e-4);
    assert!((e.left.unwrap().0 - 0.4).abs() < 1e-4, "left width");
    assert!((e.right.unwrap().0 - 0.4).abs() < 1e-4, "right width");
    assert!((e.transom_m.unwrap() - 0.4).abs() < 1e-4, "transom height");
    // …and via a glass pane.
    c.cancel_opening_placement();
    c.elevation_selection = Some(ber_model::ber::openings::OpeningRef::Window(pane_id));
    c.start_edit_selected_assembly();
    assert!(matches!(c.opening_edit, Some(OpeningEdit::Assembly(_))));
}

/// Applying the doorset edit re-composes the assembly in place: new piece
/// sizes, flush layout, same centre, door attributes carried, one undo.
#[test]
fn doorset_edit_recomposes_with_new_sizes() {
    use ber_model::ber::fenestration::OpeningPlacement;
    let mut c = controller_with_doorset();
    let (panel_id, old_centre) = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        let d = &s.doors[0];
        let Some(OpeningPlacement::Wall { along_m, .. }) = d.placement else {
            panic!("door placed on a wall");
        };
        // centre of door = centre of a symmetric assembly
        (d.id, along_m)
    };
    c.elevation_selection = Some(ber_model::ber::openings::OpeningRef::Door(panel_id));
    c.start_edit_selected_assembly();
    // Wider door (1.1), one WIDER left light (0.6), drop the right light,
    // taller transom (0.5).
    c.apply_assembly_edit(
        1.1,
        2.0,
        Some(0.6),
        None,
        None,
        None,
        Some(0.5),
        false,
        WindowTypeChoice::Existing(c.current_record.as_ref().unwrap().data.window_types[0].id),
        ber_model::ber::fenestration::Overshading::Average,
        Some(1),
        true,
        vec![],
    )
    .expect("doorset edit applies");
    c.materialize();
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(s.doors.len(), 1, "still one door panel");
    assert_eq!(s.windows.len(), 2, "left light + transom (right dropped)");
    let d = &s.doors[0];
    assert!((d.width_m - 1.1).abs() < 1e-4);
    assert_eq!(d.draught_stripped, Some(true), "draught tick applied");
    let aid = d.assembly_id.expect("still an assembly");
    assert!(s.windows.iter().all(|w| w.assembly_id == Some(aid)));
    // Flush: left light's right edge == door's left edge.
    let Some(OpeningPlacement::Wall { along_m: d_al, .. }) = d.placement else {
        panic!()
    };
    let left = s
        .windows
        .iter()
        .find(|w| {
            matches!(w.placement, Some(OpeningPlacement::Wall { along_m, .. }) if along_m < d_al)
        })
        .expect("left light");
    let Some(OpeningPlacement::Wall { along_m: l_al, .. }) = left.placement else {
        panic!()
    };
    assert!(
        ((l_al + left.width_m / 2.0) - (d_al - d.width_m / 2.0)).abs() < 1e-3,
        "left light flush against the door"
    );
    // Same centre: total = 0.6 + 1.1 = 1.7 → centre where the old one was.
    let centre = ((l_al - left.width_m / 2.0) + (d_al + d.width_m / 2.0)) / 2.0;
    assert!(
        (centre - old_centre).abs() < 1e-3,
        "assembly re-centres where it was (old {old_centre}, new {centre})"
    );
    // One undo restores the original 4-member assembly.
    c.undo().unwrap();
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(s.windows.len(), 3, "undo restored both lights + transom");
    assert!((s.doors[0].width_m - 0.9).abs() < 1e-4);
}

/// An infeasible doorset edit (wider than the wall) is refused with the model
/// untouched and the box still open.
#[test]
fn doorset_edit_too_wide_is_refused_untouched() {
    let mut c = controller_with_doorset();
    let panel_id = c.current_record.as_ref().unwrap().data.storeys[0].doors[0].id;
    c.elevation_selection = Some(ber_model::ber::openings::OpeningRef::Door(panel_id));
    c.start_edit_selected_assembly();
    let type_id = c.current_record.as_ref().unwrap().data.window_types[0].id;
    let err = c.apply_assembly_edit(
        9.0,
        2.0,
        Some(1.5),
        None,
        Some(1.5),
        None,
        None,
        false,
        WindowTypeChoice::Existing(type_id),
        ber_model::ber::fenestration::Overshading::Average,
        Some(1),
        false,
        vec![],
    );
    assert!(err.is_err(), "12 m of doorset on a 10 m wall with margins");
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(s.windows.len(), 3, "members untouched");
    assert!((s.doors[0].width_m - 0.9).abs() < 1e-4, "door untouched");
    assert!(
        matches!(c.opening_edit, Some(OpeningEdit::Assembly(_))),
        "box still open for a retry"
    );
}

/// Elevation DRAG of any doorset member moves the whole assembly rigidly —
/// the members' relative offsets (flush edges, transom above the door) are
/// preserved, so the door and its lights can never intersect.
#[test]
fn doorset_drag_stays_rigid() {
    use ber_model::ber::fenestration::OpeningPlacement;
    let mut c = controller_with_doorset();
    let offsets = |c: &AppController| -> Vec<(f32, f32)> {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        let Some(OpeningPlacement::Wall {
            along_m: d_al,
            sill_m: d_sl,
            ..
        }) = s.doors[0].placement
        else {
            panic!()
        };
        let mut v: Vec<(f32, f32)> = s
            .windows
            .iter()
            .filter_map(|w| match w.placement {
                Some(OpeningPlacement::Wall {
                    along_m, sill_m, ..
                }) => Some((along_m - d_al, sill_m - d_sl)),
                _ => None,
            })
            .collect();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v
    };
    let before = offsets(&c);
    // Grab the TRANSOM (the pane above the door) and drag it around.
    let transom_id = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        s.windows
            .iter()
            .find(|w| matches!(w.placement, Some(OpeningPlacement::Wall { sill_m, .. }) if sill_m > 1.9))
            .unwrap()
            .id
    };
    c.elevation_wall = c.current_record.as_ref().unwrap().data.storeys[0]
        .walls
        .regions
        .first()
        .map(|r| r.id);
    c.elevation_drag = Some(ber_model::ber::openings::OpeningRef::Window(transom_id));
    c.elevation_pointer_drag(3.0, 1.4);
    c.elevation_pointer_drag(6.5, 2.6);
    c.elevation_pointer_up();
    let after = offsets(&c);
    assert_eq!(before.len(), after.len());
    for (b, a) in before.iter().zip(after.iter()) {
        assert!(
            (b.0 - a.0).abs() < 1e-3 && (b.1 - a.1).abs() < 1e-3,
            "member offsets preserved through the drag: {before:?} vs {after:?}"
        );
    }
}

/// A drifted doorset member (its anchor fraction perturbed — the fingerprint
/// a wall reshape's per-member relink leaves) re-flushes against the door on
/// the next re-derive instead of intersecting it.
#[test]
fn drifted_doorset_member_reflushes_on_rederive() {
    use ber_model::ber::fenestration::OpeningPlacement;
    let mut c = controller_with_doorset();
    // Perturb the LEFT sidelight's durable anchor so its re-derived along
    // lands INSIDE the door.
    {
        let s = &mut c.current_record.as_mut().unwrap().data.storeys[0];
        let d_al = match s.doors[0].placement {
            Some(OpeningPlacement::Wall { along_m, .. }) => along_m,
            _ => panic!(),
        };
        let w = s
            .windows
            .iter_mut()
            .find(|w| {
                matches!(w.placement, Some(OpeningPlacement::Wall { along_m, sill_m, .. })
                    if along_m < d_al && sill_m < 1.5)
            })
            .expect("left sidelight");
        if let Some(a) = w.wall_anchor.as_mut() {
            a.along_fraction += 0.06; // ~0.6 m rightward on a 10 m wall → into the door
        }
    }
    c.mark_dirty().unwrap();
    c.materialize();
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let (d_al, d_w) = match s.doors[0].placement {
        Some(OpeningPlacement::Wall { along_m, .. }) => (along_m, s.doors[0].width_m),
        _ => panic!(),
    };
    let left = s
        .windows
        .iter()
        .find(|w| {
            matches!(w.placement, Some(OpeningPlacement::Wall { along_m, sill_m, .. })
                if along_m < d_al && sill_m < 1.5)
        })
        .expect("left sidelight survives");
    let l_al = match left.placement {
        Some(OpeningPlacement::Wall { along_m, .. }) => along_m,
        _ => panic!(),
    };
    assert!(
        ((l_al + left.width_m / 2.0) - (d_al - d_w / 2.0)).abs() < 1e-3,
        "sidelight re-flushed against the door (pane right edge {:.3} vs door left edge {:.3})",
        l_al + left.width_m / 2.0,
        d_al - d_w / 2.0
    );
}

/// USER REPORT (tablet, 2026-08-08): TrimOrtho a notch out of the MIDDLE of a
/// fully-painted wall. The two surviving remnants must inherit the paint over
/// exactly their spans; the notch gap has no wall (nothing to claim an
/// exposure); the trim-minted notch walls start Unset for the assessor.
#[test]
fn trim_ortho_notch_inherits_paint_on_remnants_only() {
    let mut c = dimensioned_square_controller(); // 10×10, storey 0
    c.set_default_ceiling_height(2.4).unwrap();
    // Paint the whole BOTTOM wall (y=0) Exposed.
    let (vid, a, b) = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .into_iter()
        .find(|(_, a, b)| a.y.abs() < 1e-4 && b.y.abs() < 1e-4)
        .expect("a y=0 wall");
    let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
    c.document
        .set_wall_section(vid, 0.0, len, len, WallExposure::Exposed);
    c.commit_to_ber().unwrap();

    // TrimOrtho a 2 m wide, 1 m deep notch out of the middle: the stroke
    // enters at (4,0), steps inward to y=1, and exits at (6,0).
    c.set_edit_mode(EditTools::TrimOrtho);
    c.apply_trim_stroke(&[
        Point2f32::new(4.0, -0.05),
        Point2f32::new(4.0, 1.0),
        Point2f32::new(6.0, 1.0),
        Point2f32::new(6.0, -0.05),
    ])
    .expect("trim-ortho applies");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();

    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    // The y=0 remnants: everything left of the notch and right of it.
    let bottom: Vec<_> = storey
        .walls
        .regions
        .iter()
        .filter(|r| {
            r.base_edge()
                .is_some_and(|(a, b)| a.y.abs() < 1e-3 && b.y.abs() < 1e-3)
        })
        .collect();
    assert!(
        bottom.len() >= 2,
        "two bottom remnants resolve: {:?}",
        bottom
            .iter()
            .map(|w| w.base_edge().unwrap())
            .collect::<Vec<_>>()
    );
    let mut covered = 0.0_f64;
    for w in &bottom {
        let (a, b) = w.base_edge().unwrap();
        let (lo, hi) = (a.x.min(b.x), a.x.max(b.x));
        assert!(
            hi <= 4.0 + 1e-3 || lo >= 6.0 - 1e-3,
            "no bottom wall region spans the notch gap: {:?}",
            (a, b)
        );
        assert_eq!(
            w.exposure,
            WallExposure::Exposed,
            "remnant inherits the paint over {:?}",
            (a, b)
        );
        covered += hi - lo;
    }
    assert!(
        (covered - 8.0).abs() < 1e-2,
        "the paint covers exactly the surviving 8 m (got {covered:.3})"
    );
    // The notch's own walls (x=4, x=6 risers into the notch + the y=1 back)
    // are NEW — they start Unset for the assessor to mark.
    let notch: Vec<_> = storey
        .walls
        .regions
        .iter()
        .filter(|r| {
            r.base_edge().is_some_and(|(a, b)| {
                let mid_y = (a.y + b.y) * 0.5;
                mid_y > 0.01 && mid_y <= 1.01
            })
        })
        .collect();
    assert!(!notch.is_empty(), "the notch walls resolve");
    for w in &notch {
        assert_eq!(
            w.exposure,
            WallExposure::Unset,
            "a trim-minted wall starts Unset: {:?}",
            w.base_edge()
        );
    }
}

/// The tablet screenshot bug: after a middle-notch trim, the NEAR remnant
/// keeps its vid — its STORED sections must be clipped to the surviving span
/// (not just clamped at derive time), or the plan overlay lerps the stale
/// 0..old_len paint straight across the trimmed-away gap.
#[test]
fn trim_clips_the_kept_walls_stored_sections() {
    let mut c = dimensioned_square_controller();
    let (vid, a, b) = c
        .document
        .outline
        .floor_plan
        .perimeter_walls()
        .into_iter()
        .find(|(_, a, b)| a.y.abs() < 1e-4 && b.y.abs() < 1e-4)
        .expect("a y=0 wall");
    let len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
    c.document
        .set_wall_section(vid, 0.0, len, len, WallExposure::Exposed);
    c.commit_to_ber().unwrap();
    c.set_edit_mode(EditTools::TrimOrtho);
    c.apply_trim_stroke(&[
        Point2f32::new(4.0, -0.05),
        Point2f32::new(4.0, 1.0),
        Point2f32::new(6.0, 1.0),
        Point2f32::new(6.0, -0.05),
    ])
    .expect("trim-ortho applies");
    // Every stored section now fits ITS wall — none paints past a wall's end.
    for (vid, a, b) in c.document.outline.floor_plan.perimeter_walls() {
        let wall_len = ((b.x - a.x).powi(2) + (b.y - a.y).powi(2)).sqrt();
        if let Some(secs) = c.document.wall_sections.get(&vid) {
            for s in secs {
                assert!(
                    s.end_m <= wall_len + 1e-3 && s.start_m >= -1e-3,
                    "section {s:?} exceeds its {wall_len:.2} m wall ({a:?} -> {b:?})"
                );
            }
        }
    }
}

/// THE FIELD REPORT (Glengara re-test): a wall carries a window AND a
/// door+sidelights; a TrimOrtho notch is carved BETWEEN them out of the same
/// wall. Both openings sit on untouched flanks — they must stay at their
/// WORLD positions on their own remnants (not teleport toward the notch as
/// their anchor fractions silently re-scope to the shortened kept wall, the
/// window ending up off the wall and inside the doorset).
#[test]
fn trim_between_openings_keeps_them_in_place() {
    use ber_model::ber::fenestration::{Frame, Glazing, OpeningPlacement};
    let mut c = dimensioned_square_controller(); // 10×10
    c.materialize();
    c.set_openings_mode(true);
    // A 1 m window centred at along 2.0 on the south wall (y=0)…
    c.set_openings_tool(OpeningToolKind::Window);
    c.openings_pointer_down(2.0, -0.2, 0.5);
    c.place_opening(
        1.0,
        1.2,
        false,
        false,
        None,
        None,
        None,
        WindowTypeChoice::default(),
        ber_model::ber::fenestration::Overshading::Average,
        None,
        true,
        Vec::new(),
    )
    .expect("window places");
    // …and a doorset centred at along 7.5 (0.9 door + 0.4 lights each side).
    c.set_openings_tool(OpeningToolKind::DoorSidelights);
    c.openings_pointer_down(7.5, -0.2, 0.5);
    c.place_pending_door_sidelights(
        0.9,
        2.0,
        Some(0.4),
        Some(0.4),
        None,
        Glazing::Double,
        Frame::WoodUPVC,
        2010,
    )
    .expect("doorset places");
    c.materialize();
    c.set_openings_mode(false);

    // Trim a 1 m wide notch between them: along 4.0 → 5.0, 0.8 deep.
    c.set_edit_mode(EditTools::TrimOrtho);
    c.apply_trim_stroke(&[
        Point2f32::new(4.0, -0.05),
        Point2f32::new(4.0, 0.8),
        Point2f32::new(5.0, 0.8),
        Point2f32::new(5.0, -0.05),
    ])
    .expect("trim-ortho applies");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();

    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    // The window: still centred at world x ≈ 2.0 on the NEAR remnant.
    let w = &s.windows[0];
    let host_of = |wall_id| {
        s.walls
            .regions
            .iter()
            .find(|r| r.id == wall_id)
            .and_then(|r| r.base_frame())
    };
    let world_x = |placement: &Option<OpeningPlacement>| -> f64 {
        let Some(OpeningPlacement::Wall {
            wall_id, along_m, ..
        }) = placement
        else {
            panic!("wall placement")
        };
        let (origin, (ux, _), _, _) = host_of(*wall_id).expect("host resolves");
        origin.x + ux * *along_m as f64
    };
    let wx = world_x(&w.placement);
    assert!(
        (wx - 2.0).abs() < 0.05,
        "window stayed at world x≈2.0 (got {wx:.3})"
    );
    // The doorset: door panel still centred at world x ≈ 7.5, panes flush.
    let d = &s.doors[0];
    let dx = world_x(&d.placement);
    assert!(
        (dx - 7.5).abs() < 0.05,
        "doorset door stayed at world x≈7.5 (got {dx:.3})"
    );
    // No pane intersects the door or the window; everything on-wall.
    let mut spans: Vec<(f64, f64)> = Vec::new();
    let mut push_span = |placement: &Option<OpeningPlacement>, width: f32| {
        let x = world_x(placement);
        spans.push((x - width as f64 / 2.0, x + width as f64 / 2.0));
    };
    push_span(&w.placement, w.width_m);
    push_span(&d.placement, d.width_m);
    for pane in s.windows.iter().skip(1) {
        push_span(&pane.placement, pane.width_m);
    }
    spans.sort_by(|a, b| a.0.total_cmp(&b.0));
    for pair in spans.windows(2) {
        assert!(
            pair[0].1 <= pair[1].0 + 1e-3,
            "openings must not overlap: {spans:?}"
        );
    }
    // And nothing hangs over the notch gap (4.0..5.0).
    for (lo, hi) in &spans {
        assert!(
            *hi <= 4.0 + 1e-3 || *lo >= 5.0 - 1e-3,
            "no opening spans the trimmed-away gap: {spans:?}"
        );
    }
}

/// THE REAL-RECORD reproduction (50 Glengara Park, field report 2026-08-08):
/// the east wall carries a door+sidelights (the front door, at the position
/// of its recess) and a standalone window further south. Trimming the recess
/// notch must (a) leave the window at its world position on the surviving
/// remnant, and (b) re-home the doorset onto the notch's new BACK wall — not
/// teleport both onto the shortened kept wall where they collide. Runs only
/// with `BER_RESIZE_RECORD` pointing at the backed-up Glengara data.json.
#[test]
fn real_record_trim_recess_rehomes_the_doorset() {
    use ber_model::ber::fenestration::OpeningPlacement;
    let Ok(path) = std::env::var("BER_RESIZE_RECORD") else {
        eprintln!("BER_RESIZE_RECORD not set — skipping");
        return;
    };
    let json = std::fs::read_to_string(&path).expect("read record");
    let ber: ber_model::ber::ber_struct::Ber = serde_json::from_str(&json).expect("parse");
    let id = ber.id;
    let conn = crate::engine::open_db(":memory:").unwrap();
    {
        let repo = crate::engine::ber_repository::BerRepository::new(&conn);
        repo.init_db().unwrap();
        repo.upsert(&crate::engine::ber_repository::BerRecord {
            id,
            name: ber.address.clone(),
            date_assessed: chrono::NaiveDate::from_ymd_opt(2026, 8, 8).unwrap(),
            data: ber.clone(),
        })
        .unwrap();
    }
    let mut c = AppController::new(conn);
    c.open_ber(&id).unwrap();
    c.materialize();

    // World position of every wall opening, keyed by id.
    let world_pos = |c: &AppController| -> std::collections::HashMap<ItemId, (f64, f64)> {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        let host = |wid: &ItemId| {
            s.walls
                .regions
                .iter()
                .find(|r| r.id == *wid)
                .and_then(|r| r.base_frame())
        };
        let mut out = std::collections::HashMap::new();
        let mut put = |oid: ItemId, placement: &Option<OpeningPlacement>| {
            if let Some(OpeningPlacement::Wall {
                wall_id, along_m, ..
            }) = placement
            {
                if let Some((origin, (ux, uy), _, _)) = host(wall_id) {
                    out.insert(
                        oid,
                        (
                            origin.x + ux * *along_m as f64,
                            origin.y + uy * *along_m as f64,
                        ),
                    );
                }
            }
        };
        for w in &s.windows {
            put(w.id, &w.placement);
        }
        for d in &s.doors {
            put(d.id, &d.placement);
        }
        out
    };
    let before = world_pos(&c);
    let (door_id, aid, sidelight_id, lone_window_id) = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        let d = &s.doors[0];
        let aid = d.assembly_id.expect("front door is a doorset");
        let pane = s
            .windows
            .iter()
            .find(|w| w.assembly_id == Some(aid))
            .expect("sidelight");
        // The standalone window on the same (east) wall as the door.
        let east_x = before[&d.id].0;
        let lone = s
            .windows
            .iter()
            .find(|w| {
                w.assembly_id.is_none()
                    && before
                        .get(&w.id)
                        .is_some_and(|(x, _)| (x - east_x).abs() < 0.05)
            })
            .expect("standalone window on the east wall");
        (d.id, aid, pane.id, lone.id)
    };

    // Trim the door's RECESS: a 0.6 m deep notch spanning y 6.76..8.67 on the
    // east wall (x = 7.295) — right through the doorset's position.
    c.set_edit_mode(EditTools::TrimOrtho);
    c.apply_trim_stroke(&[
        Point2f32::new(7.35, 6.76),
        Point2f32::new(6.695, 6.76),
        Point2f32::new(6.695, 8.67),
        Point2f32::new(7.35, 8.67),
    ])
    .expect("recess trim applies");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();

    let after = world_pos(&c);
    // (a) The standalone window stayed at its world position.
    let (bx, by) = before[&lone_window_id];
    let (ax, ay) = after[&lone_window_id];
    assert!(
        (ax - bx).abs() < 0.05 && (ay - by).abs() < 0.05,
        "the untouched window stayed put (was ({bx:.2},{by:.2}), now ({ax:.2},{ay:.2}))"
    );
    // (b) The doorset re-homed onto the recess back wall: x ≈ 6.695, same y.
    let (dax, day) = after[&door_id];
    let (_, dby) = before[&door_id];
    assert!(
        (dax - 6.695).abs() < 0.05,
        "door re-homed onto the recess back wall (x = {dax:.3})"
    );
    assert!(
        (day - dby).abs() < 0.2,
        "door kept its position along the wall (was y {dby:.2}, now {day:.2})"
    );
    let (sax, _) = after[&sidelight_id];
    assert!(
        (sax - 6.695).abs() < 0.05,
        "sidelight followed its door onto the back wall (x = {sax:.3})"
    );
    // (c) The assembly is still rigid and nothing overlaps the lone window.
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    assert_eq!(
        s.doors[0].assembly_id,
        Some(aid),
        "doorset survived as an assembly"
    );
    let door_span = {
        let (_, y) = after[&door_id];
        let hw = s.doors[0].width_m as f64 / 2.0;
        (y - hw, y + hw)
    };
    let lone_span = {
        let (_, y) = after[&lone_window_id];
        let w = s
            .windows
            .iter()
            .find(|w| w.id == lone_window_id)
            .unwrap()
            .width_m as f64;
        (y - w / 2.0, y + w / 2.0)
    };
    assert!(
        door_span.1 <= lone_span.0 + 1e-3 || lone_span.1 <= door_span.0 + 1e-3,
        "the doorset and the window do not intersect ({door_span:?} vs {lone_span:?})"
    );
}

// ── Move opening to another wall ────────────────────────────────────────────

/// "Move to wall…": a doorset on the south wall transfers RIGIDLY onto a
/// trimmed recess's back wall — the user's Glengara flow (the front door
/// belongs on the recess). Members keep sills + relative offsets; the anchors
/// follow, so a re-derive keeps it there; one undo returns it.
#[test]
fn move_doorset_onto_the_recess_back_wall() {
    use ber_model::ber::fenestration::OpeningPlacement;
    use ber_model::ber::openings::OpeningRef;
    let mut c = controller_with_doorset(); // 0.9 door + 0.4 lights at along 5.0, south wall
                                           // Trim a recess into the EAST wall (x=10): 1.9 wide, 0.7 deep.
    c.set_edit_mode(EditTools::TrimOrtho);
    c.apply_trim_stroke(&[
        Point2f32::new(10.05, 4.0),
        Point2f32::new(9.3, 4.0),
        Point2f32::new(9.3, 5.9),
        Point2f32::new(10.05, 5.9),
    ])
    .expect("recess trims");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();

    // Select the door panel in the (conceptual) elevation and arm the move.
    let panel_id = c.current_record.as_ref().unwrap().data.storeys[0].doors[0].id;
    c.set_openings_mode(true);
    c.elevation_selection = Some(OpeningRef::Door(panel_id));
    c.elevation_wall = c.current_record.as_ref().unwrap().data.storeys[0]
        .walls
        .regions
        .first()
        .map(|r| r.id);
    c.begin_move_selected_opening();
    assert!(c.opening_move_pending());
    assert!(
        c.elevation_wall().is_none(),
        "elevation closed for the pick"
    );

    // Tap the recess BACK wall (x=9.3, mid-height y=4.95).
    c.move_opening_tap(9.3, 4.95, 0.3).expect("transfer lands");
    assert!(!c.opening_move_pending());
    c.materialize();

    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let world = |placement: &Option<OpeningPlacement>| -> (f64, f64) {
        let Some(OpeningPlacement::Wall {
            wall_id, along_m, ..
        }) = placement
        else {
            panic!("wall placement")
        };
        let (origin, (ux, uy), _, _) = s
            .walls
            .regions
            .iter()
            .find(|r| r.id == *wall_id)
            .unwrap()
            .base_frame()
            .unwrap();
        (
            origin.x + ux * *along_m as f64,
            origin.y + uy * *along_m as f64,
        )
    };
    let d = &s.doors[0];
    let (dx, dy) = world(&d.placement);
    assert!(
        (dx - 9.3).abs() < 1e-3,
        "door on the recess back wall (x = {dx:.3})"
    );
    // Panes came along, flush, on the SAME wall.
    let aid = d.assembly_id.unwrap();
    for pane in s.windows.iter().filter(|w| w.assembly_id == Some(aid)) {
        let (px, py) = world(&pane.placement);
        assert!(
            (px - 9.3).abs() < 1e-3,
            "pane followed onto the back wall (x = {px:.3})"
        );
        let sill = match &pane.placement {
            Some(OpeningPlacement::Wall { sill_m, .. }) => *sill_m,
            _ => 0.0,
        };
        if sill < 1.0 {
            // A sidelight (sill at the floor): flush against a door edge.
            let gap = ((py - dy).abs() - (d.width_m + pane.width_m) as f64 / 2.0).abs();
            assert!(gap < 1e-3, "sidelight flush (gap err {gap:.4})");
        } else {
            // The transom (at the door's top): centred over the assembly.
            assert!(
                (py - dy).abs() < 0.5,
                "transom stayed over the doorset (offset {:.3})",
                py - dy
            );
        }
    }
    // Undo returns the doorset to the south wall.
    c.undo().unwrap();
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let Some(OpeningPlacement::Wall { wall_id, .. }) = s.doors[0].placement else {
        panic!()
    };
    let (_, (ux, _), _, _) = s
        .walls
        .regions
        .iter()
        .find(|r| r.id == wall_id)
        .unwrap()
        .base_frame()
        .unwrap();
    assert!(
        ux.abs() > 0.9,
        "undo restored the doorset to the horizontal south wall"
    );
}

/// A target wall too short for the body is refused: model untouched, the
/// move still armed for another tap; a MISS cancels the move.
#[test]
fn move_opening_refuses_too_short_and_cancels_on_miss() {
    use ber_model::ber::openings::OpeningRef;
    let mut c = controller_with_doorset(); // total doorset width 1.7 + margins
                                           // Trim a NARROW recess (0.6 wide) into the east wall — too short for it.
    c.set_edit_mode(EditTools::TrimOrtho);
    c.apply_trim_stroke(&[
        Point2f32::new(10.05, 4.0),
        Point2f32::new(9.3, 4.0),
        Point2f32::new(9.3, 4.6),
        Point2f32::new(10.05, 4.6),
    ])
    .expect("narrow recess trims");
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.mark_dirty().unwrap();
    c.materialize();
    let panel_id = c.current_record.as_ref().unwrap().data.storeys[0].doors[0].id;
    c.set_openings_mode(true);
    c.elevation_selection = Some(OpeningRef::Door(panel_id));
    c.begin_move_selected_opening();
    let err = c.move_opening_tap(9.3, 4.3, 0.25);
    assert!(err.is_err(), "1.7 m doorset can't fit a 0.6 m wall");
    assert!(
        c.opening_move_pending(),
        "still armed — the assessor can tap a better wall"
    );
    // The doorset never left the south wall.
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let Some(ber_model::ber::fenestration::OpeningPlacement::Wall { wall_id, .. }) =
        s.doors[0].placement
    else {
        panic!()
    };
    let (_, (ux, _), _, _) = s
        .walls
        .regions
        .iter()
        .find(|r| r.id == wall_id)
        .unwrap()
        .base_frame()
        .unwrap();
    assert!(ux.abs() > 0.9, "doorset untouched on the south wall");
    // A tap on empty space cancels the armed move.
    let err = c.move_opening_tap(5.0, 3.0, 0.25);
    assert!(err.is_err(), "miss reports the cancel");
    assert!(!c.opening_move_pending(), "move disarmed");
}

/// FIELD REPORT (Glengara bay): lowering a BAY's ceiling via a step line at
/// the bay's base said "No resolved ceiling under that area". The side
/// sampler took the bbox-middle of the strip — outside the bay, which only
/// spans part of the house's width. The sampler now clips the resolved
/// ceilings to the line's side and picks an interior point, so the bay flow
/// works end-to-end: current height reads, the absolute assign lands, and
/// the bay's ceiling region ends at the typed height.
#[test]
fn bay_ceiling_step_line_reads_height_and_lowers_the_bay() {
    use document::LineSide;
    let mut c = AppController::new(crate::engine::open_db(":memory:").unwrap());
    let _ = c.create_ber(
        "Bay".into(),
        chrono::NaiveDate::from_ymd_opt(2026, 1, 1).unwrap(),
    );
    // A Glengara-like plan: 6.1 × 11.6 body with a 2.3 × 0.8 bay on the north.
    c.document.floor_plan = FloorPlan::from_points_to_orthogonal(
        &[
            Point2f32::new(0.0, 0.0),
            Point2f32::new(6.1, 0.0),
            Point2f32::new(6.1, 11.6),
            Point2f32::new(5.4, 11.6),
            Point2f32::new(5.4, 12.4),
            Point2f32::new(3.1, 12.4),
            Point2f32::new(3.1, 11.6),
            Point2f32::new(0.0, 11.6),
            Point2f32::new(0.05, 0.05),
        ],
        0.2,
        true,
    )
    .unwrap();
    c.document.dimensioning.scale_set = true;
    c.document.dimensioning.known_params = c.document.floor_plan.all_active_params();
    c.commit_to_ber().unwrap();
    c.set_default_ceiling_height(2.42).unwrap();
    c.materialize();

    // The step LINE along the bay's base (y = 11.6), lowering the bay side.
    c.pending_ceiling_step = Some(PendingCeilingStep::Amount {
        axis: ParameterAxis::Y,
        coord_m: 11.6,
        side: LineSide::Greater,
        snap: None,
    });
    let current = c
        .ceiling_step_current_height()
        .expect("the bay side has a resolved ceiling (the field failure)");
    assert!(
        (current - 2.42).abs() < 1e-3,
        "reads the default height (got {current})"
    );
    c.assign_ceiling_step_absolute(1.9)
        .expect("bay lowers to the typed height");
    c.materialize();
    let storey = &c.current_record.as_ref().unwrap().data.storeys[0];
    // The ceiling piece over the bay sits at 1.9; the body stays at 2.42.
    let z_at = |x: f64, y: f64| {
        storey
            .ceilings
            .top_z_at(domain::points::Point2f64::new(x, y))
            .unwrap_or(f64::NAN)
    };
    assert!(
        (z_at(4.25, 12.0) - 1.9).abs() < 1e-3,
        "bay ceiling at 1.9 (got {})",
        z_at(4.25, 12.0)
    );
    assert!(
        (z_at(3.0, 6.0) - 2.42).abs() < 1e-3,
        "main body stays at 2.42 (got {})",
        z_at(3.0, 6.0)
    );
}

/// Structure "Divide wall": select one wall, type two cut distances, Split →
/// the wall resolves as THREE regions with the typed spans, the middle one
/// selected for attribution; each part then holds its own construction. The
/// exposure-mode ergonomics (handles/typed bounds), now for structure.
#[test]
fn structure_divide_splits_the_selected_wall() {
    let mut c = dimensioned_square_controller(); // 10×10
    c.set_default_ceiling_height(2.4).unwrap();
    c.materialize();
    // Select the south wall's region.
    let south_id = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        s.walls
            .regions
            .iter()
            .find(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
            .unwrap()
            .id
    };
    c.structure_selected.insert(south_id);
    assert!(
        c.structure_can_divide(),
        "one wall selected → divide offered"
    );
    c.begin_structure_divide();
    let v = c.structure_divide_view().expect("divide open");
    assert!((v.span.0 - 0.0).abs() < 1e-3 && (v.span.1 - 10.0).abs() < 1e-3);
    // Type the two cuts: 3 m and 5 m from the piece's left end.
    c.set_structure_divide_bound(true, 3.0).unwrap();
    c.set_structure_divide_bound(false, 5.0).unwrap();
    c.apply_structure_divide().expect("split lands");
    // The south base line now resolves as three regions: 0..3, 3..5, 5..10.
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let sd = &c.document.storeys[0];
    let mut spans: Vec<(f32, f32)> = s
        .walls
        .regions
        .iter()
        .filter(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
        .filter_map(|r| {
            sd.recover_wall_region_span(r)
                .map(|(_, s0, s1, _)| (s0, s1))
        })
        .collect();
    spans.sort_by(|a, b| a.0.total_cmp(&b.0));
    assert_eq!(spans.len(), 3, "three pieces: {spans:?}");
    for (got, want) in spans.iter().zip([(0.0, 3.0), (3.0, 5.0), (5.0, 10.0)]) {
        assert!(
            (got.0 - want.0).abs() < 0.02 && (got.1 - want.1).abs() < 0.02,
            "piece {got:?} ≈ {want:?}"
        );
    }
    // The MIDDLE piece is selected, ready for "Edit attributes".
    assert_eq!(c.structure_selected.len(), 1, "middle piece selected");
    let sel = *c.structure_selected.iter().next().unwrap();
    let (_, s0, s1, _) = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        let r = s.walls.regions.iter().find(|r| r.id == sel).unwrap();
        c.document.storeys[0].recover_wall_region_span(r).unwrap()
    };
    assert!(
        (s0 - 3.0).abs() < 0.02 && (s1 - 5.0).abs() < 0.02,
        "selected span {s0:.2}..{s1:.2}"
    );
    // Undo restores the single full-length wall.
    c.undo().unwrap();
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let south: Vec<_> = s
        .walls
        .regions
        .iter()
        .filter(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
        .collect();
    assert_eq!(south.len(), 1, "undo re-joined the wall");
}

/// Divide with NO cut placed (both bounds still at the span ends) refuses
/// with a helpful message; the drag-handle path clamps into the span.
#[test]
fn structure_divide_needs_a_cut_and_clamps() {
    let mut c = dimensioned_square_controller();
    c.set_default_ceiling_height(2.4).unwrap();
    c.materialize();
    let south_id = {
        let s = &c.current_record.as_ref().unwrap().data.storeys[0];
        s.walls
            .regions
            .iter()
            .find(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
            .unwrap()
            .id
    };
    c.structure_selected.insert(south_id);
    c.begin_structure_divide();
    assert!(c.apply_structure_divide().is_err(), "no cut placed yet");
    // A typed bound beyond the span clamps to it (no cut → still refused).
    c.set_structure_divide_bound(true, 99.0).unwrap();
    assert!(
        c.apply_structure_divide().is_err(),
        "clamped to the end = no cut"
    );
    // The clamp parked BOTH bounds at the far end — grab there, drag inward.
    c.structure_divide_pointer_down(10.0, 0.0, 0.5);
    c.structure_divide_pointer_drag(4.0, 0.2);
    c.structure_divide_pointer_up();
    c.apply_structure_divide().expect("dragged cut lands");
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    let south: Vec<_> = s
        .walls
        .regions
        .iter()
        .filter(|r| r.polygon.exterior.iter().all(|p| p.y.abs() < 1e-3))
        .collect();
    assert_eq!(south.len(), 2, "one cut → two pieces");
}

/// The pin dropdown's ➕ edit: an already-added object's count / note update
/// in place and new photos APPEND — no duplicate object needed (the field
/// complaint), and one undo restores the original.
#[test]
fn object_edit_updates_in_place_and_appends_photos() {
    use ber_model::ber::objects::{ObjectKind, VentKind};
    let mut c = dimensioned_square_controller();
    c.materialize();
    // Open a room pin and add a vent with a note.
    c.objects_pointer_down(5.0, 5.0, 0.5);
    c.add_object(
        ObjectKind::Vent(VentKind::Open),
        1,
        Some("living room".into()),
        None,
        None,
        vec![],
    );
    let (room_id, object_id) = {
        let room = c.active_object_room_view().expect("room open");
        (room.id, room.objects[0].id)
    };
    // Edit: bump the count, extend the note.
    c.begin_edit_object(room_id, object_id);
    let v = c.object_edit_view().expect("edit open");
    assert_eq!(v.count, 1);
    assert_eq!(v.note, "living room");
    c.update_object(
        2,
        Some("living room — behind the couch".into()),
        None,
        None,
        vec![],
    )
    .expect("edit applies");
    assert!(c.object_edit_view().is_none(), "edit closed");
    {
        let room = c.active_object_room_view().unwrap();
        assert_eq!(room.objects.len(), 1, "no duplicate object");
        assert_eq!(room.objects[0].count, 2);
    }
    let note = {
        let record = c.current_record.as_ref().unwrap();
        record
            .data
            .object_rooms_iter()
            .find(|r| r.id == room_id)
            .unwrap()
            .objects[0]
            .note
            .clone()
    };
    assert_eq!(note.as_deref(), Some("living room — behind the couch"));
    // Undo restores the original values.
    c.undo().unwrap();
    let room = c.active_object_room_view().unwrap();
    assert_eq!(room.objects[0].count, 1);
}

/// THE FOUR-BUNGALOW ROOF FAILURE: in the roof step's Classify stage the
/// assessor naturally SELECTS the regions to roof — but the old one-button
/// stage committed selected FLAT ceilings as finished FLAT roofs, and stage B
/// (Gable/Hip) then had nothing left to offer. The new "None — pick a roof
/// style next" advances WITHOUT committing, discarding the misleading
/// selection, so the gable flow proceeds normally.
#[test]
fn roof_skip_follow_reaches_the_gable_flow_without_flat_committing() {
    let mut c = dimensioned_square_controller();
    c.set_default_ceiling_height(2.4).unwrap();
    c.set_roof_mode(true);
    c.confirm_all_storeys_added_roof();
    assert_eq!(c.roof_stage(), Some(RoofStage::Classify));
    // The field mistake: select the (flat) ceiling region in Classify…
    c.roof_region_tap(5.0, 5.0, 0.5);
    assert!(
        c.roof_regions_view().iter().any(|r| r.selected),
        "region selected in Classify"
    );
    // …but take the NEW escape instead of committing it as a flat roof.
    c.skip_roof_follow();
    assert_eq!(c.roof_stage(), Some(RoofStage::Section));
    assert!(
        c.current_record.as_ref().unwrap().data.roof.is_empty(),
        "nothing committed — no phantom flat roof"
    );
    assert!(
        !c.roof_regions_view().iter().any(|r| r.selected),
        "the misleading Classify selection was discarded"
    );
    // Stage B proceeds to a real gable.
    c.roof_region_tap(5.0, 5.0, 0.5);
    c.pick_roof_section_style(RoofSectionStyle::GableBoth)
        .unwrap();
    c.assign_roof_section_pitch(40.0).unwrap();
    c.confirm_roof_section().unwrap();
    let roof = &c.current_record.as_ref().unwrap().data.roof;
    assert_eq!(roof.areas.len(), 1);
    assert!(
        !matches!(roof.areas[0].shape, ber_model::ber::roof::RoofShape::Flat),
        "a pitched roof, not the phantom flat: {:?}",
        roof.areas[0].shape
    );
}

/// Stage-B ridge placement: DRAG moves the generated ridge laterally with a
/// snap to the section's wall lines; "centre between 2 points" (snapped
/// taps) centres it midway; the commit bakes the shift into the stored
/// ridge + apexes; browsing candidates resets the shift.
#[test]
fn roof_ridge_moves_by_drag_and_centres_between_points() {
    let mut c = dimensioned_square_controller(); // 10×10, ridge axis X → lateral y
    c.set_default_ceiling_height(2.4).unwrap();
    c.set_roof_mode(true);
    c.confirm_all_storeys_added_roof();
    c.skip_roof_follow();
    c.roof_region_tap(5.0, 5.0, 0.5);
    c.pick_roof_section_style(RoofSectionStyle::GableBoth)
        .unwrap();
    c.assign_roof_section_pitch(40.0).unwrap();
    let before = c.pending_roof_section_view().unwrap().ridge_lines[0];
    assert!(
        ((before.0).1 - 5.0).abs() < 1e-6,
        "generated ridge starts on the midline"
    );
    // Grab the ridge at its midpoint and drag 2 m north (no snap target at 7).
    c.roof_ridge_pointer_down(5.0, 5.0, 0.3);
    c.roof_ridge_pointer_drag(5.0, 7.0);
    c.roof_ridge_pointer_up();
    let dragged = c.pending_roof_section_view().unwrap().ridge_lines[0];
    assert!(
        ((dragged.0).1 - 7.0).abs() < 1e-3,
        "ridge followed the drag (y = {})",
        (dragged.0).1
    );
    // Drag NEAR the north wall — it snaps onto y = 10's wall line? The wall
    // is the section extent, clamp+snap land it exactly on 10 only if within
    // tol; drag to 9.9 → snaps to 10.0.
    c.roof_ridge_pointer_down(5.0, 7.0, 0.3);
    c.roof_ridge_pointer_drag(5.0, 9.9);
    c.roof_ridge_pointer_up();
    let snapped = c.pending_roof_section_view().unwrap().ridge_lines[0];
    assert!(
        ((snapped.0).1 - 10.0).abs() < 1e-3,
        "ridge snapped to the wall line (y = {})",
        (snapped.0).1
    );
    // Centre between two snapped points: the south-west corner and the north
    // wall's midpoint → centre y = 5.
    c.begin_roof_centre_pick();
    c.roof_centre_pick_tap(0.05, 0.05); // snaps to (0,0)
    c.roof_centre_pick_tap(5.0, 9.95); // snaps onto the y=10 wall
    let centred = c.pending_roof_section_view().unwrap().ridge_lines[0];
    assert!(
        ((centred.0).1 - 5.0).abs() < 1e-3,
        "ridge centred between the picks (y = {})",
        (centred.0).1
    );
    // Move it off-centre again, then COMMIT: the stored apexes carry the move.
    c.roof_ridge_pointer_down(5.0, 5.0, 0.3);
    c.roof_ridge_pointer_drag(5.0, 6.5);
    c.roof_ridge_pointer_up();
    c.confirm_roof_section().unwrap();
    let roof = &c.current_record.as_ref().unwrap().data.roof;
    assert_eq!(roof.areas.len(), 1);
    let apex_ys: Vec<f64> = roof.areas[0]
        .ridge
        .iter()
        .flat_map(|r| [r.0.y, r.1.y])
        .collect();
    assert!(
        apex_ys.iter().all(|y| (y - 6.5).abs() < 1e-3),
        "committed ridge at the moved position: {apex_ys:?}"
    );
}

/// Solar hot water is its own category: Tubes + Controls are offered there
/// (each with the mandatory photo), PV/Battery stay under Solar PV, and a
/// legacy undifferentiated SolarThermal record groups under the new category.
#[test]
fn solar_hot_water_category_splits_tubes_and_controls() {
    use ber_model::ber::objects::{ObjectCategory, ObjectKind, SolarPanelKind};
    assert!(ObjectCategory::ALL.contains(&ObjectCategory::SolarWaterHeating));
    let hw = ObjectCategory::SolarWaterHeating.subtypes();
    assert_eq!(
        hw,
        vec![
            ObjectKind::SolarPanel(SolarPanelKind::SolarTubes),
            ObjectKind::SolarPanel(SolarPanelKind::SolarControls),
        ]
    );
    let pv = ObjectCategory::SolarPanel.subtypes();
    assert!(
        !pv.contains(&ObjectKind::SolarPanel(SolarPanelKind::SolarThermal)),
        "the undifferentiated legacy kind is no longer offered"
    );
    // Category grouping: new kinds + the legacy one live under hot water.
    for k in [
        SolarPanelKind::SolarTubes,
        SolarPanelKind::SolarControls,
        SolarPanelKind::SolarThermal,
    ] {
        assert_eq!(
            ObjectKind::SolarPanel(k).category(),
            ObjectCategory::SolarWaterHeating
        );
    }
    assert_eq!(
        ObjectKind::SolarPanel(SolarPanelKind::Photovoltaic).category(),
        ObjectCategory::SolarPanel
    );
    // Photos stay mandatory; no battery-style kWh demanded.
    assert!(ObjectKind::SolarPanel(SolarPanelKind::SolarTubes).photo_required(true));
    assert!(!ObjectKind::SolarPanel(SolarPanelKind::SolarControls).kwh_required());
    assert_eq!(
        ObjectKind::SolarPanel(SolarPanelKind::SolarTubes).label(),
        "Solar hot water (Tubes)"
    );
}

/// Solar hot-water TUBES record their collector area: required to add,
/// stored on the object, editable via the per-object edit; the count is the
/// number of tubes. (The roof pitch comes from the pin's 3D surface pick,
/// as for any roof-mounted object.)
#[test]
fn solar_tubes_record_and_edit_the_collector_area() {
    use ber_model::ber::objects::{ObjectKind, SolarPanelKind};
    let mut c = dimensioned_square_controller();
    c.materialize();
    c.objects_pointer_down(5.0, 5.0, 0.5);
    let tubes = ObjectKind::SolarPanel(SolarPanelKind::SolarTubes);
    assert!(tubes.area_required(), "tubes demand the collector area");
    c.add_object(tubes.clone(), 20, None, None, Some(3.8), Vec::new());
    let (room_id, object_id) = {
        let room = c.active_object_room_view().unwrap();
        (room.id, room.objects[0].id)
    };
    {
        let record = c.current_record.as_ref().unwrap();
        let o = &record
            .data
            .object_rooms_iter()
            .find(|r| r.id == room_id)
            .unwrap()
            .objects[0];
        assert_eq!(o.count, 20, "count = number of tubes");
        assert_eq!(o.area_m2, Some(3.8));
    }
    // Edit the area in place.
    c.begin_edit_object(room_id, object_id);
    let v = c.object_edit_view().unwrap();
    assert!(v.area_required);
    assert_eq!(v.area_m2, Some(3.8));
    c.update_object(20, None, None, Some(4.2), vec![]).unwrap();
    let record = c.current_record.as_ref().unwrap();
    let o = &record
        .data
        .object_rooms_iter()
        .find(|r| r.id == room_id)
        .unwrap()
        .objects[0];
    assert_eq!(o.area_m2, Some(4.2), "area edited in place");
}

/// The EXTRA-pictures bucket: untagged `Ber::photos` entries (side: None)
/// are the general bucket — the panel view returns exactly those, external
/// side shots stay out of it, and the shared id-keyed remove works.
#[test]
fn extra_photos_bucket_holds_untagged_shots() {
    use ber_model::ber::common::{Evidence, ItemId};
    let mut c = dimensioned_square_controller();
    c.materialize();
    let (extra_id, side_id) = (ItemId::default(), ItemId::default());
    {
        let record = c.current_record.as_mut().unwrap();
        record.data.photos.push(Evidence {
            id: extra_id,
            file_path: "/tmp/extra.jpg".into(),
            thumbnail_path: None,
            description: Some("meter box".into()),
            side: None,
            ..Default::default()
        });
        record.data.photos.push(Evidence {
            id: side_id,
            file_path: "/tmp/front.jpg".into(),
            thumbnail_path: None,
            description: None,
            side: Some(ber_model::ber::common::ExternalSide::Front),
            ..Default::default()
        });
    }
    let extra = c.extra_photos_view();
    assert_eq!(extra.len(), 1, "only the untagged shot is in the bucket");
    assert_eq!(extra[0].id, extra_id);
    assert_eq!(extra[0].description.as_deref(), Some("meter box"));
    // The shared remove drops it; the tagged side shot stays.
    c.remove_external_photo(extra_id);
    assert!(c.extra_photos_view().is_empty());
    assert_eq!(
        c.current_record.as_ref().unwrap().data.photos.len(),
        1,
        "the front-side shot survives"
    );
}

/// 26 BIRCHFIELD ROAD's infinite lines: a 2 mm typed-dimension mismatch
/// between a phase ring and the outline edge partitioned a 2.5 m × 2 mm
/// floor+ceiling strip, whose near-degenerate plane drew lines across the
/// whole 3D view. The raised thickness guard drops the strip at partition
/// time — and because floors/ceilings re-derive every resolve, an already
/// scarred record heals on its next materialize.
#[test]
fn millimetre_phase_mismatch_partitions_without_a_sliver() {
    let mut c = dimensioned_10x6_controller();
    c.set_default_ceiling_height(2.4).unwrap();
    c.materialize();
    // A phase zone whose north edge sits 2 mm SHORT of the outline's y=6 —
    // the Birchfield-style entry mismatch.
    c.phase_regions.insert(
        0,
        vec![document::PhaseRegion {
            polygon: vec![
                Point2f64::new(0.0, 3.0),
                Point2f64::new(10.0, 3.0),
                Point2f64::new(10.0, 5.998),
                Point2f64::new(0.0, 5.998),
            ],
            phase: ConstructionPhase::Extension1,
        }],
    );
    c.mark_dirty().unwrap();
    c.materialize();
    let s = &c.current_record.as_ref().unwrap().data.storeys[0];
    for (name, regions) in [(
        "floors",
        &s.floors
            .regions
            .iter()
            .map(|r| {
                r.polygon
                    .exterior()
                    .coords()
                    .map(|p| (p.x, p.y))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>(),
    )] {
        for ring in regions.iter() {
            let ys: Vec<f64> = ring.iter().map(|p| p.1).collect();
            let span = ys.iter().cloned().fold(f64::MIN, f64::max)
                - ys.iter().cloned().fold(f64::MAX, f64::min);
            assert!(
                span > 0.02,
                "no near-degenerate {name} strip survives (y-span {span:.4})"
            );
        }
    }
    for r in &s.ceilings.regions {
        let ys: Vec<f64> = r.polygon.exterior.iter().map(|p| p.y).collect();
        let span = ys.iter().cloned().fold(f64::MIN, f64::max)
            - ys.iter().cloned().fold(f64::MAX, f64::min);
        assert!(
            span > 0.02,
            "no near-degenerate ceiling strip survives (y-span {span:.4})"
        );
    }
}
